window.__D("text/keter-shem-tov/c003",{"p":[[300010480,"שצח-ב\n\n[<b>הנה</b>] &lt;מה ש&gt;אמרו רז\"ל ע\"י תשובה זדונות נעשו לו כזכיות. כי הנה השב צריך שיהיה נמאס אצלו הדבר שנכשל בו, כי אע\"פ שכאשר עדיין לא חטא ארז\"ל אל יאמר אדם אי אפשי בבשר חזיר כו', מ\"מ כשחטא צריך שיהיה נמאס ממש אצלו הדבר ההוא. וזהו נעשים לו כזכיות, שאליהם אין יצה\"ר, כך להעבירות לא יהיה לו יצה\"ר.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י סי</b>'<b> קטז (שלהי קכו)</b>\n<i>ע\"י תשובה כו'</i> – יומא פו, ב. <i>אל יאמר אדם כו'</i> – ספרא ס\"פ קדשים.\n----- הערות וציונים -----\nבלקו\"ת לאדה\"ז פ' ואתחנן ט, ד מפורש בשם הרה\"מ (הובא בהוספות למדל\"י-או\"ת סי' מ, ועיי\"ש בהערות)."]]],[300010481,"שצט\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; הוי ממעט בעסק ועסוק בתורה, &lt;קשה&gt; דהוי ליה למימר הוי ממעט בעסק דרך ארץ ועסוק בתורה, כי עסק ר\"ל דהוא עסק התורה. וצ\"ל האמת כך הוא, דשמעתי <i>ממורי</i> &lt;הבעש\"ט&gt; על קושית הט\"ז, אחד המרבה ואחד הממעיט ובלבד שיכוין כו' למה שוין במכוין וכו', וביאר כי צריך ללמוד ולהתפלל עם מוחין, משא\"כ כו', וא\"כ אם ממעיט כדי שיהיו לו מוחין לכוין היטב שוה למי שיש לו מוחין טובים שיוכל להרבות, וז\"ש ובלבד שיכוין וכו' <span data-k=\"sm\">[ודפח\"ח] </span>. . .\n<b>וז\"ש</b> הוי ממעט בעסק, היינו בתורה, כדי שיוכל לעסוק בתורה להעמיק בדחילו ורחימו, <span data-k=\"sm\">[וכמו שכתב הט\"ז באו\"ח סי' מז ענין לעסו\"ק בדברי תורה וכו' יעו\"ש]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י חקת קמה</b>,<b> סע</b>\"<b>ד (תקמא</b>,<b> א)</b>\n<i>הוי ממעט כו'</i> – אבות פ\"ד מ\"י. <i>קושית הט\"ז</i> – או\"ח סי' א אות ג. <i>אחד המרבה כו'</i> – מנחות קי, א. <i>הט\"ז באו\"ח סי' מז</i> – אות א.\n----- הערות וציונים -----\nראה לעיל סי' קכ."]]],[300010482,"ת-א\n\n<b>יחשוב</b> שעולם הדיבור מדבר בו וזולתו אי אפשר לדבר, כמו שכתוב אדנ-י שפתי תפתח. וגם כן מחשבתו א\"א להיות כ\"א ע\"י עולם המחשבה <span data-k=\"sm\">[והוא כשופר, כי מה שתוקעין בתוכו אותו הקול הוא מוציא, ואם יפרוש ממנו התוקע אז לא יצא הקול, כך בהעדר ח\"ו ית' ממנו אינו יכול לדבר ולחשוב]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י סי</b>'<b> קמו (קנד)</b>\n<i>אד' שפתי גו'</i> – תהלים נא, יז.\n----- הערות וציונים -----\nראה לעיל סי' קצח, רעג-ב, שא-ב<i>-ג</i> ותיא. ורג\"כ במדל\"י סי' קנ (קנח).\n<i>בהעדר ח\"ו כו'</i> – ראה לעיל סי' ר-א ורעג-א."]]],[300010483,"ת-ב\n\n<b>&lt;כי&gt;</b><i>[ftnref_1_פד]</i> הדיבור של ישראל הוא עולם הדיבור, כביכול, המחיה העולם, ומחשבתן הוא עולם המחשבה, וכן למעלה ממנו. ועוה\"ז מקבל אותיות הדיבור דרך אמצעות המדות &lt;חסד דין רחמים, לפי&gt; שעוה\"ז יש בו שטח וגבול צריך לקבל ע\"י המדות.\n<b>והנה</b> קדושת שבת במוסף, בכתר, &lt;שאנחנו מעלין עולם הדיבור בכתר, שאנחנו&gt; <span data-k=\"sm\">[שאנו]</span> מעלין עולם הדיבור בעולם המחשבה, ושם הבהירות גדול עד שאין נראה התחלקות המדות, &lt;כמשל השמש שאין יכולין להסתכל בו מחמת גודל הבהירות שבו, והאור היוצא ממנו יכולין להסתכל בו ולהשיגו ולהנות ממנו לסיבת מיעוט בהירותו, כי אלו היה באור בהירות כמו בשמש לא היו יכולים ג\"כ להשיגו. כמו כן שמש ומגן ה' צבאות&gt; –\n<b>(</b><i>[ftnref_2_פה]</i><b>&lt;וסוד</b> השבת, ובזהר מהו שבת שמא דקב\"ה, וארז\"ל&gt; <span data-k=\"sm\">[והנה ארז\"ל כל השומר שבת כהלכתו אפילו עובד ע\"ז כדור אנוש מוחלין לו, דאיתא מה היה העולם חסר מנוחה]</span>, בא שבת בא מנוחה <span data-k=\"sm\">[דהעולם נברא בו' ימי המעשה ובדבורו של הש\"י דהיינו אותיות התורה , ונעשה הכל מאי\"ן, אבל עדיין לא הי' כח הפועל בנפעל כי זהו קיומו]</span>, &lt;פי'&gt; כי הקב\"ה נקרא מנוחה שאין שייך בו תנועה, כי תנועה לא שייך כ\"א בדבר שהוא בזמן ובמקום, אבל הקב\"ה הוא א\"ס ואינו נעתק ממקום למקום, וגם אינו בגדר זמן.)\n<b>&lt;והנה</b> בשבת במוסף, בקדושת כתר, שאנו מעלין עולם הדיבור בעולם המחשבה, ושם הבהירות גדול עד שאין נראה התחלקות המדות&gt; –\n<b>לפי</b> זה לא ישאר חיות לעוה\"ז התחתון. ועוה\"ז הוא צורך גבוה, כי אין מלך בלא עם. ע\"כ תיכף שאנו אומרים אי\"ה מקום כבודו, ואי\"ה מרמז לג' ראשונות שאין שם התחלקות המדות, תיכף אחר זה אנו אומרים ממקומו הוא יפן ברחמים, דהיינו להשפיע טובו לכאן, לפי שאין מלך בלא עם.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י סי</b>'<b> קס (קסח)</b>\n<i>לפי שבשבילם נבראו כולם</i> – ויק\"ר לו, ד. <i>כשם שא\"א לעולם כו'</i> – תענית ג, ב. <i>במוסף בכתר שאנו כו'</i> – פע\"ח שער השבת פ\"כ. שער הכונות, ענין מוסף של שבת. <i>שמש ומגן גו'</i> – תהלים פד, יב. <i>ובזהר מהו כו'</i> – זח\"ב פח, ב. <i>כל השומר שבת כו'</i> – שבת קיח, ב. <i>דאיתא מה הי' העולם חסר כו'</i> – רש\"י בראשית ב, ב, ובמגילה ט, א בד\"ה ויכל (ושם בשם המדרש). <i>אין מלך בלא עם</i> – רב\"ח וישב לח, ל, ובכד הקמח ר\"ה-ב. <i>ואי\"ה מרמז כו'</i> – פע\"ח שם.\n----- שולי הגליון -----\n[ftn_1_פד]) <i>מכאן עד סוף הסימן יש עירבוב פרשיות</i>,<i> השמטות והוספות כו'</i>.<i> וכ\"ה במקורו במדל\"י</i>:\nנודע שכל השפעה הנשפע עלינו הוא ע\"י מדות ג' קווין, חסד דין רחמים. הנה אם באתגלייא נראה ג' קווין, מזה נודע שגם עולם העליון, שאינו מושג לנו, ג\"כ הוא במדת ג' קווין. הגם שלפי מיעוט השגתינו אינו נראה התחלקות ג' קווין הנ\"ל, הוא מחמת גודל הבהירות שבו, כמשל השמש שאין יכולים להסתכל בה מחמת גודל הבהירות שבה, והאור היוצא ממנה יכולים להסתכל בו ולהשיגו וליהנות ממנו לסיבת מיעוט בהירותו, ואילו היה באור בהירות כמו בשמש לא היו יכולים להשיגו וליהנות ממנו, כי אדרבה מחשיך היה את העינים כמו השמש. כמו כן הקב\"ה בעולם [<i>נ\"א באו\"ת</i>: כמו כן גם בעולם העליון] מחמת גודל הבהירות שבו אינו מושג, ונראה שאין בו אור אלא חשך, רק מה שיוצא ממנו, כמו הנשמה (והמחשבה) רואים שהוא מחיה את הגוף אבל לא עצמותו. . .\nונודע שישראל הם חיות של כל העולמות כולם (לפי שבשבילם נבראו כולם, ובחשבו ית' שיבראו ישראל בהתלהבות זה נבראו כל העולמות לצורך ישראל, והתלהבות זה הוא חיותם ממש, א\"כ נמצא שישראל חיותם של כל העולמות כולם) כמ\"ש חז\"ל כשם שא\"א לעולם בלא רוחות [כך א\"א לעולם בלא ישראל]. והדיבור של ישראל <i>(כבפנים עד סוף הסימן</i>,<i> בהשמטת הבא בחצאי עיגול)</i>.\n[ftn_2_פה]) <i>הכניס כאן קטע זה</i>,<i> הבא בחצאי עיגול</i>,<i> ממדל\"י סי' קכו</i>.\n----- הערות וציונים -----\n<i>כמשל השמש כו' כ\"כ הקב\"ה כו'</i> – להעיר מחולין ס' רע\"א. וראה לעיל סי' רמו.\n<i>כשם שא\"א לעולם כו'</i> – להעיר מזח\"ג רכא, ריש ע\"ב.\n<i>הדיבור של ישראל כו' עולם המחשבה</i> – ראה לעיל סי' ת-א ובהערות שם.\n<i>עולם הדיבור כ\"י המחיה העולם</i> – ראה במקורו (בקטע שנשמט לעיל לפני ד\"ה ונודע): השכינה כ\"י שהיא עולם הדיבור, דהיינו אותיות הדיבור של הקב\"ה, שבו נברא העולם, דהיינו ויאמר אלקים יהי אור וכדומה, והיא המחיה העוה\"ז.\n<i>לפי שעוה\"ז יש בו כו' צריך לקבל ע\"י המדות</i> – להעיר מע\"ח ש\"א ענף ב בענין זח\"ג רנז, ב.\n<i>והנה ארז\"ל כל כו'</i> – כנזכר בשוה\"ג זהו קטע ממדל\"י סי' קכו, ומבואר בלקו\"י-יד\"א פמ\"ה."]]],[300010484,"תא-א\n\n<b>ענין</b> השבת הוא שמתגלה השורש, והענפים <span data-k=\"sm\">[יוצאים ו]</span>חושקים אליו [. . .] &lt;פירוש&gt; שיום השבת הוא יום קדוש שמאיר ומתגלה בהירות מקדוש, שהוא הש\"י קדוש הקדושים, ומאיר על <span data-k=\"sm\">[כל]</span> הברואים <span data-k=\"sm\">[ועיקר על עמו ישראל כי זה סוד פריסות סוכת שלום . . .]</span><i>[ftnref_1_פו]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י – יד</b>\"<b>א כט</b>,<b> ב (רפמ</b>\"<b>ח)</b>\n----- שולי הגליון -----\n[ftn_1_פו]) <i>ההמשך מכאן ואילך</i>,<i> כפי שהוא במקורו</i>,<i> הובא לקמן סי' תב</i>.\n----- הערות וציונים -----"]]],[300010485,"תא-ב\n\n<b>&lt;פי'</b> כי&gt; ענין רוחניות של הכל הוא מה שנאצל במחשבה הקדומה <span data-k=\"sm\">[ית\"ש]</span>, וזהו חיות של הכל, ואח\"כ כשנברא הכל בפועל ע\"י <span data-k=\"sm\">[התעבות ו]</span>השתלשלות, אעפ\"כ אותו הרחניות נשאר למעלה נעלם בשרשו <span data-k=\"sm\">[ואינו מתגלה כלל, רק ענין]</span> החיות שבברואים הוא חיות קטן מאד שנתצמצם <span data-k=\"sm\">[ונשתלשל]</span> לשיוכל להתלבש בגופניות, <span data-k=\"sm\">[ואותו האור הנעלם לא היה יכול להתגלות ולהאיר על הברואים מפני שעדיין היה עסוק הש\"י בבריאה וצמצום לשיתגשמו הדברים]</span>. ואחר שנגמר הכל ביום ו', <span data-k=\"sm\">[אם]</span> אילו היה העולם נשאר בזה הבריאה לא היה יכול להתקיים <span data-k=\"sm\">[מחמת שמעט החיות הוא מה שבו, כי חיות שבגשמי הוא מצומצם]</span>. לזאת אחר גמר כל מעשה בראשית הבהיק הש\"י בהירות מבריאה הנעלמה, דהיינו ממה שנתהוו הברואים במחשבתו הויה רוחניות מאד, <span data-k=\"sm\">[והיא ממש עצם אלהות]</span>, והבהיק זיו הדרו מסוף העולם עד סופו בכל מעשה בראשית, והעיקר בהאדם שהוא מובחר בברואי הש\"י, הבהיק אליו בהירות משרשו הנעלם שבמחשבת הש\"י ב\"ה. וזהו ענין מה היה העולם חסר מנוחה, ר\"ל הש\"י נקרא מנוחה &lt;כו'&gt; <span data-k=\"sm\">[שאין שייך בו תנועה ממקום למקום כמו בברואים]</span>, &lt;בא שבת בא מנוחה&gt;.\n<b>&lt;היינו&gt;</b><i>[ftnref_1_פז]</i> <span data-k=\"sm\">[לזה הבהיק]</span> בהירות הוייתם &lt;של הברואים&gt; הנעלם שהוא מעצמותו יתברך, <span data-k=\"sm\">[ע\"י השתלשלות מעט]</span> ואז נתמלאו חשק ורצון אליו, כמו התינוק שהולך אחר מעשה נערות ושוכח באביו, ואח\"כ כשרואה את אביו מחמת חשקו אליו משליך הכל ומתדבק בו ורץ אליו מחמת שהוא נתח מנתחיו. כן, כביכול, כשהש\"י מבהיק זיו הדרו אל הברואים, אז מגמת פניהם אליו בתשוקה גדולה, וזה רצונו שמקוה מהם, וזה סיבת קיומם [. . .] וזה ענין השבת, שהוא השבה אל השורש, ר\"ל השורש מאיר על הענפים, והענפים חושקים ומתענגים בו ונכספים אליו, והוא אחדות עם הש\"י.\n[<b>ועל</b> <span data-k=\"sm\">ידי זה תבין מאמר הזוהר]</span> &lt;וז\"ש בזהר&gt; רזא דשבת איהו שבת דאתאחדת ברזא דאחד <span data-k=\"sm\">[וכו']</span> דהא כורסיא יקירא ברזא דאחד וכו' . . . &lt;פירוש&gt; כי הברואים נקראים בכללות כסא להש\"י, כמש\"ה השמים כסאי וגו', והברואים הם רבים מצד חיצוניותם, אבל מצד פנימיותם הם אחד, ואימתי הם אחד כשהם דבוקים וחשקם למחשבה אחת לדביקות הש\"י, נמצא כל מגמת חפצם רצון אחד וחשק אחד ולהדבק באחד, והדבקות הזה היא המאחדת ומקשרת הש\"י עם הברואים לשיתקיימו ע\"י הש\"י שהוא אחד. וזה ההתקשרות נק' ברית, לזה נק' השבת ברית עולם, שאז הוא זווגא דקוב\"ה ושכינתיה. <span data-k=\"sm\">[וכבר ידעת ענין קוב\"ה ושכינתיה]</span>, ר\"ל הקב\"ה נק' אלהות הנעלם מהברואים, ושכינתיה הוא אלהות השוכן בתחתונים והתקשרות שניהם הוא ביום השבת . . .\n<b>וכבר</b> ידעת <span data-k=\"sm\">[ושמעת]</span> שתמיד כמו שהיה פעם א' מתעורר באותו הזמן תמיד, ובפרט בענין יום השבת מוכרח להיות כן, כי בטובו מחדש בכל יום תמיד מעשה בראשית, וכל יום נברא יום א', ונברא ברואים בכל יום מדצח\"מ עד בא יום השבת, ומתעורר המקום ליתן חיות להם כמו שהיה בעת הבריאה <span data-k=\"sm\">[וענין זה הוא עיקר גדול . . .</span><i>[ftnref_2_פח]</i><span data-k=\"sm\">]</span>.",[["","","----- מקורות ומראה מקומות -----\n<i>ענין רוחניות</i> . . <i>בברואים</i>]: <b>לקו</b>\"<b>י – יד</b>\"<b>א כח</b>,<b> ד (סוף פמ</b>\"<b>ה) </b>[<i>לזה הבהיק</i>] . . <i>ביום השבת</i> . . : <b>שם כט</b>,<b> א (שם סוף פמ</b>\"<b>ו ורפמ</b>\"<b>ז) </b><i>וכבר ידעת</i> . . <i>עיקר גדול</i> . .]: <b>שם כט</b>,<b> ב (שם פמ</b>\"<b>ח</b>,<b> קרוב לתחילתו)</b>\n<i>מה הי' העולם חסר כו'</i> – רש\"י לבראשית ב, ב, ובמגילה ט, א ד\"ה ויכל (ושם בשם המדרש). <i>מאמר הזוהר כו'</i> – זח\"ב קלה, א. <i>השמים כסאי גו'</i> – ישעי' סו, א. <i>ברית עולם</i> – כי תשא לא, טז. <i>שאז הוא זווגא כו'</i> – תקו\"ז ת\"ו כא, א. זח\"ב פט, סע\"א. <i>בטובו מחדש כו'</i> – ברכת יוצר.\n----- שולי הגליון -----\n[ftn_1_פז]) <i>במקורו יש כאן המשך דברים</i>,<i> ואח\"ז כתב</i>:\nולמה נקרא שבת לשון השבה, ששבו הברואים לשרשם, ור\"ל ענין זה הוא כי אין קיום לשום נברא בעולם זולת ברצון הש\"י, כי אין לשום נברא מציאות בעולם, כי הם נבראו אחר ההעדר, דהיינו שקדם להם ההעדר, ומי שההעדר קדם לו א\"א להתקיים אם לא ברצון הש\"י שהוא קיים לעד, שהוא קדמון לכל והוא נצחי ולא סר ולא יסור. וענין הברואים היה ברצונו שרצה שיהיו, ובלתי רצונו היו כלים ואין להם מציאות כלל כמו שלא היו קודם שעלה ברצונו. ורצונו בברואים הוא התענוג מהם כשיתדבקו לשרשם על ידי תשוקתם, ועי\"ז יהיו קיימים מפני שיתדבקו בו, והוא נצחי וקיים, ועוד שימלאו רצונו שרצה בהם, ויהיה רצונו במקומו, ויהיה הבריאה, כי אין להם מציאות בלעדו מקיום רצונו בהם.\nולענין הרצון הזה שיתדבקו בשרשם הוא א\"א, כי הלא ע\"י הבריאה נתרחקו מהשורש כנ\"ל מחמת (התאות) [התהוות] הגופניות של בני אדם, ונתפרדו עי\"ז מהשורש שהוא רוחניות משורש אחדות א'. לזאת, אחר הבריאה שרצה הש\"י שיתקיימו ולא יכלו מחמת התרחקם ממנו, לזה הבהיק בהירות (<i>כבפנים</i>).\n[ftn_2_פח]) <i>בהמשך</i>: כלל העולה שיום השבת הוא <i>(הובא לעיל סי' תא</i><i>א</i><i> ולקמן סי' תב)</i>.\n----- הערות וציונים -----\n<i>בהאדם שהוא מובחר כו'</i> – ראה סנהדרין לז, סע\"א. קהלת רבה לקהלת ז, יג. אמו\"ד לרס\"ג בהקדמה שלהי פ\"ה, ושם מ\"ד.\n<i>הש\"י נקרא מנוחה כו'</i> – ראה לעיל סי' ת-ב, הקטע ממדל\"י סי' קכו.\n<i>הקב\"ה נקרא כו' ושכינתיה הוא כו'</i> – ראה לקו\"ת לאדה\"ז, דרושים לר\"ה נה, ג קוב\"ה נק' מה שהוא קדוש ומובדל מגדר עלמין ולית מחשבה תפיסא ביה וביטול ההשגה, ושכינתיה הוא שכינת עוזו ומלכותו המתלבשת בבחינת עלמין להחיותם כו'. וראה מזה בתניא פמ\"א ושם פמ\"ו.\n<i>שתמיד כמו שהיה פעם א' כו'</i> – נשנה שם ביד\"א רפנ\"ג בשם האריז\"ל. ראה שו\"ת הר\"י אירגאס בסו\"ס שומר אמונים רס\"י ה'. לב דוד להחיד\"א פכ\"ט ע\"פ דברי הרמ\"ז בס' תקון שובבי\"ם. וכן בס' חומת אנך, תהלים קיא, ד וקלח, ח. ס' יוסף תהילות קיא, ד. ועיין בספר המאמרים ה'תש\"ד לאדמו\"ר מהוריי\"צ, ע' 13, מקור לזה מהמשנה דגיטין לא, א, עיי\"ש. ולהעיר עוד מתוס' סוטה יד, א ד\"ה מפני.\n<i>כי בטובו מחדש כו'</i> – ראה לקמן בהוספות סי' עז."]]],[300010486,"תב\n\n<b>&lt;ענין&gt;</b> <span data-k=\"sm\">[כלל העולה שיום השבת הוא יום קדוש, שמאיר ומתגלה בהירות מקדוש שהוא הש\"י קדוש הקדושים, ומאיר על כל הברואים, ועיקר על עמו ישראל, כי זה סוד]</span> פריסות סוכת שלום, &lt;הפי' הוא&gt; כי סוכה ר\"ל <span data-k=\"sm\">[יסכה]</span> &lt;שהוא סוכה ברוח הקודש&gt; <span data-k=\"sm\">[שהוא]</span> לשון צפיה, שהוא ענין הבהירות המתגלה, כדי שעי\"ז ישתוקקו הנשמות אליו, ועיני כל אליו יצפו. ושלום הוא ענין התקשרות הברואים בבורא ית', כי זהו שלימות ושלום הכל א'. וענין שנקרא סוכה הוא שהוא כמו סכך שיש בו נקבים ומתנוצץ אור השמש בו דרך הנקבים &lt;כמרז\"ל כוכבי חמה וכוכבי אור&gt;, כמו כן הבהירות של הש\"י מתגלה לכל אחד ואחד לפי ערכו, לא' בניצוץ קטן, ולא' גדול מזה, ולזה נק' סוכה.\n[<b>ולפי</b> <span data-k=\"sm\">זה אם עיני שכל לך תבין]</span> עיקר יום השבת הוא להתדבק בהש\"י על ידי תפלה ותורה, ולזה קורא בזוהר האי יומא יומא דנשמתין, ולא יומא דקיימא בגופא, ר\"ל שמאיר שורש הנשמות על הנשמות שבגופים והם נכפפים אליו, וזה נק' תוספות נשמה יתירה, וכ\"ז נרגש &lt;לברי לבב&gt; <span data-k=\"sm\">[לכך צריך להזהר בתפלת שבת מאד מאד, כי זה עיקר השבת . . .]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>לקו</b>\"<b>י – יד</b>\"<b>א כט</b>,<b> ב (באמצע פמ</b>\"<b>ח</b>,<b> המשך לסוף סי</b>'<b> תאב)</b>\n<i>יסכה שהוא סוכה כו'</i> – מגילה יד, א. <i>ושלום </i>. .<i> התקשרות</i> – ר' זח\"ג י, ריש ע\"ב. <i>כמרז\"ל כוכבי כו'</i> – סוכה כב, רע\"א. שם ע\"ב. ירושלמי סוכה פ\"ב ה\"ג. <i>בזוהר האי יומא כו'</i> – זח\"ב רה, סע\"א. <i>תוספות נשמה יתירה</i> – ביצה טז, א. זח\"ב רד, ב. שם רה, א.\n----- הערות וציונים -----\n<i>עיקר יום השבת הוא כו'</i> – ראה לעיל סי' שיט ד\"ה והנה השבת לא ניתן לתענוג ואילך, ובהערות שם. סי' שעד ובהערות שם."]]],[300010487,"תג\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; שקילתא לסלתאי ואנחתא בכוותא דרקיע, ר\"ל על ידי שנתחבר בין חסידים ואנשי מעשה סבר שזה יגרום פרנסתו, כמו ששמעתי <i>ממורי</i> &lt;הבעש\"ט&gt; זלה\"ה תואר ראובן שמעון לוי יהודה יששכר זבולון, רא\"ו שאני ב\"ן &lt;למקום&gt;, ובזה יהיה שמעו הולך וגדול שהוא לוי, שנתחבר לחסידים, ויודו וישבחו אותו, ויהיה מבחינת יששכר וזבולון והוא יעסוק בתורה והם יפרנסו אותו, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י בהעלתך קמ</b>,<b> ב (תפג</b>,<b> ב)</b>\n<i>שקילתא כו'</i> – ב\"ב עד, א.\n----- הערות וציונים -----\n<i>כמו ששמעתי ממורי כו'</i> – ראה לעיל סי' לא ובהערות שם."]]],[300010488,"תד\n\n<b>מהבעש\"ט</b> זלה\"ה. מכל פשעי הצילני חרפת נבל כו'. דנודע דאם אדם מלמד חוב על איזה רשע, ופוסק עליו את הדין ואומר שראוי הוא שיבוא עליו פורעניות כזה וכזה, אזי זה הדין בעצמו פוסק על עצמו, אע\"פ שאין בו עבירה זו, מ\"מ אפשר שיש לו כאלו עשה עבירה, היינו המתגאה כאלו בא על אשת איש, הכועס כאלו עע\"ז, ואפשר שכאלו שלו הוא חמור אצלו יותר מעבירה עצמו של אותו רשע, כי מדקדקין עליו יותר. משא\"כ אם דן אותו לזכות, ואומר שהוא מגושם הרבה ויש לו חומר עכור עד שא\"א לו לכבוש את יצרו, וכיוצא מן הזכותים שאפשר לדונו, אזי מלמד הזכות הזה ע\"ע. וז\"א מכל פשעי הצילני שחרפת נבל אל תשימני, שלא אחרף מימי לנבל, ואלמד עליהם זכות, ובזה תציל אותי מכל פשעי, שזכות זה יהיה עלי ג\"כ. ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>מכל פשעי גו'</i> – תהלים לט, ט. <i>המתגאה כאילו כו'</i> – סוטה ד, ב. <i>הכועס כאלו כו'</i> – זח\"א כז, ב.\n----- הערות וציונים -----\nראה לקמן בהוספות סי' קיב וקיג, ובהערות שם. ולעיקר הדברים יש להעיר משבת קכז, ריש ע\"ב. תנחומא שופטים ד. זו\"ח נח כג, ריש ע\"ב (הובא בזח\"א רנב, ב וראה שם בנצו\"ז).\n<i>אם דן כו' ואומר שהוא מגושם כו'</i> – ראה תניא ריש פ\"ל."]]],[300010489,"תה\n\n<b>שמעתי</b> <i>ממורי</i> &lt;הבעש\"ט&gt; זלה\"ה בלומד &lt;ואינו מבין&gt; או מתפלל ואינו מכוין פירושו, הוא בבחינת המלכות לבדה. משא\"כ במבין מקשר מלכות בבינה <span data-k=\"sm\">[ודפח\"ח]</span>. וזה שאמר הכתוב מי זאת עולה מן המדבר <span data-k=\"sm\">[וק\"ל]</span>.\n<b>ולפי</b> הנ\"ל י\"ל כי יש בדיבור ב' בחינות, א' הדיבור, ב' פי' הדיבור. ופירוש הדיבור הוא במחשבה, בינה, עולם המחשבה, והדיבור עצמו הוא במלכות, ושניהם מי זאת עולה מן המדבר וק\"ל.\n<b>ובזה</b> יובן ויקחו לי תרומה, ר\"ל שיקחו להעלות תרומה, מלכות, אל הבינה, שנקרא לי, על דרך אם אין אני לי מי לי כו'. והיינו על ידי כל איש אשר ידבנו לבו, שמכוין בלבו פירוש המלות, והוא במחשבה שנקרא בינה, עי\"ז עולה דיבור אל הבינה והבן, שהיא בב' פנים הנ\"ל וא\"ש.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י קו</b>\"<b>א קסז</b>,<b> ד</b>\n<i>מי זאת גו'</i> – שה\"ש ח, ה. <i>והדיבור </i>. .<i> במלכות</i> – זח\"א קמה, א. <i>ויקחו לי תרומה מאת כל איש גו'</i> – תרומה כה, ב. <i>תרומה מלכות</i> – זח\"ב קלה, רע\"א. <i>הבינה שנקרא לי</i> – זח\"ב מג, ריש ע\"ב. <i>אם אין אני לי כו'</i> – אבות פ\"א מי\"ד. <i>במחשבה שנקרא בינה</i> – זח\"ג רכט, ב. זח\"א רמו, ב.\n----- הערות וציונים -----\nראה לעיל סי' סז-א. רג\"כ סי' קס ורפא-ב. לקו\"י סי' ע."]]],[300010490,"תו-א\n\n<b>כל</b> המחשבות בכללן בז' מינים כנגד ז' ימי הבנין, כגון אהבה ויראה וכו'. ובכל בחינה יש טוב ורע &lt;כו'&gt; <span data-k=\"sm\">[ובשבע רעות מחיה ז' עממין]</span>. לכן כשנופל לו מ\"ז יעיין מאיזה בחינה היא, ויאמר מה עשיתי שלקחתי חלק מעולם המחשבה וזרקתי אל מקום הטינופת, ומזה יכנע עד לעפר ויביא זאת המחשבה למדת אין. ואח\"כ יחשוב אם אני אוהב הדבר הזה, או אני מתענג מזה, כמה יש לי לאהוב הש\"י, וכן ליראה אותו וליבוש &lt;מפניו&gt; <span data-k=\"sm\">[ממנו]</span> ולפארו וכו', וכן לנצח המדה הזאת, ולהתקשר בהש\"י. &lt;ועי\"ז יבוא לעולם המחשבה שהוא למעלה מן הזמן&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י סי</b>'<b> קמז (קנה)</b>\n----- הערות וציונים -----\nראה לעיל סי' רכז ובהערות שם.\n<i>לכן כשנופל לו מ\"ז כו'</i> – ראה לעיל סי' לט ובהערות שם."]]],[300010491,"תו-ב\n\n[<b>צריך</b> <span data-k=\"sm\">האדם לחשוב את עצמו כאין, וישכח א\"ע מכל וכל. ויבקש הכל בכל תפילתו על השכינה, ואזי יכול לבא למעלה מזמן, דהיינו לעולם המחשבה ששם הכל שוה, חיים ומות ים ויבשה. וזהו מ\"ש בזוהר [מה תצעק אלי דבר אל בני ישראל וגו'], אל\"י דייקא, [דהא האי מילתא] בעתיקא תליא, שהיו צריכין להפקיר א\"ע ולשכוח בצרתן כדי שיבואו לעולם המחשבה ושם הכל שוה [והיו יכולים לילך אפילו בים]. משא\"כ כשהוא דבוק בגשמיות עוה\"ז הוא דבוק בהתחלקות טוב ורע, דהיינו ז' ימי הבנין, ואיך יבא למעלה מזמניות ששם אחדות גמור.]</span> וכן כשחושב א\"ע ליש ומבקש צרכיו, אז אין הקב\"ה יכול להתלבש בו, שהוא ית' א\"ס ואין כלי יכול לסובלו, משא\"כ כשחושב א\"ע לאין &lt;כו'&gt; <span data-k=\"sm\">[כנ\"ל]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י סי</b>'<b> קנא (קנט) [במילואים ע</b>\"<b>פ או</b>\"<b>ת סי</b>'<b> שפז-ג]</b>\n<i>מ\"ש בזוהר</i> – זח\"ב נב, ב. <i>מה תצעק אלי גו'</i> – בשלח יד, טו. <i>אז אין הקב\"ה יכול כו'</i> – ראה סוטה ה, א.\n----- הערות וציונים -----\n<i>ויבקש כו' על השכינה</i> – ראה לעיל סי' כ ובהערות שם.\n<i>ששם הכל שוה </i>. .<i> ים ויבשה</i> – ראה מדל\"י סי' קלד (קמב) בהתגלות יש חילוק בין ים ליבשה משא\"כ בשרשן ברצון העליון הקדום שם הכל אחדות פשוט. וראה בהערה הבאה אח\"ז.\n<i>מ\"ש בזוהר כו' ושם הכל שוה</i> – ראה מדל\"י שלהי סי' קס (קסח) בביאור דברי הזוהר.\n<i>בגשמיות עוה\"ז הוא דבוק בהתחלקות כו'</i> – להעיר מלעיל סי' שצ ותי. מדל\"י סי' רכה (רלז).\n<i>כשחושב א\"ע ליש כו' משא\"כ כו'</i> – ראה לקמן סי' תז-ב (במקורו) ומדל\"י סי' רנ (רסא)."]]],[300010492,"תז-א\n\n<b>שמעתי</b> <i>ממורי</i> &lt;הבעש\"ט זלה\"ה&gt; ביאור מוסר הכנעה נגד הגאוה, למלך שהיה לו ב' בנים, ושלח א' למדינה אחרת בכבוד &lt;גדול&gt;, ולאחד שלח בבזיון כדי שילמד הכנעה וענוה. וכך היה, עד שאח\"כ כבש זה עם הענוה יותר מדינות מחבירו ע\"י כבוד ומלחמה, והוא ע\"י מעשה רב, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>סו</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> שלהי ע</b>\"<b>ב (תשלא</b>,<b> ב אות כג)</b>\n----- הערות וציונים -----"]]],[300010493,"תז-ב\n\n<b>ואם</b> האדם ירצה לעשות הכנה שישרה עליו אלהות, אזי עיקר הכל שיבין וישיג מאד שאין בו אלא האלהות המחיה אותו, ובלתי זה הוא כאפס ממש, ואז יש הכנה שיכול לשרות עליו.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י שלהי סי</b>'<b> קסב (קע)</b>\n----- הערות וציונים -----\nראה לעיל סי' תו-ב."]]],[300010494,"תז-ג\n\n<b>&lt;כי&gt;</b> הקב\"ה ברא העוה\"ז ובתוכו האדם בצלמו, כדי שישרה בו &lt;כמרז\"ל נתאוה להיות לו דירה בתחתונים&gt; <span data-k=\"sm\">[כמשל בתי שררות בבית הוועד שרושמים [מבחוץ] שזה ביתו של פלוני]</span>. ולמה עשה כן, הלא המלאכים הם &lt;כ\"א&gt; שליש עולם ואורות יפות ומצוחצחות עד מאד. עכ\"ז יש לו ית' יותר תענוג מן האדם, כמשל הצפור המדברת לפני המלך אפי' דברי שטות יש להמלך יותר תענוג מכל מליצות השרים המשוררים. כך האדם החומרי, כשמעלה במחשבתו עולמות עליונים &lt;המה ראו כן תמהו נבהלו נחפזו רעדה אחזתם שם&gt; <span data-k=\"sm\">[נופל עליהם חיל ורעדה]</span> מיראתו של הקב\"ה, ונראה אור גדול מצוחצח. וכ\"ז נגלה ע\"י האדם שבעולם השפל, אזי &lt;יש&gt; <span data-k=\"sm\">[נולד]</span> התפארות גדול בהקב\"ה. וזהו אין אשה, דהיינו החומר, אלא ליופי, ר\"ל שהיופי, היינו התפארות העליון, נתגדל מאד מזה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י סי</b>'<b> קנב (קס)</b>\n<i>נתאוה הקב\"ה כו'</i> – תנחומא נשא טז. <i>המלאכים הם כו'</i> – בר\"ר סח, יב. <i>המה ראו גו'</i> – תהלים מח, ו-ז. <i>אין אשה אלא ליופי</i> – תענית לא, א. כתובות נט, ב.\n----- הערות וציונים -----\nראה לקו\"י טו, ד (סי' קס), וראה שם עוד יח, ג (סי' רכ) ואו\"ת סי' רפא.\n<i>אשה דהיינו החומר</i> – מו\"נ ח\"א פי\"ז ושם ח\"ג פ\"ח. ראה תקו\"ז תכ\"א סא, רע\"א גופא דאיהי איתתא."]]],[300010495,"תח\n\n<b>שמעתי</b> <i>ממורי</i> &lt;הבעש\"ט זלה\"ה&gt; שהאדם נקרא צדיק בסוד צדיק יסוד עולם כשיש לו תענוג גדול בעבודת הש\"י, כי מבשרי אחזה אלוה, נצח והוד הוא מצד האמנה בו ית' וכו', ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ ואתחנן קע</b>,<b> סע</b>\"<b>א (תרכו</b>,<b> ב)</b>\n<i>צדיק יסוד עולם</i> – משלי י, כה. <i>מבשרי גו'</i> – איוב יט, כו.\n----- הערות וציונים -----\nראה לעיל סו\"ס יא וסי' פח ורנז, ובהערות שם."]]],[300010496,"תט\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[קבלתי </span><i>ממורי</i><span data-k=\"sm\">]</span> שאם יראה מ\"ז, אם מענין הרהורי תאות המשגל ידבק בשרשו שהוא חסד, וכיוצא בזה, וכבוד ה' הסתר דבר, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י עקב קעא</b>,<b> א (תרכט</b>,<b> א)</b>\n<i>וכבוד ה' כו'</i> – ע\"פ משלי כה, ב.\n----- הערות וציונים -----\nראה לעיל סי' לט ובהערות שם."]]],[300010497,"תי\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> זלה\"ה, הן בסדר הלימוד הן בתפלה, אם הוא מבין פירוש המלות בתפלה ומבין פשט ההלכה בלימודו אז מקשר מלכות, שהוא דיבור, אל הבינה, שהוא מחשבה <span data-k=\"sm\">[ודפח\"ח]</span>. וז\"ש אדנ-י הוי\"ה &lt;אלקים אתה החלות&gt;, שיהא מקשר הדיבור, אדני, אל המחשבה, שהוא הוי\"ה בניקוד אלהים, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ ואתחנן קסז</b>,<b> א (תרטז</b>,<b> ב)</b>\n<i>מלכות שהוא דיבור</i> – זח\"א קמה, א. <i>הבינה שהוא מחשבה</i> – זח\"ג רכט, סע\"ב. זח\"א רמו, ב. <i>אד' הוי' גו'</i> – ואתחנן ג, כד. <i>בדיבור אד'</i> – זח\"ג רכח, א. <i>המחשבה שהוא כו'</i> – זח\"ג י, סע\"ב. תקו\"ז ח, ב.\n----- הערות וציונים -----\nנשנה לקמן סי' תכג-א. ראה לעיל סי' סז-א ותה ובהערות שם."]]],[300010498,"תיא\n\n<b>יחשוב</b> &lt;אדם בדיבור&gt; שעולם הדיבור מדבר בו, עולם גדול כזה שבו נבראו כל העולמות, כדאי' בהבראם שהוא בה' מוצאות הפה, ועי\"ז יחשוב בתפארתו ית'. כל חיות העולמות הוא מהדיבור, והדיבור הוא עולם היראה, וכביכול שכינה מצמצמת א\"ע ושורה בדיבורו בפיו, כדאי' בס' יצירה קבען בפה. ואם הדיבור הוא כך, מה הוא עולם המחשבה, ועוד אורות מצוחצחות אשר אין סוף וחקר.\n<b>כשיתחיל</b> לחשוב יאמר בלבו כי זה &lt;צמצום&gt; <span data-k=\"sm\">[צמצם א\"ע כביכול]</span> עולם המחשבה במוח, מדת חו\"ב, עולם גדול כזה ראוי לבייש לפניו.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י סי</b>'<b> קמד (קנב)</b>\n<i>בהבראם</i> – בראשית ב, ד. <i>שהוא בה'</i> – ע\"פ מנחות כט, ב. <i>כדאי' בס\"י</i> – פ\"ב מ\"ג.\n----- הערות וציונים -----\nראה לעיל סי' קצח, רעג-ב, רפד-א, שא-ב, שא-ג, שיג ות-ב.\n<i>שבו נבראו העולמות </i>. .<i> כל חיות העולמות כו'</i> – ראה לעיל סי' ת-ב ובהערות שם ד\"ה עולם הדיבור.\n<i>בה' מוצאות הפה</i> – ראה ס\"י פ\"ב מ\"ג. זח\"ג רכח, רע\"א. תקו\"ז ת\"ע קלב, סע\"א. תקוזו\"ח קיא, רע\"ג."]]],[300010499,"תיב\n\n<b>&lt;כתב</b> הרב הקדוש הגאון המחבר מ' יעקב יוסף הכהן ז\"ל וז\"ל:&gt;\n<b>הקשה</b> <i>מורי</i> &lt;ע\"פ ואהבת את ה'&gt; מה זה לו ית' לתועלת שנאהבנו, יתוש כמונו, אם יאהב למלך גדול ונורא מה זה נחשב לכלום. &lt;ושמעתי&gt; <span data-k=\"sm\">[הגם דשמעתי]</span> ממנו פירוש נפלא על קושיא זו, כי בריאת העולם היה ע\"י דין, שהוא סוד הצמצום כנודע, לכך דיני ויסורי האדם הם גוף אל הנשמה וחיות הרוחניות, וכשאדם מקבל היסורין באהבה ובשמחה שהוא בחינת החיות והרוחניות, הוא מקרב ומקשר ומדבק הגוף אל הנשמה, שהוא החיות והרוחניות, ונתבטל הדין. וח\"ו בהיפך דוחה הגוף שלו מן החיות. לכך אמר עצה היעוצה לאדם ואהבת את ה' אלהיך, שהוא בחינת דין, לקבלו בשמחה ולקשרו אל הוי\"ה שהוא הנשמה, ע\"י ואהבת, והבן <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י עקב קעא</b>,<b> ג (תרל</b>,<b> ב)</b>\n<i>ואהבת גו'</i> – ואתחנן ו, ה. <i>בריאת העולם היה ע\"י דין</i> – זח\"א קפ, ריש ע\"ב. שם רל, ב. זח\"ב כב, ריש ע\"ב. <i>וכשאדם מקבל כו'</i> – ר' תקו\"ז סתס\"ג צה, א. <i>אלקיך שהוא בחינת דין</i> – זח\"א סד, ב. זח\"ג ל, ב. ספרי ואתחנן סוף פ' כו.\n----- הערות וציונים -----\nראה לעיל סי' קפ ולקמן סי' תיג.\n<i>בריאת העולם הוא ע\"י דין שהוא סוד הצמצום</i> – ראה מבו\"ש ש\"א ח\"א פ\"א כל צמצום הוא דין. וראה ע\"ח שי\"ח פ\"ה. תניא, שהיוה\"א פ\"ד ופ\"ו.\n<i>וכשאדם מקבל היסורין כו'</i> – ראה תקו\"ז סוף תס\"ג צה, א."]]],[300010500,"תיג\n\n<b>&lt;עוד</b> יש לתרץ ע\"פ ואהבת קושיות מורי הבעש\"ט זלה\"ה וע\"פ מה ה' אלקיך שואל מעמך כ\"א ליראה&gt; <span data-k=\"sm\">[דקשה על ואהבת קושיית </span><i>מורי</i><span data-k=\"sm\">, ועל פסוק תירא קשה]</span> קושיית הפילוסופין. <span data-k=\"sm\">[וע\"כ צ\"ל כתירוץ </span><i>מורי</i><span data-k=\"sm\">, ובזה סרה גם קושית הפילוסוף]</span>, כי המלך בשר ודם א\"צ לצוות כי מעצמו יריאין מפניו, וגם הקב\"ה א\"צ לצוות על היראה זו יראת העונש שמעצמן יריאין מעונש מיתה ויסורין. הגם כי יש רשעים שגם מעונש מיתה ויסורין אין יראים, הטעם הוא שאותן רשעים כבר הם מתים בחיים, ואם היראה הוא להם מחמת מיתה ועוני א\"כ כשכבר מתים סר היראה מהם, שאהבתם ויראתם היו תלוין בדבר, בטל דבר בטילה אהבה ויראה שלהם. משא\"כ הצדיקים שיש להם אהבה ויראה פנימית, אשר על זה באו הכתובים ואהבת את ה' אלהיך, שהוא לאהוב היסורין ועוני החשוב כמת, וגם ליראה את ה' אלהיך שהוא גם אחר שבא &lt;ופגע בו&gt; מדה\"ד, ועל כרחך הוא מצד כבודו וגדלו ית', שאין הפסק לאהבה ויראה זו <span data-k=\"sm\">[אף אחר שפגעו בם מדת הדין]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י עקב קעא</b>,<b> סע</b>\"<b>ד (תרלא</b>,<b> ב)</b>\n<i>ואהבת גו'</i> – ואתחנן ו, ה. <i>מה ה' גו'</i> – עקב י, יב. <i>רשעים כבר הם כו'</i> – ברכות יח, ב. <i>שאהבתם </i>. .<i> תלויין בדבר כו'</i> – ע\"פ אבות פ\"ה מט\"ז. <i>ועוני החשוב כמת</i> – נדרים ז, ב. שם סד, ב. זח\"ב קיט, א.\n----- הערות וציונים -----\nראה לעיל סי' קפ ששם באורך. ולהעיר שנזכרה קושיית הפילוסוף גם בתוי\"י פ' ראה קעג, סע\"ג (תרלז, ב) בלי הזכרת הבעש\"ט, ושם בריש ע\"ד סיים: ומעתה מבואר קושי' הפילוסוף שאין זה ציווי ליראה אלא עצה היעוצה לאדם, בראותו שמתעוררין להתפשט כמה מיני יראה בעולם אז את ה' אלקיך תירא שהוא שורש היראה וניצול מכולם וק\"ל. וראה לעיל סי' רז-א ובהערות שם."]]],[300010501,"תיד\n\n<b>מהבעש\"ט</b> זלה\"ה ע\"פ מהרי שלש סאים קמח סלת, וארז\"ל הוא אמר קמח והיא אמרה סלת מכאן שהאשה עיניה צרה באורחים. והקושיא מפורסמת. ופי' הבעש\"ט ע\"פ משל, שהארי צוה ואמר לגוריו, אריות קטנים בנים שלו, ואמר להם תדעו שאתם הגבורים אשר מעולם, וכל הבריות מחויבים להתייראות מכם. פעם אחת הלכו האריות בבטחונם על גבורתם שאמר להם אביהם, ובאו לפלטין אחד חרב ובו היו כל מיני ציורים, וראו ציור א' על הכותל והנה שמשון הגבור עומד והורג את הארי וישסעהו כשסע הגדי. וכאשר ראו זה האריות הקטנים ברחו בבהלה אל אביהם, ואמרו לו הלא אדונינו אבינו אתה אמרת לנו שאנחנו הגבורים אשר מעולם כו', והרי ראה ראינו שם זה הציור אשר נבהלנו מאד, כי ראינו אדם א' עומד והורג את הארי וישסעהו כשסע הגדי. והשיב להם אביהם, אדרבה, מזה נודע גודל גבורתכם, שזה אירע פעם אחת בעולם, שאדם א' היה גבור מאוד ועשה פלא חוץ מהטבע להרוג את הארי, ע\"כ מציירים אותו לחידוש ולפלא. וזה שאמרו, כיון שכתוב בתורה צדקות ונדיבות שרה, שהוא אמר קמח והיא אמרה סלת, מכאן שאשה אחרת עיניה צרה באורחים.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>מהרי שלש גו'</i> – וירא יח, ו. <i>ארז\"ל הוא אמר כו'</i> – ב\"מ פז, א.\n----- הערות וציונים -----\nבגמרא שם כתיב קמח וכתיב סלת, ובפרש\"י שהיא אמרה קמח והוא סלת. וא\"כ אתי שפיר הלימוד שהאשה צרה כו'. אבל יש מפרשים באו\"א כמו כאן, ראה פתח עינים להחיד\"א שם שהאריך לבאר שאברהם אמר קמח ושרה אמרה סלת, וא\"כ יש להקשות מנא לן לימוד הנ\"ל."]]],[300010502,"תטו\n\n<b>כתיב</b> כי יקרא קן צפור כו' שלח תשלח את האם כו', ופי' בתיקונים כדי לעורר רחמים דיימא קב\"ה כל עופא מעורר רחמים על עופין דיליה ולית מאן דמעורר רחמים על בני, בהאי שעתא יימא קוב\"ה למעני למעני אעשה. אנה קן וצפרין קדושין, רבונא דעלמא אימת תפתח היכל קן צפור ויצא משם משיח מלובש בלבושי נוקמא, אימתי ירוחם משיח, כמ\"ש במדרש כונן שהוא ביסורין גדולים בשלשלאן דפרזלא, ומלכי בית דוד ונביאי ישראל מנחמים אותו שיצא לחירות, ושלשלאות דפרזלא שעליו מתנתקות, אימתי מקימי מעפר דל מאשפות ירים אביון ועריכת נר לבן ישי משיחך, אימתי יעמוד מיכאל על ההר ויקרא ובא לציון גואל.\n<b>אבינו</b> מלכנו עשה למענך אם לא למענינו, אם אין בינינו זכות, ואין בינינו צדיקים ובעלי צדקות, וגם אין לנו זכות אבות, כמ\"ש לעת תמוט רגלם, שתכלה זכות אבות ח\"ו, הלא אתה אבינו ואתה צדיק ובעל צדקה גדול עם כל ברואיך, כמ\"ש לך ה' הצדקה, עושה צדקות עם כל בשר ורוח, וכמ\"ש כי אברהם לא ידענו כו' אתה ה' אבינו גאלינו מעולם שמך, עשה למען שמך, עשה למען כסא כבודך, עשה למען שכינתך. ואם השכינה וחיילותיה עומדים לפני כסא כבודך, וגם הסט\"א וחיילותיהם שהם החוחים והקוצים הסובבים השושנה העליונה, הלא ודאי הוא כבודך שתזכה בדין אנחנו ושכינת עוזך, ואל ישמחו שונאינו, יבושו כל עובדי פסל כו'.",[["","","----- מקורות ומראה מקומות -----\n<i>כי יקרא גו'</i> – כי תצא כב, ז. <i>ופי' בתיקונים כו'</i> – ת\"ו כג, א. <i>למעני גו'</i> – ישעי' מח, יא. <i>ויצא משם משיח כו'</i> – ר' זח\"ב ז, ב. שם ח, ב. זח\"ג קצו, ב. <i>כמ\"ש במדרש כונן כו'</i> – אוצר מדרשים ע' 256. ר' פס\"ר סי' לו. <i>מקימי מעפר גו'</i> – תהלים קיג, ז. <i>ועריכת נר כו'</i> – עמידה דר\"ה ויוה\"כ. <i>ובא לציון גו'</i> – ישעי' נט, כ. <i>לעת תמוט רגלם</i> – האזינו לב, לה. <i>שתכלה כו'</i> – פירש\"י שם. <i>לך ה' הצדקה</i> – דניאל ט, ז. <i>עושה צדקות כו'</i> – תפילת א-ל מלך יושב. <i>כי אברהם גו'</i> – ישעי' סג, טז. <i>יבושו כל עובדי פסל</i> – תהלים צז, ז.\n----- הערות וציונים -----"]]],[300010503,"תטז\n\n<b>רבש\"ע,</b> אין אנחנו מחיילותיו של הס\"ם המכונים בשם נגע רע, ר\"ת נפילים גבורים ענקים רפאים עמלקים, אלא אנחנו מחיילות של שכינת עוזך, ואנחנו עוברים לפניך כבני מרון, אנחנו מחיילות של בית דוד, זרעו של יצחק, ועקידת יצחק לזרעו ברחמים תזכור, וכמ\"ש איש על דגלו באותות לבית אבותם, והרי אנחנו חתומים בכנפי מצוה, הכר נא למי החותמת.",[["","","----- מקורות ומראה מקומות -----\n<i>נגע רע ר\"ת כו'</i> – זח\"א כה, א. <i>עוברים לפניך כו' מחיילות כו'</i> – ר\"ה יח, א. <i>ועקידת יצחק כו'</i> – סוף ברכת זכרונות במוסף דר\"ה. <i>איש על דגלו גו'</i> – במדבר ב, ב. <i>הכר נא גו'</i> – ע\"פ וישב לח, כה.\n----- הערות וציונים -----"]]],[300010504,"תיז\n\n<b>כתיב</b> וכי ימוך אחיך ומטה ידו עמך והחזקת בו גר ותושב וחי עמך. אף אם הוא גר או תושב, ואיזהו תושב כשקבל עליו שלא לעבוד עבודה זרה, ואוכל נבילות, אעפ\"כ מצווין להחיותו. א\"כ גם אנחנו, אם אין בנו כי אם שאין אנחנו עובדי ע\"ז, כמ\"ש אם שכחנו שם אלהינו ונפרוש כפינו לאל זר הלא אלהים יחקר זאת כו', ואם אנחנו כופרים בע\"ז הלא ארז\"ל הכופר בע\"ז כמודה בכל התורה, נמצא אנחנו מודים בתורתך ובך. ואף כי גרים ותושבים אנחנו עמך תושיענו, ואף על פי שאיני כדאי ולא ראוי ולא זכאי להמליץ על עצמי, כ\"ש על אחרים, כמרז\"ל יבוא זכאי ויכפר על החייב, ואני חייב ולא זכאי, אעפ\"כ הלא ארז\"ל אף על פי שהנדון אומר יכול אני לחפש על עצמי זכות כו', כ\"ש על ישראל.\n<b>כתיב</b> והבאתי אותם בארץ אויביהם או אז יכנע לבבם, ואנחנו כבר נכנעים מאד, ואז ירצו עונם וזכרתי את בריתי יעקב כו'.",[["","","----- מקורות ומראה מקומות -----\n<i>וכי ימוך גו'</i> – בהר כה, לה. <i>ואיזהו תושב כו' להחיותו</i> – רש\"י שם. פסחים כא, ב ורש\"י שם ד\"ה להקדים. <i>אם שכחנו גו'</i> – תהלים מד, כא-כב. <i>הכופר בע\"ז כו'</i> – נדרים כה, א. <i>יבוא זכאי כו'</i> – יומא מג, ב. שבועות יד, א. <i>ארז\"ל אע\"פ כו'</i> – סנהדרין מב, ריש ע\"ב. <i>והבאתי אותם גו'</i> – בחקותי כו, מא. <i>וזכרתי את גו'</i> – בחקותי כו, מב.\n----- הערות וציונים -----"]]],[300010505,"תיח\n\n<b>כתיב</b> ויהי בימים הרבים ההם כו' ויאנחו כו' ותעל שועתם. וגם אנחנו נאנח בשברון מתנים, אנחה השוברת חצי גופו של אדם, ואף כי על חורבן בהמ\"ק שנינן בה, מ\"מ צרות חדשות נאנח עליהם, מלאכי מעלה יבכיון על דאבוני, אנחנו אין כחינו אלא בפינו, תולעת יעקב. משוד עניים מאנקת אביונים עתה אקום יאמר ה', פי' כי אם ח\"ו תגזור גזירות כגון עצירת גשמים או רעב, אבל איך תוכל לסבול גודל הרחמנות מאנקת אביונים, כי אינך כמלך בשר ודם שאינו יודע עתידות, אבל אתה מגיד ורואה מראשית אחרית ורואה הרחמנות, ומלך רחמן אתה, ע\"כ עתה אקום, קודם בא הצרה אקום להושיע יאמר ה', כ\"ש שתושיע מצרה שכבר באה. מתי ינחם את משיח מכל יסוריו שסבל, ואת אבילי ירושלים והעיר האבילה כו'.",[["","","----- מקורות ומראה מקומות -----\n<i>ויהי בימים הרבים גו'</i> – שמות ב, כג. <i>אנחה השוברת כו'</i> – ברכות נח, ב. <i>אין כחינו אלא בפינו</i> – זח\"א קעח, רע\"א. <i>תולעת יעקב</i> – ישעי' מא, יד. <i>משוד עניים גו'</i> – תהלים יב, ו. <i>מגיד ורואה גו'</i> – ע\"פ ישעי' מו, י. <i>משיח מכל יסוריו שסבל</i> – סנהדרין צח, א. פס\"ר סי' לו-לז. <i>ואת אבילי ירושלים כו'</i> – תפלת נחם.\n----- הערות וציונים -----"]]],[300010506,"תיט-א\n\n<b>האדם</b> יודע מה נתבשל כל השנה מ\"ז בגופו בשעת תורה ותפלה, מי יתן והיה כלי נחשת, ומורק ושוטף, ח\"ו כלי חרס אינו יוצא מדופיו וצריך שבירה, לב נשבר ונדכה אלהים לא תבזה.",[["","","----- מקורות ומראה מקומות -----\n<i>כלי נחשת ומורק ושוטף</i> – ר' צו ו, כה. <i>כלי חרס אינו כו'</i> – פסחים ל, ב ורש\"י שם ד\"ה דמידייתי. <i>לב נשבר גו'</i> – תהלים נא, יט.\n----- הערות וציונים -----"]]],[300010507,"תיט-ב\n\n<b>הצופה</b> העולה על המגדל כשרואה איזה דבר אז תוקע בשופר, ואתה עלית על המגדל של בית הכנסת, האם אתה רואה כל המסטינים הסובבים הכסא שאתה תוקע, כמו שהיו הראשונים רואים לזמר עריצים להכרית החוחים כו'. ע\"כ נק' יום תרועה, לשון מוקש אתרעא, כעני בפתח דופק פתחי לי שערי צדק, פתח לנו שערי רחמים כי בידך מפתח שערי רחמים, זה השער לה' צדיקים יבואו בו.",[["","","----- מקורות ומראה מקומות -----\n<i>יום תרועה</i> – פנחס כט, א. <i>ל' מיקש אתרעא</i> – זו\"ח חקת נב, רע\"א. <i>פתחו לי גו' זה השער לה' גו'</i> – תהלים קיח, יט-כ.\n----- הערות וציונים -----"]]],[300010508,"תכ-א\n\n<b>יומא</b> פ\"א משנה ה', מסרוהו זקני ב\"ד לזקני כהונה והעלוהו לעליית בית אבטינס והשביעוהו כו' ואמרו לו אישי כ\"ג אנו שלוחי ב\"ד ואתה שלוחנו ושליח ב\"ד, משביעין אנו עליך במי ששיכן שמו בבית הזה שלא תשנה דבר מכל מה שאמרנו לך, הוא פורש ובוכה כו', פי' על שחשדוהו לצדוקי ליתן הקטרת מבחוץ. והנה עתה חרב בהמ\"ק ואין כהן גדול ולא קטרת, אבל התפלות הקדושות הם במקום קטורת, כמ\"ש תכון תפלתי קטורת לפניך, וראוי שלא תתן מבחוץ אותם יחודים קדושים עליונים דקה מן הדקה הנק' קטורת, וגם אתה לא תשנה ח\"ו, כי אם לא היית שלוחינו לא היינו חוששים, כי המתפלל וטעה סימן רע לו, אבל אתה שלוחינו, וש\"ץ שטעה סימן רע לשולחיו, וח\"ו הרי אתה מפסיד לכולנו, כי הכ\"ג היה טעון פרישה ז' והזאת אפר פרה, כ\"ש עתה התפלה קטורת שלנו, והרי אנחנו מושבעים ועומדים מן המשנה, מתנאים הקדושים, מישראל, מבית דין של מעלה ושל מטה.",[["","","----- מקורות ומראה מקומות -----\n<i>יומא פ\"א מ\"ה</i> – יומא יח, ב. <i>על שחשדוהו כו'</i> – יומא יט, ב. <i>תכון תפלתי גו'</i> – תהלים קמא, ב. <i>דקה מן הדקה</i> – כריתות ו, ב. <i>המתפלל וטעה כו' וש\"ץ שטעה כו'</i> – ברכות לד, ב. <i>הכ\"ג היה טעון כו'</i> – יומא ב, א. <i>והזאת אפר פרה</i> – יומא ד, א.\n----- הערות וציונים -----"]]],[300010509,"תכ-ב\n\n<b>וכמה</b> חרב חדה מונחת על צואריהם, ומזלם חזי, ואעפ\"כ לא ימנעו עצמם מן הרחמים, והם יבכו בלב שלם.\n<b>הלא</b> ראש השנה הוא יום טוב, ובמשנה יום טוב של ר\"ה, והוא יום שמחה, ע\"כ אומרים שהחיינו. ומ\"ש האריז\"ל לבכות, הוא עבור גלות שכינה וכו' וכדי שידונינו הש\"י לטובה. והוא שכ' לכו אכלו משמנים וגו' ואל תעצבו כי חדות ה' היא מעוזכם, והבכיה שבוכין הוא בכיה של שמחה על שהחיינו והגיענו. ע\"כ ראוי כיון שהוא יום שמחה ראוי לזכור ירושלים, כמ\"ש אם לא אעלה את ירושלים על ראש שמחתי, שקבלנו זה בשבועה וקללה כמ\"ש אם אשכחך ירושלים כו'.",[["","","----- מקורות ומראה מקומות -----\n<i>חרב חדה כו'</i> – ע\"פ ברכות י, סע\"א. <i>ר\"ה הוא יו\"ט</i> – מרדכי פ\"ק דר\"ה סי' תשח. <i>יו\"ט של ר\"ה</i> – ר\"ה כט, ב. <i>והוא יום שמחה</i> – נחמי' ח, ב. שם י-יב. <i>ומ\"ש האריז\"ל כו'</i> – פע\"ח שער השופר פ\"ה. <i>לכו אכלו גו'</i> – נחמי' ח, י. <i>אם לא אעלה גו'</i> – תהלים קלז, ו. <i>אם אשכחך גו'</i> – תהלים קלז, ה.\n----- הערות וציונים -----\n<i>והוא יום שמחה</i> – ראה ירושלמי ר\"ה פ\"א ה\"ג. טושו\"ע ריש סי' תקצז.\n<i>ומ\"ש האריז\"ל כו'</i> – ראה מש\"כ בזה בלקו\"ת לאדה\"ז, דרושים לר\"ה נד, ריש ע\"ד. ועיי\"ע שם פ' תצא לו, סע\"ג ולז, ד."]]],[300010510,"תכא\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> ז' מדריגות שיש בשכינה, א' היודע שירד ממדריגתו ואינו מתפלל &lt;כו'&gt;, ב' שיודע ומתפלל שיעלה וכו', &lt;ג' שאינו יודע מירידתו וסובר שאין למעלה ממנו, זהו בנוקבא דתהום רבה&gt; <span data-k=\"sm\">[ודפח\"ח]</span>.\n<b>והמשל</b> על זה לאשה עניה אחת שהי' לה ביצה אחת ושמחה בה שמחה גדולה, שסברה שמביצה זו תבוא שתוכל לקנות עי\"ז פרה ושאר צאן ובקר ועושר רב, הא כיצד שתשים הביצה תחת תרנגולת חברתה ותלד אפרוח, ומן האפרוח הזה יהיו לה ביצים וכן אפרוחים כו', ובאמצע שמחתה ושעשוע ומשמושה בביצה הנ\"ל נפל הביצה מידה ונשארה קרח מכאן כו'. כן הוא המשל מזה שאינו יודע כו', משא\"כ היודע משתדל לעלות כו' ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<i>שמעתי</i> . . <i>ודפח\"ח</i>: <b>תוי</b>\"<b>י חקת קנא</b>,<b> ד (תקסא</b>,<b> ב)</b>\n<i>בנוקבא דתהום רבה</i> – זח\"ג קטו, רע\"א ובהג' מהרח\"ו שם. שם קכב, א.\n----- הערות וציונים -----\n<i>ז' מדרגות</i> – ראה מש\"כ בהערות לסי' קיח.\n<i>ג' שאינו יודע כו'</i> – ראה לעיל סי' קיח.\n<i>המשל על זה כו'</i> – הובא בקיצור באו\"ת שה\"ש סי' קפט, ושם גם נמשל לזה."]]],[300010511,"תכב\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; כל רודפיה השיגוה בין המצרים, דשמעתי הודאי שמו כו' אבל הספק הוא חצוניות וקליפות <span data-k=\"sm\">[ודפח\"ח]</span>. וז\"ש מה שכל רודפיה השיגוה בין בגשמי בין ברוחני לפי שהיו בין המצרים, שהיו בספק אם לאחוז במיצר וגבול זה או במיצר אחר שכנגדו.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י דברים קסו</b>,<b> ב (תריב</b>,<b> א)</b>\n<i>כל רודפיה גו'</i> – איכה א, ג. <i>הודאי שמו כו'</i> – פיוט וכל מאמינים במחזור לר\"ה ויו\"כ.\n----- הערות וציונים -----\n<i>הספק הוא חיצוניות וקליפות</i> – ראה לעיל סי' שעט ובהערות שם."]]],[300010512,"תכג-א\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt;. כל העוסק בתורה ובתפלה, שהוא מלכות, יתייחד עם עולם המחשבה, שהוא בינה כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>לקמן תכג-ג</b> <b>וש</b>\"<b>נ</b>\n----- הערות וציונים -----"]]],[300010513,"תכג-ב\n\n<b>והזהיר</b> מאד ללמוד ד' שלחן ערוך בלי שום פירוש, וללמדם עם קטנים, וכ\"ש הגדולים, כי מחמת מניעות לימוד זה התורה משתכחת מישראל. כ\"א כשרוצה לפסוק דין אזי יעיין היטב במפרשים.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n----- הערות וציונים -----\nלהעיר מצוה\"ר סי' קיז. דבש לפי להחיד\"א מע' ת אות מא. ועיין הל' ת\"ת לאדה\"ז רפ\"ב."]]],[300010514,"תכג-ג\n\n[<b>שמעתי</b> <i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span>, הן בסדר הלימוד הן בתפלה, אם הוא מבין פירוש המלות בתפלה ומבין פשט ההלכה בלימודו אז מקשר מלכות, שהוא דיבור, אל הבינה, שהוא מחשבה, ודפח\"ח. וז\"ש אדני הוי\"ה &lt;אתה החלת כו'&gt; שיהא מקשר הדיבור, אדני, אל המחשבה, שהוא הוי\"ה בניקוד אלקים, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ ואתחנן קסז</b>,<b> ב (תרטז</b>,<b> ב)</b>\n<i>מלכות שהוא דיבור</i> – זח\"א קמה, א. זח\"ג רכח, א. <i>הבינה שהוא מחשבה</i> – זח\"ג רכט, סע\"ב. זח\"א רמו, ב. <i>אד' הוי' גו'</i> – ואתחנן ג, כד. <i>הדיבור אד'</i> – זח\"ג רכח, ב. שם יא, א. <i>המחשבה שהוא כו'</i> – זח\"ג י, סע\"ב. תקו\"ז ח, ב.\n----- הערות וציונים -----\nכבר הובא לעיל סי' תי עיי\"ש."]]],[300010515,"תכד\n\n<b>שמעתי</b> מחסיד א', כששמע הרב מ' דוב בער זלה\"ה מהשם הגדול של הרב הקדוש הבעש\"ט, וכל העם נוסעים אליו ופועל בתפלתו פעולות גדולות ונוראות, והנה הרב מ' דוב בער זלה\"ה היה חריף גדול ובקי בכל הש\"ס ובכל הפוסקים, והיה לו עשר ידות בחכמת הקבלה, והיה מתמיה על דבר השמועה מגודל מעלת הבעש\"ט. ופעם א' נתיישב בדעתו לנסוע אל הבעש\"ט כדי לנסותו כו', ומחמת שהרב מ' דוב בער זלה\"ה הי' מתמיד גדול בלימוד, תיכף כשהיה בדרך יום ושתים, ולא היה אפשר לו להתמיד בלימודו כמו בביתו, התחיל להתחרט על שנסע. והנה אח\"כ כשבא אל הבעש\"ט זלה\"ה, וסבר שישמע ממנו תורה, והבעש\"ט זלה\"ה סיפר לו מעשה א' איך שנסע דרך כמה ימים ולא היה לו עוד לחם ליתן להערל שלו בעל העגלה ונזדמן לו גוי עני א' עם שק לחם וקנה ממנו הלחם כדי לפרנס הערל בעל העגלה שלו, עוד ממעשיות כאלה. ואח\"כ ביום השני בא עוד אצל הבעש\"ט, וסיפר לו איך שבדרך לא היה לו עוד שחת לתת להסוסים ונזדמן לו כו'. והנה כל המעשיות שסיפר הבעש\"ט זלה\"ה היה בהם חכמה נפלאה ורבה למבין, והנה ה\"ה הרב מ' דוב בער שלא הבין זה, ע\"כ בא לבית אכסניא ואמר למשרת שלו אני הייתי חפץ לנסוע היום תיכף למקומינו, אך מפני שהיה חשך מאד ע\"כ נלין פה עד שתזרח ותעלה מאור הלבנה אזי נסע לדרכינו.\n<b>והנה</b> בחצות לילה, כשהכין הרב מ' דו\"ב א\"ע לנסוע, אז שלח הבעש\"ט את משרת שלו לקרוא אותו, והלך אצל הבעל שם טוב זלה\"ה. ושאל אותו הבעש\"ט זלה\"ה, יכול אתה ללמוד, והשיב כן. וא\"ל הבעש\"ט, וכן שמעתי שאתה יכול ללמוד. ושאל אותו הבעש\"ט, יש לך ידיעה בחכמת הקבלה, א\"ל כן. ואמר הבעש\"ט למשרת שלו, קח לי ספר עץ החיים, והראה הבעש\"ט להרב מ' דוב בער מאמר א' בספר עץ החיים, א\"ל הרב מ' דו\"ב הנה אקח לעיין ולהתיישב כו', ואח\"כ אמר להבעש\"ט ז\"ל את הפשט במאמר הזה. וא\"ל הבעש\"ט, אינך יודע כלום. וחזר ועיין בו כו', וא\"ל להבעש\"ט הפשט הנכון כמ\"ש, ואם יודע מעלתו פשט אחר יאמר לי ואשמע האמת עם מי. וא\"ל הבעש\"ט, עמוד על רגליך, ועמד. והנה במאמר הזה היה כמה שמות מלאכים, ומיד שאמר הבעש\"ט זלה\"ה זה המאמר נתמלא כל הבית כולו אורה, ואש היה מלהטת סביבותיו, וראו בחוש את המלאכים הנזכרים. וא\"ל לה\"ה הרב מ' דוב בער ז\"ל, אמת שהפשט כמו שאמרת, אבל הלימוד שלך היה בלי נשמה. ותו\"מ צוה הרב מ' דו\"ב את המשרת שלו לנסוע לביתו, והוא נשאר שם אצל הבעש\"ט ולמד אצלו חכמות גדולות ועמוקות. כל זה שמע מפה קדוש הרב מ' דוב בער זלה\"ה.",[["","","----- הערות וציונים -----\nנו\"א בשבחי הבעש\"ט ע' עה ואילך. ולהעיר שכאן מיוחס הסיפור להרה\"מ עצמו, וע\"כ יש לתקן בשבחי הבעש\"ט."]]],[300010516,"תכה\n\n<b>ויאמר</b> הנה האש והעצים ואיה השה לעולה ויאמר אלהים יראה לו השה לעולה בני. קשה, למה שאל הנה האש והעצים. עוד קשה, מ\"ט השיב אלהים יראה לעולה בני, הל\"ל עולה בני. וי\"ל דבגמ' פסחים פ' אלו דברים, ת\"ר הלכה זו נתעלמה מבני בתירה כו' ולא ידעו אם פסח דוחה שבת, קראו להלל כו', התחיל מקנטרן כו', שאלוהו שכח ולא הביא סכין כו', וירושלים לאחר שפרצו בחומה מלכי יון הויא רה\"ר, א\"ל בני נביאים הן &lt;כו'&gt;, למחר מי שפסחו טלה תוחבו בצמרו מי שפסחו גדי תוחבו בין קרניו. ומקשי, והא קעביד עבודה בקדשים, ומשני כדהלל דלא מעל אדם בעולתו מימיו דלא היה מקדישה עד שבא לבהמ\"ק.\n<b>וז\"ש</b> יצחק, שנ' תחלה ויקח בידו את האש כו' ויבקע עצי עולה וישם על יצחק, והקשה לו יצחק ויאמר הנה האש שאתה נושא, וא\"א לומר שאתה בעצמך תהיה העולה, והעצים אני נושא ועולה הויה קדשי קדשים ויש בה מעילה מחיים, א\"כ מוכרח לומר שיהיה שה לעולה, א\"כ ואיה השה לעולה. והשיבו ויאמר אלהים יראה לו השה, פי' אפשר שהאמת עמך דאלהים יראה לו השה, ואם לאו לעולה בני, פי' איני אומר עולה בני, דהוה משמע דכבר הקדשתיך להיות עולה, אלא לעולה בני, פי' שם אקדישך וכדהלל.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>ויאמר הנה האש גו'</i> – וירא כב, ז-ח. <i>ת\"ר הלכה זו כו'</i> – פסחים סו, א. <i>וירושלים לאחר שפרצו כו'</i> – תוספות פסחים סו, א ד\"ה תוחב. <i>ומקשי כו'</i> – פסחים סו, ריש ע\"ב. <i>ויקח בידו גו'</i> – וירא כב, ו. <i>ויבקע גו'</i> – שם ג. <i>ועולה הויא ק\"ק</i> – זבחים נג, ב. <i>ויש בה מעילה מחיים</i> – מעילה ט, א.\n----- הערות וציונים -----\nלהעיר שבס' אוהב ישראל להרב מאפטא, ס\"פ וירא, הובא כל זה (בשנוים קלים) \"בשם הרב הגאון הגדול מו\"ה בצלאל דודו\"."]]],[300010517,"תכו\n\n<b>הלומד</b> לשמה כוונת אהבתו לדבק א\"ע בעצמות האותיות &lt;של&gt; התורה, שהוא רצה היות &lt;מרכבה להקב\"ה שהוא&gt; חי החיים ותענוג התענוגים &lt;שבתוך האותיות הוא&gt; <span data-k=\"sm\">[שבתוכו]</span> אור א\"ס באור פני מלך חיים. וזהו ששמעתי <i>ממורי</i> &lt;הבעש\"ט מ&gt;ענין לשמה לשם האות עצמה &lt;פי' לאור א\"ס והחיות הגנוז בו&gt; _<span data-k=\"sm\">[ודו\"ק ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י חקת קנא</b>,<b> ג (תקס</b>,<b> ב)</b>\n<i>חי החיים</i> – תקו\"ז תי\"ט מא, סע\"ב. שם תס\"ט קטו, סע\"א. <i>ובאור פני גו'</i> – משלי טז, טו.\n----- הערות וציונים -----\n<i>לדבק א\"ע כו'</i> – ראה לעיל סי' צד, צו-א וקכב. ורג\"כ סי' יו\"ד ומד-א.\n<i>לשמה לשם האות עצמה</i> – לעיל סי' קכז וקמב, ועיי\"ש בהערות."]]],[300010518,"תכז<i>[ftnref_1_פט]</i>\n\n<b>מבעש\"ט</b> זלה\"ה. הכל בהשגחה פרטית ממנו ית', וכשאינו מאמין בזה הוא בדין מלכות שמים ומשועבד אל הקליפה המכסה ומסתיר ענייני השגחת הש\"י. ולעתיד, בימי המשיח, יעביר רוח הטומאה ויתגלה השגחתו ית' בפרטות, וזהו אין בין העוה\"ז לימות המשיח אלא שעבוד מלכיות.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י וישלח סד</b>,<b> ריש ע</b>\"<b>ב (שט</b>,<b> א)</b>\n<i>יעביר רוח גו'</i> – ע\"פ זכרי' יג, ב. <i>אין בין עוה\"ז כו'</i> – ברכות לד, ב.\n----- שולי הגליון -----\n[ftn_1_פט]) <i>סימן זה הוא קטע</i>,<i> בשנויים והשמטות</i>,<i> מהמובא לעיל סי' מו</i>,<i> עיי\"ש</i>.\n----- הערות וציונים -----\nהמאמר במילואו לעיל סי' מו-א."]]],[300010519,"תכח\n\n<b>מהבעש\"ט</b> זלה\"ה. מהו באדם חסדים וגבורות, פי' כשיחשוב האדם שפלותו וגריעותו נק' גבורות, וההיפך גודל מעלת חסדי הש\"י עליו ועם כל אדם נק' חסדים<i>[ftnref_1_צ]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י וישב כט</b>,<b> סע</b>\"<b>א (קד</b>,<b> ב)</b>\n----- שולי הגליון -----\n[ftn_1_צ]) <i>במקורו אינו מהבעש\"ט</i>,<i> ושם</i>:\nשמעתי מהמנוח מו' נח מראשקוב, שיחשוב האדם גריעותו וחסרונו ושפלותו נקרא גבורות, וההיפוך גודל מעלות חסד השי\"ת עם האדם נקרא חסדים וכו' ודפח\"ח.\n----- הערות וציונים -----"]]],[300010520,"תכט\n\n<b>בס'</b> חרידים אלה המצות עשה התלויות בלב ואפשר לקיימן בכל יום: מאושר מאלו' מאנוש מאמין מציאותיך ממציא מאין מצואים משגיח מנהיג מושל, מאמין מיחודיך, מתירא מרוממות מוראך, משמך ממקדשך, מיראך מחכמיך, משתוקק מאהבתך, משורר משירות מחודשות מלפניך, מזכירך מאהבה מיצועי משכבו מתעורר מחצות מדביקותיך, ממליכך מק\"ש מעלה מטה מארבע, מעמקים מתפלל, מקדשך ממקהלות, מדמה מדרכיך, מבחירה מטוב, משימך מבטחו, מתבונן מגדולתך, מזכיר מחסדיך מיציאת מצרים, מקבל מעול מלכות מעול מצות משבח מלך מחונן מכח מזכירך משבחך מנשימותיו, מיסוריו מקבלם מאהבה משמחה, מפשפש מעשיו מתשובה מחטאיו מתודה, מל מערלת מלב מבשר, מורא מאב מאם, מכבדם, מחבב מריעיו מגירים מדיינים מזכות, מלכעוס, מלדבר מרעת מריעיו משנאיו מגופך מחביריך מנע, מקבל מדברי מוכיחים, מבקר מחולים, מבקש מרחמיו מחזירם מתשובה, מקדש מחנהו מיוחד מחותמות מאותות מלך, משייר מפיאה מצדעיו מלהשחית מזקנו, מתעטף מכסות מורא מסתכל מציצית מזכירים מצותיך, מקדש מחשבת מוחיו מתפילין, מזכיר מתמידות ומשבת, משים מגופו מקדש מעון משכנותיך, משים מזוזה מפתחו מזכיר ממשלתך מצאתו מביתו מבואו, משים נפשו מחוט משולש מקדושה משולשת מתענג משבת מעצמותו מקדושתו מוכתר מכתר מאור מקודש מתפארת מעוזו מוכלל מנשמה מתוספות מושלת משבת מובטל ממנהגו מטבעיו' מגופניות מתפשט מגשמיות, מקדש מחשבת מוחיו מתעורר מרוחניות מתלבש מנשמה משדי, משיג מהשגות מתורה מסודותיה, משים מנפשו משכן מתמיד מקדש מלך מדביקותו מדמה מאור מסביבו מתפשט מתוכו מושבו מתעטף מכסות מורא מרעיד מטבעו מתעורר מיראה מאהבה.",[["","","----- הערות וציונים -----\nנראה שזהו מהדורא קמא ממ\"ש הרב המחבר בקונטרס נתיב מצותיך פ\"א בשנויי נוסח וסדר המצוות. ועיי\"ש בהקדמת הקונטרס בענין התחלת כל המילים בממי\"ן."]]],[300010521,"תל\n\n<b>בגמרא</b> הרוצה ליהנות יהנה כאלישע כו' והרוצה שלא ליהנות אל יהנה כשמואל הרמתי. הקשה, א\"כ כיון שהוא דבר הרשות, דהרוצה לעשות כך עושה והרוצה לעשות כך עושה, א\"כ למה ליה לבעל מסדר הגמרא למכתביה. עוד קשה, דחדא בבא משתמע מאידך, או סיפא מרישא, דכיון דקאמר הרוצה להנות יהנה כאלישע ממילא שמעינן דהרוצה שלא ליהנות כו', או רישא מסיפא.\n<b>ופי'</b> דהנה העשיר הנותן צדקה הוא עושה מצוה דנתון תתן לו כו', פתוח תפתח את ידך לאחיך כו', אבל העני המקבל את הצדקה לכאורה אינו עושה שום מצוה. אך אם העני המקבל את הצדקה מקבל בכונה זו, כלומר כיון שאני צריך לקבל, וכגון שאין מעשה ידיו מספיקים לו, על זה אמרו כל הצריך ליטול ואינו נוטל הרי זה שופך דמים, ובמשנה היו לו מאתים חסר דינר אפילו אלף נותנים לו כאחת ה\"ז יטול. א\"כ, כשמקבל העני בכונה זו, כיון שאני צריך ליטול הריני מזכה את העשיר העושה עמי צדקה, נמצא גדול המעשה יותר מן העושה, שהרי העני המקבל יכול לקבל ביום אחד צדקה מכמה אנשים יותר ממה שהנותן יכול ליתן. וזה ארז\"ל כן בפי' ע\"פ האיש אשר עשיתי עמו היום בועז, אשר עשה עמי לא אמר אלא עשיתי עמו, דיותר ממה שבעה\"ב עושה עם העני העני עושה עם בעה\"ב.\n<b>והנה</b> העני המקבל צדקה לשם שמים כו', ראוי לו שלא לקבל צדקה אלא מאנשים צדיקים, ושיזכו על ידו, אבל לא מאנשים רשעים, כדמצינו באלישע דמאנשים צדיקים קיבל צדקה אבל מנעמן לא רצה לקבל, דאע\"פ שנעשה גר תושב לא רצה לקבל ממנו דלא היה כדאי שיזכה ע\"י אלישע.\n<b>וזהו</b> פי' הגמרא, הרוצה ליהנות יהנה כאלישע, פי' שיתכוין בלקחו הצדקה כדי לזכות את העשיר הנותן לו, א\"כ לא יקבל צדקה אלא מאנשי ישראל הצדיקים שהם כדאי לזכות על ידו, ולא יאמר כיון שמצוה הוא ליקח צדקה על דרך זה א\"כ ירדוף אחר זה לקחת דוקא כו'. ע\"כ אמר אעפ\"כ הרשות בידו, והרוצה שלא ליהנות אל יהנה כשמואל הרמתי, דמצינו שלא היה נהנה מהבריות.\n<b>תושלב\"ע</b>\n<b>א</b>שירה ואזמרה ואודה בקול נעים לאל ראשון ואחרון, <b>ה</b>נותן חלקנו בתורה ביושר וכשרון, <b>ר</b>ני רני השיטה בשיר ורון, <b>נ</b>א קומי עלזי חבצלת השרון. <b>ה</b>א-ל יושיע מהרה לעם אשר קרא שמם ישראל וישורון, <b>כ</b>בוד מרום מראשון בית מקדשנו יכונן וישיב לויים לשירן ולזמרן ולעבודתם בית אהרן, <b>ה</b>כל יודו ויברכו וישבחו לשמו עליונים ותחתונים העוברים לפניו כבני מרון, <b>נ</b>צח כולם יפארון וישוררין אין כא-ל ישורון. <b>י</b>ושם על לב לזכרון <b>ג</b>ודל אהבת עוז הדרת מלך בישורון, <b>ד</b>ום הוחילו לאלקים עוד נשיב לבצרון להודות על כל הטוב והכשרון, <b>ל</b>ברך על השלימים והמוגמרין. <b>ב</b>מהרה נזכה ותשיב העבודה למקדשינו ולשכת הגזית לסנהדרין, <b>ת</b>בנה ותכונן מקדש והיכל ומזבח והארון, <b>ו</b>ירננו שוכני עפר ויקיצו ישיני חברון, <b>ר</b>נה וצהלה בראש ההרים אשר במאדרי אדרון, <b>ה</b>עת גדול יהי כבוד הבית האחרון, במהרה בימינו אמן.\n<b>בעזר הבורא אשר במאמרו ברא שחקים</b>\n<b>נשלם ספרי כתר שם טוב בשני חלקים</b>",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>הרוצה ליהנות כו'</i> – ברכות י, ב. <i>נתון תתן לו</i> – ראה טו, י. <i>פתוח תפתח גו'</i> – שם יא. <i>כל הצריך ליטול כו'</i> – ירושלמי פאה פ\"ח סה\"ט. <i>ובמשנה היו לו כו'</i> – פאה פ\"ח מ\"ח. <i>גדול המעשה כו'</i> – ב\"ב ט, א. <i>האיש אשר עשיתי גו'</i> – רות ב, יט. <i>דיותר ממה שבעה\"ב כו'</i> – רו\"ר ה, ט. ויק\"ר לד, ח. <i>באלישע דמאנשים צדיקים קיבל</i> – מ\"ב ד, ח ואילך. <i>מנעמן לא רצה לקבל</i> – מ\"ב ה, טז. <i>דאע\"פ שנעשה גר תושב</i> – גיטין נז, ב.\n----- הערות וציונים -----\n<i>אם העני המקבל כו'</i> – ראה לקו\"ש ח\"ג ע' 908 בענין ויקחו לי – לשמי, דקאי על העני. וראה עוד מזה בתוי\"י ס\"פ ויקהל סט, א.\n<i>ראוי לו שלא לקבל אלא מאנשים צדיקים</i> – ראה עץ יוסף לע\"י ברכות שם. תוי\"י ס\"פ ויקהל סט, א, וכתונת פסים ר\"פ צו ב, סע\"ג. ולהעיר מב\"ק טז, ב.\n<i>לא יקבל אלא מאנשי ישראל כו'</i> – ראה לקו\"ש ח\"ח ע' 266. ולהעיר מזח\"ב קצה, א."]]],[300010522,"א\n\n<b>כוונת המקוה מהבעש\"ט ז\"ל</b>{*}\n(הועתק מספר פרי הארץ)\n<b>כשבא</b> אל המקוה יכוין שהמקוה הוא שם קנ\"א דהיינו <b>אהי\"ה</b> במלוי <b>ההי\"ן</b> כזה אל\"ף ה\"ה יו\"ד ה\"ה גמטריא קנ\"א כמנין מקו\"ה ועיקר יכוין שהמקוה התחתונה שאנו טובלים בו הוא בעצמו שם קנ\"א ע\"י השתלשלו' ויטבול פעם א' ויכוין שם קנ\"א כנ\"ל בשעת שהוא תחת המים ואח\"כ יכוין שם אגל\"א שהוא שם הגבורות היוצא מר\"ת הפסוק אתה גבור לעולם אדנ-י ויטבול פעם ב' ויכוין שם הנ\"ל ואח\"כ יכוין שם אל\"ד ויכוין שמשם אגל\"א נעשה מא\"ג ד' ונעשה שם אל\"ד ויטבול פעם ג' ויכוין שם הנ\"ל ואח\"כ יטבול פעם ד' בשעה שיהא ראשו תחת המים ישלוב השני שמות אהי\"ה ואל\"ד כזה אלף א ה ה ל יוד ה ד ד ויכוין את הדבר שמתפללי' עבורו שהוא בתוך השם הזה הוא נמתק שיעלה אותו כנז\"ל ויטבול פעם ה' וישלב את השם אהי\"ה פשוט עם השם אל\"ד פשוט כזה א א ה ל י ד ה ויכוין להעלות הדבר שמתפלל אל מדרי' עליונה של הבינה ואז נעשה הכל חסד ורחמים גמורי'.",[["","","----- הערות -----\nנדפס בסו\"ס סידור עם דא\"ח ע' ה' [שטו] והן כוונות אחרות מהנדפס לעיל ב, ג סימן ב'."]]],[300010523,"ב\n\n<b>כוונת התקיעות מהבעש\"ט ז\"ל</b>\n<b>בספר</b><sup data-n=\"1\">*</sup> שמועה טובה (ווארשא, תרח\"צ, ע' עו-עח) נדפסו \"כוונת התקיעות<sup data-n=\"2\">1</sup> מבעש\"ט זללה\"ה\", ובהקדמה שם כותב שנעתק מ\"כת\"י ישן נושן\" שחלק א' ממנו הי' \"טמון וגנוז בבית הרב הגה\"ק מקאָזניץ זצוקללה\"ה\" וחלק \"בגנזי הרב הגה\"ק מגור בעהמ\"ס שפת אמת\".\nוכנראה הם הכוונות שבסי' האריז\"ל – (הר\"ש מרשקוב). ולכאורה אין להביאור דאדה\"ז<sup data-n=\"3\">**</sup> שייכות אליהם. ועכצ\"ל שישנן עוד כוונות להבעש\"ט שונות מכוונות האריז\"ל (וכמו בכוונות המקוה).\nבכ\"ז, לשלימות הענין וכיון שלע\"ע לא מצאתי בשום מקום כוונות התקיעות מיוחסות להבעש\"ט נעתקו כאן<sup data-n=\"4\">2</sup>\n<b>כוונת התקיעות מבעש</b><b>\"</b><b>ט זללה</b><b>\"</b><b>ה.</b>\n<b>תקיעות דמיושב.</b>\n<b>תקיעה</b> אברהם עולה ומושך המוחין ונעשה כסא:\n<b>שברים</b> יצחק עולה ומתפשט עד סיום כל הוד:\n<b>תרועה</b> עלה אלקים יעקב דוד:\n<b>תקיעה</b> יעקב ומכניס נצח בחכמה הוד בבינה יסוד בדעת כ\"ז בפ\"א דספירה:\n<b>תשר</b><b>\"</b><b>ת ב</b><b>'</b> להמשיך המוחין <b>בפ</b><b>\"</b><b>ב</b>\n<b>תקיעה</b> אברהם ולהוציא מלאה פ\"ב ממוח בינה ולעשות כסא:\n<b>שברים</b> להמשיך חלק ב' מוח בינה ועיטרא דגבורה תוך לבוש הוד ולהכניסם:\n<b>תרועה</b> ימשוך מתתא לעילא עיטרא דגבורה:\n<b>תקיעה</b> יכניס נצח ומוח בחכמה הוד ומוח בבינה יסוד ומוח בדעת חלק ב' דמוחין בפ\"ב דחב\"ד ז\"א:\n<b>תשר</b><b>\"</b><b>ת ג</b><b>'</b> להמשיך המוחין לפ\"ג דחב\"ד דז\"א.\n<b>תקיעה</b> להוציא חלק ג' ממוח בינה ועיטרא דגבורה לעשות כסא:\n<b>שברים</b> מכניס בינה וגבורה תוך לבוש הוד:\n<b>תרועה</b> מושך חלק ג' ממוחין תוך לבוש [ ]<sup data-n=\"5\">1</sup>:\n<b>תקיעה</b> מכניס חלק ג' מפרקין קדמאין תוך פ\"ג דחב\"ד דז\"א:\n<b>תש\"ת.</b>\n<b>תקיעה</b> מכניס חלק א' מפ\"ב דחכמה בחסד ז\"א:\n<b>שברים</b> חלק א' ממוח בינה בגבורה דז\"א:\n<b>תקיעה</b> חלק א' ממוח דעת בת\"ת דז\"א:\n<b>תקיעה</b> מכניס חלק ב' מפ\"ב מוח חכמה בחסד ז\"א:\n<b>שברים</b> חלק ב' מפ\"ב מוח בינה בגבורה ז\"א:\n<b>תקיעה</b> חלק ב' מפ\"ב מוח דעת בת\"ת ז\"א:\n<b>תקיעה</b> חלק ג' מפ\"ב מוח חכמה בחסד ז\"א:\n<b>שברים</b> חלק ג' מפ\"ב מוח בינה בגבורה ז\"א:\n<b>תקיעה</b> חלק ג' מפ\"ב דדעת בת\"ת ז\"א:\n<b>תר\"ת.</b>\n<b>תקיעה</b> מכניס חלק א' מפ\"ג דחכמה בנצח ז\"א:\n<b>תרועה</b> חלק א' מפ\"ג דמוח בינה בהוד ז\"א:\n<b>תקיעה</b> חלק א' מפ\"ג דמוח דעת ביסוד ז\"א:\n<b>תקיעה</b> מכניס חלק ב' מוח חכמה בנצח ז\"א:\n<b>תרועה</b> חלק ב' מפ\"ג מוח בינה בהוד ז\"א:\n<b>תקיעה</b> חלק ב' מפ\"ג מוח דעת ביסוד ז\"א:\n<b>תקיעה</b> חלק ג' מפ\"ג מוח חכמה בנצח ז\"א:\n<b>תרועה</b> חלק ג' מפ\"ג מוח בינה בהוד ז\"א:\n<b>תקיעה</b> חלק ג' מפ\"ג מוח דעת ביסוד ז\"א:\n<b>תקיעות דמעומד.</b>\n<b>מלכיות.</b>\n<b>תקיעה</b> מתפשט בו פ\"א מפת דנצח אמא:\n<b>שברים</b> פ\"א מפת דהוד אמא:\n<b>תרועה</b> פ\"א מפת דיסוד אמא:\n<b>תקיעה</b> פ\"א מפת דנצח אמא:\n<b>תקיעה</b> פ\"ב מפת דהוד אמא:\n<b>שברים</b> פ\"ב מפת דיסוד אמא:\n<b>תקיעה</b> פ\"ב מפת דנצח אמא:\n<b>תקיעה</b> פ\"ג מפת דהוד אמא:\n<b>תרועה</b> פ\"ג מפת דיסוד אמא:\n<b>תקיעה</b> מתפשט בו מלכות דאמא:\n<b>זכרונות.</b>\n<b>תקיעה</b> פ\"א דחסד דנצח אמא בחסד נוק' דז\"א:\n<b>שברים</b> פ\"א דגבורה דהוד אמא בגבורה דנוק':\n<b>תרועה</b> פ\"א דת\"ת דיסוד אמא בת\"ת דנוק':\n<b>תקיעה</b> פ\"ב דחסד דנצח אמא בחסד דנוק':\n<b>תקיעה</b> פ\"ב דגבורה דהוד אמא בגבורה דנוק':\n<b>שברים</b> פ\"ב דת\"ת דיסוד אמא בת\"ת דנוק':\n<b>תקיעה</b> פ\"ג דחסד דנצח אמא בחסד דנוק':\n<b>תקיעה</b> פ\"ג דגבורה דהוד אמא בגבורה דנוק':\n<b>תרועה</b> פ\"ג דת\"ת דיסוד אמא בת\"ת דנוק':\n<b>תקיעה</b> מלכות דאמא מתפשט:\n<b>שופרות.</b>\n<b>תקיעה</b> פ\"א דחכמה דנוק':\n<b>שברים</b> פ\"א דבינה דנוק':\n<b>תרועה</b> פ\"א דדעת דנוק':\n<b>תקיעה</b> פ\"ב דחכמה דנוק':\n<b>תקיעה</b> פ\"ב דבינה דנוק':\n<b>תרועה</b> פ\"ב דדעת דנוק':\n<b>תקיעה</b> פ\"ב דחכמה דנוק':\n<b>תקיעה</b> פ\"ג דבינה דנוק':\n<b>תרועה</b> פ\"ג דדעת דנוק':\n<b>תקיעה</b> מלכות דאמא מתפשט:\n<b>מלכיות.</b><sup data-n=\"6\">2</sup>\n<b>פ\"א</b> דנצח דנוק' שהוא חכמה דנצח דנוק' בפ\"א דחסד ז\"א תורה מצד ז\"א:\n<b>פ\"א</b> דהוד נוק' שהוא בינה דהוד נוק' בפ\"א דגבורה ז\"א תורה מצידו:\n<b>פ\"א</b> דיסוד נוק' שהוא דעת דיסוד נוק' בפ\"א ת\"ת דז\"א תורה מצידו:\n<b>פ\"ב</b> נצח נוק' שהוא חסד דנצח דנוק' בפ\"ב דחסד ז\"א כתובים מצד נוק':\n<b>פ\"ב</b> דהוד נוק' שהוא גבורה דהוד דנוק' בפ\"ב גבורה ז\"א כתובים מצדה:\n<b>פ\"ב</b> יסוד נוק' שהוא ת\"ת דיסוד נוק' בפ\"ב ת\"ת ז\"א:\n<b>פ\"ג</b> דנצח נוק' נצח דנצחה בפ\"ג דחסד ז\"א:\n<b>פ\"ג</b> דהוד נוק' דהוד דהודה בפ\"ג דגבורה ז\"א:\n<b>פ\"ג</b> דיסוד נוק' דיסוד דיסודה בפ\"ג דת\"ת ז\"א:\n<b>לכן</b> אומרים בפסוק זה יהי' ה' אחד שיהי' הזיווג עמה תמיד ביסודה ויהיה יה יה פב\"פ ובתוך <b>פסוק</b> אחרון עטרת יסודה שהוא מלכות וזה ה' אלקינו לכוללה בתורה שבכתב ה' אחד מחב\"ד חג\"ת נה\"י עטרת ת\"ת ישראל נכלל תורה שבע\"פ עם תורה שבכתב:\n<b>זכרונות.</b>\n<b>פ\"א</b> דחסד נוק' בחכמה דז\"א:\n<b>פ\"א</b> דגבורה נוק' בבינה דז\"א:\n<b>פ\"א</b> דת\"ת נוק' בדעת הדעת דז\"א:\n<b>פ\"ב</b> דחסד נוק' בחסד החכמה דז\"א כתובים דלאה:\n<b>פ\"ב</b> דגבורה נוק' בגבורה דבינה דז\"א:\n<b>פ\"ב</b> דת\"ת נוק' בת\"ת דדעת ז\"א:\n<b>פ\"ג</b> שהוא נצח דחסד נוק' בנצח דחכמה ז\"א נביאים מצד נה\"י דאמא המתפשטים שם:\n<b>פ\"ג</b> שהוא הוד גבורה נוק' בהוד בינה ז\"א:\n<b>פ\"ג</b> שהוא יסוד ת\"ת נוק' ביסוד דעת ז\"א:\n<b>פסוק</b><sup data-n=\"7\">3</sup> לכלול מלכות דיסוד דת\"ת דנוק' בעטרת יסוד שבדעת דז\"א:\n<b>שופרות.</b>\n<b>לכלול</b> חב\"ד דנוק' בנה\"י דאמא שהם למעלה מחב\"ד ז\"א ולפי שיסוד דאמא סוד שופר שמשם יוצא הקולות נק' שופרות:\n<b>פ\"א</b> חכמה נוק' בפ\"א דנצח אמא שהוא חכמה דנצח אמא:\n<b>פ\"א</b> בינה דנוק' בפ\"א הוד אמא שהוא בינה דהוד אמא:\n<b>פ\"א</b> דעת נוק' בפ\"א דיסוד אמא שהוא דעת דיסודה:\n<b>פ\"ב</b> דחכמה נוק' בפ\"ב דנצח אמא שהוא חסד דנצחה:\n<b>פ\"ב</b> דבינה נוק' בפ\"ב דהוד אמא שהוא דבורה דהודה:\n<b>פ\"ב</b> דדעת נוק' בפ\"ב דיסוד אמא שהוא ת\"ת דיסודה:\n<b>פ\"ג</b> חכמה דנוק' בפ\"ג דנצח דאמא שהוא נצח דנצחה:\n<b>פ\"ג</b> בינה דנוק' בפ\"ג דהוד דאמא שהוא נצח דהודה:\n<b>פ\"ג</b> דעת דנוק' בפ\"ג דיסוד דאמא שהוא נצח דיסודה:\n<b>פסוק</b> אחרון מלכות שביסוד דדעת דנוקבי' במלכות שביסוד דאמא:",[["1","*","מכאן ועד התיבות \"נעתקו כאן\". וכן ההערות 1-2; 1-3 – נעתקו מרשימת כ\"ק אדמו\"ר זי\"ע."],["2","1","בסופן שם גם כוונות הפסוקים דמלכיות זכרונות שופרות דמוסף – ולקמן נעתקו גם הן."],["3","**","הנדפס בסידור עם דא\"ח בשער התקיעות ד\"ה להבין ענין תקיעת שופר."],["4","2","כמה יש להעיר בהשוואה להכוונות שבסי' האריז\"ל, ואכ\"מ.\n-----"],["5","1","כן הוא בס' שמועה טובה."],["6","2","כוונות הפסוקים דמוסף."],["7","3","כן הוא בס' הנ\"ל. וכנראה השמיט המדפיס תיבת <i>אחרון</i>."]]],[300010524,"ג\n\n<b>תורות</b><sup data-n=\"1\">*</sup><b> ופּתגמי הבעל שם טוב</b>\n<b>נלקטו מספרי רבותינו נשיאנו הקדושים ותלמידיהם</b>\n<b>ז' תורות שאמר מורנו הבעש\"ט</b><sup data-n=\"2\">**</sup>\nש\"פ כי תבוא, חי אלול תרנב, בגן עדן.\n. . . תורת הבעש\"ט{*} הראשונה – היתה אחר קבלת שבת{*} – ע\"פ<sup data-n=\"3\">1</sup> והי' כי תבוא אל הארץ גו', ופי' ארץ ל' מרוצה, כי בתיבת ארץ יש ב' פי', כדאיתא במדרש{*} למה נק' שמה ארץ שרצתה לעשות רצון קונה, וארץ ל' מרוצה{*},\nוהי' כי תבוא אל הארץ – אַז דו וועסט צוקומען צו דעם רצון ומרוצה – אשר ה\"א נותן לך נחלה וירשתה – וואָס דאָס איז אַ מתנה מלמעלה בירושה{*} בכל אחד מישראל, דאַרף זיין די עבודה אין דעם – וישבת בה – דאָס זאָל זיין בהתיישבות – ולקחת<sup data-n=\"4\">2</sup> גו' ושמת בטנא – מלביש זיין די אורות אין כלים – והלכת אל המקום – הוא ענין השגחה פרטית – אשר יבחר ה' אלקיך – אַז אַ איד גייט אין אַן אָרט, איז דאָס ניט וואָס ער גייט נאָר מ'פירט איהם, די השגחה העליונה. איז אַז ער קומט אין אַן אָרט איז די כוונה – לשכן שמו שם – לפרסם אלקות בעולם.\nהתורה השני' היתה אחר תפלת ערבית. אמר עוד הפעם התורה הקודמת והוסיף: והי' כי תבוא – בכדי אויף צוקומען צו דעם רצון וואָס איז במתנה באַ יעדערן, הוא ע\"י – לשכן שמו שם – מוסר נפש זיין זיך לפרסם אלקותו בעולם. וואס איז דער מסירת נפש אין דעם – מיט אַ ברכה ופסוק תהלים<sup data-n=\"5\">3</sup>.\nואמר אאמו\"ר{*}: בעלמא דין איז הפלאה שטייט אין השכלה, אָבער דאָרט – איז די הפלאה אין חומש<sup data-n=\"6\">4</sup> תהלים.\n– די צוויי תורות זיינען געווען בהקהל, עס זיינען געווען תלמידי הבעש\"ט ותלמידי תלמידיהם און זייערע חסידים, אויך פרויען,\nכמבואר במאמר להבין ענין זיווג הנשמות בג\"ע<sup data-n=\"7\">5</sup> – המאמר הוא מאדמו\"ר האמצעי ומסודר מאדמו\"ר הצמח צדק – ששם מדבר בענין נשמות דעלמא דדכורא ודעלמא דנוקבא, ומבואר בהגהה שנשמות דעלמא דנוקבא לאָזט מען צו הערן תורה בג\"ע.\nתורה הג'. די דריטע תורה פון בעש\"ט וואָס דער טאַטע האָט געהערט, הוא ע\"פ<sup data-n=\"8\">6</sup> היום הזה מצוך הוי' אלקיך לעשות את החוקים והמשפטים וגו', והקשה למה הקדים חוקים למשפטים, הסדר הוא אַז פריער שכל דערנאָך למעלה מהשכל (בלשון החסידים הוא עבודה ע\"פ טו\"ד . . . חסר).\nדי פערטע תורה הוא ע\"פ<sup data-n=\"9\">7</sup> משכיל לאיתן האזרחי, אשר הפי' כבר מבואר בחסידות<sup data-n=\"10\">8</sup>, ולבסוף התורה הוסיף הבעש\"ט לאמר, כי זריחת פשיטות העצמות הוא אצל הפשוטים שבישראל<sup data-n=\"11\">9</sup> יותר מכמו שהוא בבני תורה.\nדי תורה החמישית. כל התורה היא שמותיו של הקב\"ה<sup data-n=\"12\">10</sup>. בס\"י<sup data-n=\"13\">11</sup> איתא שלשה אבנים בונות ששה בתים. תיבת צהר יש לה ששה צירופים<sup data-n=\"14\">12</sup>, חמשה נגלים ואחד נעלם. הרץ, צרה רצה צהר. הרץ, שע\"י שרצים לדבר מצוה נעשה מצרה רצה{12}, והוא ע\"ד יהי רצון להמשיך רצון חדש, עד שנעשה צהר, עס ווערט ליכטיג. וסיים, לו ידעו כח שיש בצירופי אותיות התורה לא הי' אחד מישראל שלא הי' בקי בחומש ובתהלים.\nתורה הששית, ששמע אאמו\"ר מהבעש\"ט<sup data-n=\"15\">13</sup> הוא ע\"פ<sup data-n=\"16\">14</sup> אשרי העם יודעי תרועה ה' באור פניך יהלכון, ואמר, דער תכלית העבודה איז לב נשבר, תכלית אופן העבודה איז הצנע לכת, און וויבאַלד אזוי, איז דאָס אשרי העם יודעי תרועה, שיודעים איך להריע, ווי צו ברעכן זיך, אַז בפנימיות זיין<sup data-n=\"17\">15</sup> בלב נשבר, און בחיצוניות זיינען זיי שמח וואָס זיי זיינען זוכה זיין עבדי השם, און אויף דעם איז ער מבקש הוי', הוי' דלעילא, באור פניך יהלכון, ווי זיי וועלן זיין<sup data-n=\"18\">16</sup> זאָל זיין באור פניך.\nתורה השביעית<sup data-n=\"19\">17</sup>, ע\"פ<sup data-n=\"20\">18</sup> קומי אורי כי בא אורך וכבוד הוי' עליך זרח, דער מאמר איז געווען צו נשיאי ישראל, ואמר להם, אתם נשיאי ישראל וואָס איר לייגט אַוועק אַייער תורה ועבודה בשביל טובת הרבים, וואָס וועט זיין מיט אַייך, איז דאָס איז קומי אורי באור הפרטי להכללי<sup data-n=\"21\">19</sup> כי בא אורך . . . (חסר).\nסדר התורות, די דריטע איז געווען בסעודתא דחקל תפוחין, די פערטע און פינפטע בסעודתא דעתיקא, די זעקסטע במנחה, און די זיבעטע בסעודתא דזעיר אנפין.\n**********",[["1","*","אחדים – גם בתוספת הביאור."],["2","**","נעתקו עפ\"י שיחת כ\"ק אדמו\"ר (מהוריי\"ץ) נ\"ע שמע\"צ תרצ\"ז אָטוואָצק. מרשימת השומעים [ספר השיחות תרצ\"ז ע' 191 ואילך]. ב' תורות הראשונות – נדפסו גם ב\"היום יום\" חי אלול, וגם בקונטרס בפ\"ע (מאמרי חודש אלול תשכ\"ג), ומועתקות כאן הערות כ\"ק אדמו\"ר זי\"ע שם.\nביאורי כ\"ק אדמו\"ר זי\"ע לתורות אלו נדפסו לקמן ע' תה ואילך.\n<i>תורת הבעש\"ט</i>: הקדמה לתורות אלו – ראה לקו\"ד ח\"ב דף שכט ואילך. ספר השיחות תרצ\"ז ע' 166 ואילך (בתוספת הערות ומ\"מ). [ה\"פתיחה\" לתורות אלו נדפסו לקמן ע' תא ואילך].\n<i>אחר קבלת שבת</i>: פ' כי תבוא, חי אלול תרנ\"ב, בגן עדן.\n<i>כדאיתא במדרש</i>: ב\"ר פ\"ה, ח.\n<i>ל' מרוצה</i>: ראה תו\"א ד\"ה כי כאשר השמים (א, ג). ובארוכה בלקו\"ת לג\"פ רד\"ה עוד ביאור ע\"פ כי כאשר השמים (כא, ג ואילך). [אוה\"ת בראשית ח\"ג תפא, ב ואילך. ח\"ו תתרמג, א ואילך].\n<i>מתנה מלמעלה בירושה</i>: ראה ב\"ב (קכט, ב. קלג, א) בענין מתנה במי שראוי ליורשו. ונת' באוה\"ת להצ\"צ ביאור לד\"ה ויאמר יהונתן ס\"ה [בראשית ח\"א טז, ב ואילך].\n<i>ואמר אאמו\"ר</i>: כ\"ק אדמו\"ר מהורש\"ב נ\"ע.\n-----"],["3","1","תבוא כו, א."],["4","2","תבוא שם, ב."],["5","3","וראה לקוטי שיחות חלק ט ע' 338 ואילך."],["6","4","להעיר מדיוק לשון כ\"ק אדנ\"ע ששם (בג\"ע) ההפלאה היא ב<i>חומש</i> תהלים – בשינוי מלשון תורת הבעש\"ט: <i>ברכה</i> ופסוק תהלים (משיחת ש\"פ תבוא תשמ\"א)."],["7","5","אולי הכוונה לד\"ה זה שבמאמרי אדה\"ז ענינים קנא ואילך, שהוא הנחת אדמו\"ר האמצעי, כמ\"ש הצ\"צ בס' החקירה (נו, א): \"וכה\"ג מצאתי אח\"כ בכת\"י מו\"ח ז\"ל מ\"ש בחורף תקס\"ג מאדמ\"ו ז\"ל\", ותוכנו מבאר הצ\"צ בסהמ\"צ שלו (מצות פו\"ר פ\"ב (דרמ\"צ ג, א ואילך)). ומ\"ש ע\"ד המבואר בהגהה – לא מצאנו לע\"ע (<i>המו\"ל</i>)."],["8","6","תבוא כו, טז."],["9","7","תהלים פט, א."],["10","8","ראה לקו\"ת ר\"פ ראה (יח, א). סה\"מ: עטר\"ת ע' תריא. תרפ\"א ע' של. תרפ\"ה ע' ס. תרפ\"ו ע' קכה. תרח\"ץ ע' סז. קונטרס לימוד החסידות פ\"ג (אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ג ע' שלה)."],["11","9","ראה גם סה\"מ תרצ\"ו ע' 13."],["12","10","ראה זח\"ב פז, א. רמב\"ן בהקדמה לפירושו עה\"ת. יונת אלם פכ\"ט."],["13","11","פ\"ד מי\"ב (בקצת דפוסים – מט\"ז)."],["14","12","ראה גם ד\"ה מה טובו תרפ\"ט פ\"א (סה\"מ קונטרסים ח\"א מח, ב. סה\"מ תרפ\"ט ע' 204 ואילך. הועתק לקמן סימן ט)."],["15","13","הובא ברד\"ה אשרי העם תש\"ח (סה\"מ תש\"ח ס\"ע 284 ואילך. הועתק לקמן סימן סט)."],["16","14","תהלים פט, טז."],["17","15","בסה\"מ תש\"ח שם: זיינען זיי בלב נשבר."],["18","16","בסה\"מ תש\"ח שם: וואו זיי וועלן גיין."],["19","17","ראה לקוטי שיחות חט\"ז ע' 379.\nברשימה אחרת משיחה זו – נוסחא אחרת:\nקומי אורי כי בא אורך וכבוד הוי' עליך זרח – התורה הזאת אמרה לפני נשיאים ומנהיגי הדור – אמר: אתם נשיאי ישראל מנהיגי הדור, איר גיט אַוועק אייער תורה ועבודה, און איר זייט זיך מתעסק אין דרכי הכלל. פאַראַן דער אור פרטי וואָס איז פאַראַן אין יעדער נשמה, און פאַראַן דער אור כללי וואָס איז פאַראַן אין נשמות כלליות, קומי אורי דאָס איז דער אור פרטי וואָס איז דאָ אין עבודה בפועל, אורך דאָס איז דער אור כללי וואָס אין נשמות כלליות וואָס איז מיוחד און מובדל פון שאר נשמות, וואָס אַ כלי צו דעם איז אורי, דער אור פרטי. און דורך די ביידע, אור און אורך, איז וכבוד הוי' וואָס איז העכער לגמרי פון כלים, עליך זרח, מער ניט ווי בדרך זריחה."],["20","18","ישעי' ס, א."],["21","19","ברשימת השיחה שתח\"י: והכללי."]]],[300010525,"ד\n\nא, א: <i>בראשית ברא אלקים את השמים ואת הארץ</i>.\n<b>דער</b> בעש\"ט איז מפרש דעם פּסוק: בראשית – די התחלת העבודה איז, ברא אלקים, – מגלה זיין<sup data-n=\"1\">20</sup> דעם שם אלקים. את השמים ואת הארץ, – אין דעם שמים און ארץ<sup data-n=\"2\">21</sup>.",[["1","20","ברא – מלשון שמא הבריא – ניקב ויצא לחוץ – חולין מג, ב."],["2","21","ספר השיחות תש\"ה ע' 64. ספר המאמרים תש\"ט ע' 81 ועיי\"ש פירוש הצ\"צ. וראה ספר המאמרים תש\"ה ע' 74 באו\"א קצת: בראשית ברא אלקים את השמים ואת הארץ, ופי' מורנו הבעש\"ט נ\"ע דבראשית דתחלת העבודה היא ברא אלקים היינו לגלות הכוונה דשם אלקים והוא את השמים ואת הארץ, דאפשרות התגלות הכוונה דשם אלקים הוא ע\"י ההתבוננות בשמים ובארץ, את השמים הם הנבראים דצבא השמים ואת הארץ הם הנבראים דצבא הארץ, ובהם ועל ידם יודעים ומשיגים הכוונה דשם אלקים. וראה רד\"ה בראשית תש\"כ (תורת מנחם – התוועדויות תש\"כ ח\"א ע' 114)."]]],[300010526,"ה\n\n<b>בראשית,</b> התחלת העבודה בעבודת ה' היא, <i>ברא</i>, פירושו גילוי, <i>אלקים</i>, לגלות את הכוונה הפנימית והעצמית דשם אלקים, כאמור<sup data-n=\"1\">22</sup> ה' הוא האלקים, אשר על ידם יתגלה הפנימית ד<i>א</i>ת <i>ה</i>שמים <i>ו</i>את <i>ה</i>ארץ, שהם הד' אותיות <i>אלף</i>, <i>הא</i>, <i>ויו</i>, <i>הא</i><sup data-n=\"2\">23</sup>, משם הוי' דלעילא שהם תכלית הבריאה ועלייתה בא\"ס ב\"ה<sup data-n=\"3\">24</sup>.",[["1","22","ואתחנן ד, ה. מלכים-א ח, ס."],["2","23","ע\"ד השם אהו\"ה ראה השמטות לזוהר ח\"א רנא, א. שערי אורה ד\"ה יביאו לבוש פצ\"ב. קהלת יעקב בערכו ובהשמטות."],["3","24","מכתב כ\"ק אדמו\"ר מהוריי\"צ (ספר המאמרים תש\"ח ע' 79. אגרות-קודש שלו ח\"ט ע' שכט), ושם לפנ\"ז: קבלה מהוד כ\"ק אבותינו רבותינו הק' מדור לדור, אשר אחת התורות הראשונות שפרסם הוד כ\"ק רבינו הזקן, כשחזר ממעזריטש מעוטר בעטרת תפארת עוז הנשיאות של יסוד העבודה ועמוד התורה של חב\"ד, היתה (אחרי ההקדמה הלזו:\nהערט די תורה וואָס מורנו הבעל שם טוב האָט מקבל געווען אין היכל המשיח און זייט זי מפרסם בשמם יחד עם ברכתם עס זאָל נתקבל ווערן אין די אידישע הערצער בפּנימיות). [ההמשך בפנים]."]]],[300010527,"ו\n\n<b>בראשית</b> ברא אלקים, בראשית איז ענינו ב' ראשית<sup data-n=\"1\">25</sup>, עס זיינען פאַראַן צוויי ראשית'ן, ראשית פון בריאת העולם, דער וועלטלעכער בראשית און דער תורה ראשית. בראשית ברא אלקים, די ב' ראשית'ן זיינען בכדי עס זאָל זיין ברא{20} אלקים מען זאָל מגלה זיין די אמיתית הכוונה פון דעם שם אלקים. ספירת הכתר איז ראשית און ספירת החכמה איז ראשית<sup data-n=\"2\">26</sup>. דער ראשית פון ספירת הכתר איז העלם דער ראשית פון ספירת החכמה איז גילוי, ראשית חכמה יראת ה'<sup data-n=\"3\">27</sup>, דער אור וחיות פון חכמה וואָס איז מאיר אין שבת בראשית ווערט נמשך על כללות השנה, וואָס אַלע טעג פון שנה, הן די ימי החול שבת ומועדים הכלליים, הן די מועדים הפרטים פון יעדער יחיד, יום הכניסה לחדר, יום הבר מצוה און אַנדערע ימי חיי האדם ומאורעותיו זיינען זיי אַלע מקבל פון דעם שבת בראשית<sup data-n=\"4\">28</sup>.",[["1","25","ראה רש\"י ורמב\"ן עה\"פ."],["2","26","ראה תורת חיים בתחלתו."],["3","27","תהלים קיא, י."],["4","28","שיחת י\"ד תשרי ה'שי\"ת (ספר השיחות ה'שי\"ת ע' 356). נתבאר בשיחת ש\"פ בראשית – התוועדות א' וב' – תשי\"ד (תורת מנחם התוועדויות תשי\"ד ח\"א ע' 106 ואילך. ע' 114 ואילך).\nובמכתב כח תשרי תש\"י (אגרות-קודש ח\"ג ע' רא): ואחתום בפתגם כ\"ק מו\"ח אדמו\"ר שליט\"א: איך וועל זאָגן אַ וואָרט פון די רביים בשם הוד כ\"ק רבינו הזקן וואָס ער האָט געהערט פון זיין רבין דעם מגיד בשם רבו הבעש\"ט נ\"ע: בראשית ברא, ראשית איז חכמה ראשית חכמה יראת ה', דער אור וחיות פון חכמה וואָס איז מאיר אין שבת בראשית ווערט נמשך על כללות השנה, וואָס אַלע טעג פון כל השנה זיינען מקבל פון שבת בראשית!\nוראה לקוטי שיחות ח\"ב ע' 658. ח\"א ע' 1. ובספר השיחות תש\"ה ע' 65: עס איז דאָ אַ מאמר פון הוד כ\"ק רבינו הזקן אַז די הארה פון שבת בראשית איז מאיר בכל שבתות השנה. הוד כ\"ק אדמו\"ר הרה\"ק האמצעי איז מאריך אין דעם. עי\"ש הביאור בזה.\nוראה שיחת יום ש\"ק בראשית תש\"ז (ספר השיחות תש\"ז ע' 80): דער אַלטער רבי קומענדיג אין ליאזנע האָט ער מיטגעבראַכט מיט זיך פון מעזריטש דריי זקנים וואָס זיינען נאָך געווען ביי מורנו הבעש\"ט.\nדער אַלטער רבי האָט געהערט פון די זקנים הנ\"ל אַ תורה וואָס זיי האָבן געהערט פון בעש\"ט, דער תוכן פון דער תורה איז וועגן מעלת שבת בראשית, דבר בזה מעלת החכ' על כתר און די הפלאה פון כתר וואָס חכ' איז מקבל פון איר.\nדער אַלטער רבי האָט די תורה מקבל געווען אין נקודות, און ער האָט דאָס שוין גערעדט אין זיינע אותיות – אויף זיין \"עברי\"."]]],[300010528,"ז\n\nבראשית א, ה: <i>ויהי ערב ויהי בוקר</i>.\n<b>איתא</b> במדרש<sup data-n=\"1\">29</sup> ויהי ערב אלו מעשיהן של רשעים ויהי בוקר אלו מעשיהן של צדיקים, ואיני יודע באיזה מהן חפץ, כיון דכתיב<sup data-n=\"2\">30</sup> וירא אלקים את האור כי טוב, הוי במעשיהן של צדיקים הוא חפץ. ותמוה, איך שייך קס\"ד שהוא חפץ במעשה רשעים, ומבאר הבעש\"ט, דיש תועלת ויתרון לאור מן החושך, היינו שמעלת יתרון האור ניכרת מצד החשך, וכן מעלת החכם ניכרת מצד הטיפש, מעלת הצדיק מצד הרשע וכו'. וזהו ואיני יודע באיזה מהן חפץ, דכיון שגם מעשה הרשעים הוא כסא למעשה צדיקים, יש מקום לומר שהכל נכנס באחדות אחד ח\"ו, לכך נאמר וירא אלקים את האור כי טוב אלו מעשיהן של צדיקים, כי במעשה הרשעים צריך הבדלה<sup data-n=\"3\">31</sup>.",[["1","29","ב\"ר פ\"ב, ה. וראה שם פ\"ג, ח."],["2","30","בראשית א, ד."],["3","31","ד\"ה באתי לגני תשל\"א (ספר המאמרים מלוקט ח\"ה ע' קנז ואילך), ומציין שם לצפנת פענח (קד, ב) ובן פורת יוסף (מו, ג) להרה\"ק כו' ר' יעקב יוסף מפולנאה. הועתק בספר בעש\"ט עה\"ת ח\"א סמ\"א ואילך."]]],[300010529,"ח\n\nנח ו, טז: <i>צהר תעשה לתבה</i>.\n<b>וזהו</b> צהר אור תעביד לתיבותא<sup data-n=\"1\">32</sup>, דאמר רבינו ז\"ל בשם הבעש\"ט<sup data-n=\"2\">33</sup> דתיבה הם אותיות התפלה וצהר תעשה לתיבה שצריכים לעשות שהאותיות יהי' מאירים, והיינו כאשר הם באים בהרגש פנימי ובהתבוננות דזהו\"ע לטישת האבנים שיאירו<sup data-n=\"3\">34</sup>.",[["1","32","תרגום אונקלוס עה\"פ."],["2","33","ראה אוה\"ת נח ח\"ג תרמ, א: והנה אדמ\"ו נ\"ע פי' בשם הבעש\"ט נ\"ע דתבה היינו ג\"כ תיבות התפלה."],["3","34","ספר המאמרים תש\"ז ע' 200. וראה המשך תער\"ב ח\"א ע' קעג ואילך. ספר המאמרים פר\"ת ע' קכה ואילך."]]],[300010530,"ט\n\nנח ו, טז. ז, א: <i>צהר תעשה לתבה . . בא אתה וכל ביתך אל התבה</i>.\n<b>. . . ושלשה</b> אותיות בונות ששה בתים<sup data-n=\"1\">35</sup> כמו אותיות הצ\"ר, שיש לו ששה צירופים וידוע בקבלה רבי מפי רבי ממורנו הבעש\"ט נ\"ע דבצירוף זה הרי יש בו ג' עקרים וג' מסתעפים העקרים הם הצר, רצה, צהר. ואמר מורנו הבעש\"ט נ\"ע<sup data-n=\"2\">36</sup> דע\"י האותיות דתורה ותפלה שהו\"ע בא אל התיבה, דתיבה הם אותיות התורה והתפלה ובא אל התיבה הוא הכניסה בתוך האותיות של תורה ותפלה, לערנען מיט אַ חיות און דאַוונען מיט אַ חיות. דהחיות מורה על פנימיות הרצון שהו\"ע רצה, הנה עי\"ז נעשה צה\"ר לתיבה, דבכח זה מהפכים את הצר\"ה של הצ\"ר הצורר ר\"ל, לצה\"ר<sup data-n=\"3\">37</sup> וע\"ד דכתיב<sup data-n=\"4\">38</sup> ועת צרה היא ליעקב, וממנה יושע דלא זו בלבד שיפטר מן הצרה, אלא עוד כי וממנה יושע, דמן הצרה ההיא תצא לו עוד ישועה. דזהו\"ע צהר שמאיר אור רב, וכמו בצהרים שהוא תוקף זריחת השמש כן כתיב<sup data-n=\"5\">39</sup> ואוהביו כצאת השמש בגבורתו<sup data-n=\"6\">40</sup>.",[["1","35","ספר יצירה פ\"ד מי\"ב (בקצת דפוסים – מט\"ז)."],["2","36","ראה צוואת הריב\"ש סימן עה. אור תורה להרב המגיד ז, ב. הובא באוה\"ת נח ח\"ג תריד, א. תרכז, א (ושם: לפי' הריבעש\"ט זצוק\"ל דהתיבה רומז לתיבות התפלה והתורה הרי הם מבחי' חו\"ב שלמעלה משבירת הכלים). וראה ספר השיחות תרצ\"ו ע' 148: מה שמבואר בחסידות בא אתה כו' אל התיבה, ופי' תיבה מלשון תיבות התורה והעבודה, שצריכים לכנוס בהתיבה עם כל כחות הנפש, מקורו הוא מהבעש\"ט. וראה לקוטי שיחות חלק א ע' 11."],["3","37","ראה גם שיחת יום שמח\"ת תרצ\"ג סכ\"ג (לקוטי דיבורים ח\"א ט, סע\"ב ואילך): הבעש\"ט נ\"ע גילה, ותלמידיו רבותינו הק' ביארו ושכללו, כי בכח כל אחד מישראל ע\"י הדביקות באותיות התורה והתפלה, להפוך מצר\"ה לצה\"ר. וראה נועם אלימלך עה\"פ. הובא באוה\"ת נח ח\"ג תרמ, ב. המשך תער\"ב ח\"א ס\"ע קעג."],["4","38","ירמי' ל, ז."],["5","39","ספר שופטים ה, לא."],["6","40","ד\"ה מה טובו תרפ\"ט (ספר המאמרים קונטרסים ח\"א מח, ב. ספר המאמרים תרפ\"ט ע' 204 ואילך). וראה גם ד\"ה צהר תש\"ב (ספר המאמרים תש\"ב ע' 47)."]]],[300010531,"י\n\n<b>כמו</b> שאמר מורנו הבעש\"ט נ\"ע בפי' המאמר במד\"ר (ויקרא פי\"ג) אמר ר' אחא וצריך יהודאה לחירובא (חרובין) עביד תתובא, דע\"י התשובה באמת בעת צרה ר\"ל מהפכין את הצרה עצמה לצהר, דצרה היא מצוקה וחשך וע\"י התשובה הנה היא עצמה נהפכת לאור, וכמ\"ש{38} ועת צרה היא ליעקב וע\"י התשובה הנה וממנה בעצמה יושע<sup data-n=\"1\">41</sup>.",[["1","41","סד\"ה מה יפית תרצ\"ט (ספר המאמרים תרצ\"ט ע' 161. ה'שי\"ת ע' 211). וראה ספר המאמרים אידיש ע' 55. לקוטי שיחות חלק ב ע' 352."]]],[300010532,"יא\n\nנח ז, א: <i>בא אתה וכל ביתך אל התבה</i>.\n<b>אַלעמען</b> איז גוט בעקאַנט די תורה וואָס דער בעש\"ט זאָגט אויף דעם פסוק בא אל התיבה, וואָס דער בעש\"ט זאָגט אַז אַ נשמה קומט אַראָפּ אויף דער וועלט און דער מענטש ווערט פאַרנומען מיט די צרכי החיים אויף מפרנס זיין בני ביתו מיגיע כפּיו – דורך אַרבעט – וואָס ווי ידוע האָט ער – דער בעש\"ט – געהאַלטן אַז אידן בעדאַרפן זיך פאַרנעמען זיך מיט אַרבעט מעהרער ווי מיט האַנדעל – איז אַז מי איז פאַרנומען מיט דער אַרבעט און די דאגות פון פּרנסה נעמען אַרום דעם מענטשן אַז ער קאָן חלילה פאַרטרינקען ווערן, איז די עצה אויף דעם בא אל התיבה, מדבק זיין זיך אין די ווערטער פון תפלה וואָס מי דאַוונט און די ווערטער פון תורה וואָס מי לערנט, און בזכות די דביקות אין די הייליקע ווערטער פון תפלה און תורה, זאָגט דער בעש\"ט וועט מגין זיין אַז אתה ובניך אשתך ונשי בניך וועלן געהאָלפן ווערן מהשי\"ת אין אַלץ וואָס מי בעַדאַרף. די דביקות אין אותיות התפלה און אותיות התורה איז אין תורת מורנו הבעש\"ט איינע פון די גרעסטע מיטלען אויף שטייגן אין די העכסטע רוחניות'דיקע דרגות. דביקות זאָגט דער בעש\"ט איז די שליסל וואָס עפנט אַלע שלעסער, און דאָס – מדבק זיין זיך אין די ווערטער פון תפלה און תורה – איז באַ יעדן אין האַנט, יעדער איד אַפילו דער גאָר פּשוט'ר קאָן צוקומען צו די העכסטע דביקות.\nער – דער בעש\"ט – זאָגט אַז די אמת'ע תמימות'דיקע אמונה וואָס אַ פּשוט'ר איד און אַ פּשוטע אידענע זאָגן תהלים איז דאָס די גרעסטע דרגא פון דביקות, די נשמה איז באַ אַלעמען גלייך, נאָר בא דעם יודע ספר און תלמיד חכם איז די דביקות עפנט די שערי ידיעה אין תורה, וואָס באַ די פּשוט'ע אידן וואָס קאָנען ניט לערנען איז דאָס ניט פאַראַן, אָבער דאָס וואָס דער זכות פון דער דביקות אין די ווערטער פון תפלה ערוועקט דעם אויבערשטנס ברוך הוא רחמים, און איז פּועל אַ ישועה פאַר דעם וואָס זאָגט די הייליקע ווערטער בדביקות איז דאָס באַ דעם פּשוט'ן אידן און דער פּשוט'ר אידענע גאָר גלייך ווי באַ דעם גרעסטן תלמיד חכם<sup data-n=\"1\">42</sup>.",[["1","42","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' קצט ואילך. וראה ספר השיחות תרצ\"ו ע' 23: די תורה וואָס דער רבי האָט געזאָגט, וואָס ער האָט געהערט פון דעם מעזריטשער מגיד נ\"ע בשם כ\"ק מורנו הבעש\"ט נ\"ע, בא אל התבה, אַז מען בעדאַרף זיך צו קלעפּן – דביקות – און אַריין גיין אין די ווערטער פון תפלה און תורה, און די פּשוט'ע אידן וואָס ווייסן ניט דעם טייטש פון די ווערטער, זאָלן זאָגן די ווערטער, אַפילו ניט וויסנדיק דעם טייטש פון די ווערטער.\nדי תורה האָט געבראַכט פיעל טויזענטער פּשוט'ע אידן צו דעם, אַז זיי האָבן כסדר געהאַלטן אין איין זאָגן תהלים אָדער חומש אויסנווייניג, יעדערער וואָס ער האָט זיך געקאָנט אויסלערנען."]]],[300010533,"יב\n\nלך לך יב, יא: <i>הנה נא ידעתי כי אשה יפת מראה את</i>.\n<b>עס</b> ווערט געבראַכט בשם הבעש\"ט<sup data-n=\"1\">43</sup>, אַז אברהם אבינו, זייענדיק אַ מרכבה צום אויבערשטן ביז אַז חז\"ל<sup data-n=\"2\">44</sup> זאָגן האבות הן הן המרכבה און ער איז געווען \"מקושר במחשבתו תמיד בשרש המחשבה\", דערפאַר האָט ער ביז דאַן ניט געוואוסט אַז שרה איז אַ יפת מראה – טראָץ דעם וואָס ער האָט איר אויך פריער געזעהן<sup data-n=\"3\">45</sup>, ווייל זיין מחשבה איז געווען שטענדיק \"שלא במקום הראי' הגשמית\". אָבער קומענדיק נאָענט צו מצרים, האָט דער אויר פון מצרים געווירקט (בדקות דדקות<sup data-n=\"4\">46</sup>) אויף אים, אַז \"ירד ממדרגתו והתחילו לבא אצלו מחשבות מבחי' השבירה\", ביז צו \"עתה ידעתי כי אשה יפת מראה את\"<sup data-n=\"5\">47</sup>.",[["1","43","מאור עינים ס\"פ שמות (ד\"ה וזהו רבות מחשבות)."],["2","44","ב\"ר פמ\"ז, ו. פפ\"ב, ו."],["3","45","שהרי אסור לאדם לקדש אשה עד שיראנה (קידושין מא, א). ועפ\"ז מתורצת קושיית המהרש\"א בחדא\"ג לב\"ב טז, א."],["4","46","ראה לקו\"ש ח\"ה ע' 63 ואילך. שם ע' 61 הערה 38."],["5","47","לקו\"ש שם ע' 60."]]],[300010534,"יג\n\nויצא כח, יג: <i>הארץ אשר אתה שוכב עלי' לך אתננה</i> (<i>מלמד שקפלה הקב\"ה לכל ארץ ישראל והניחה תחת יעקב אבינו, שתהא נוחה ליכבש לבניו </i>(חולין צא, ב)).\n<b>תורת</b> הבעש\"ט<sup data-n=\"1\">48</sup> בהמעלה (בנוגע ליעקב עצמו) דקיפל הקב\"ה לכל א\"י והניחה תחת יעקב – דלא הי' צריך לנסוע ממקום למקום לברר הניצוצין דשם<sup data-n=\"2\">49</sup>.",[["1","48","כתונת פסים – לבעל התולדות – פ' בהעלתך. כתר שם טוב סימן טו."],["2","49","לקוטי שיחות שם ע' 488. ושם: ודוקא יעקב – תורה."]]],[300010535,"יד\n\nויצא ל, מב: <i>והיו העטופים ללבן והקשורים ליעקב</i>.\n<b>וביאור</b> הדבר ידוע ע\"פ מ\"ש במ\"א בשם הבעש\"ט ז\"ל ביאור ענין והיו העטופים ללבן והקשורים ליעקב שבחי' עטופים הוא ממוצע בין קדושה לנוגה שצ\"ל ג\"כ ממוצע ביניהם ואף שבחי' נוגה הוא הממוצע בין הקדושה לגקה\"ט אך באמת גם בין קדושה לנוגה יש ממוצע ונק' עטופים ולא נת' זה בע\"ח. והענין כי כל סט' דקדושה נק' קשורים ע\"ש שהם קושרים וקולטים בתוכם היטב האור וההשפעה הנמשך להם מא\"ס ב\"ה שנקלט בתוכן ההתפעלות והביטול לאלקות וזהו והיו הקשורים ליעקב משא\"כ בחי' עטופים היינו שאין נקשר ונקלט בתוכן ההשפעה כ\"כ ומחמת זה אין יכולי' להשפיע אח\"כ ההשפעה זו לזולתם כיון שלא נקשרה ונקלטה תחלה בתוכן כו'. וזהו שרש ומקור להתהוות הקליפות שאומרים הב הב ולא להשפיע לזולתם כו' ע\"ש וזהו ממוצע בין קדושה לק\"נ שבחי' ק\"נ הוא למטה מבחי' זו שנק' קליפה ממש<sup data-n=\"1\">50</sup>.",[["1","50","אוה\"ת מטות ע' א'שלא. וראה גם בשם הבעש\"ט ביאורי הזוהר להצ\"צ ח\"א ע' רמה. ולהעיר ממאמרי אדמו\"ר הזקן: תקס\"ה ח\"א ע' מז ואילך; פרשיות ח\"א ע' קסט ואילך. שערי תשובה לאדמו\"ר האמצעי ח\"א נז, א ואילך. ספר המאמרים תרנ\"ט ס\"ע קכט. פר\"ת ס\"ע קד."]]],[300010536,"טו\n\nויצא לא, כג: <i>וירדוף אחריו</i>.\n<b>אי'</b> בשם הבעש\"ט ז\"ל<sup data-n=\"1\">51</sup> ובשם הה\"מ ז\"ל<sup data-n=\"2\">52</sup> שמה שרדף לבן אחר יעקב הוא לפי שיעקב השאיר אחריו אותיות התורה שלא בירר אותם, ולזאת רדף אחריו ליתן אותיות אלו שמהם נתוסף פרשה בתורה<sup data-n=\"3\">53</sup>.",[["1","51","הובא במאור עינים ר\"פ ויצא."],["2","52","הובא באור המאיר עה\"פ. ונתבאר באוה\"ת ויצא ח\"ה תתסט, א ואילך (בכת\"י ב' מהמאמר באוה\"ת שם כתוב: מ\"ש בשם הבעש\"ט ובשם הרב המגיד נ\"ע דמש\"ה רדף לבן אחר יעקב כו'). לקוטי שיחות חלק א ע' 80. חלק טו ע' 260 ואילך."],["3","53","ספר המאמרים תרס\"ג ח\"א ע' עו. וראה ספר המאמרים פר\"ת ע' צט. ע' קפג."]]],[300010537,"טז\n\nוישלח לה, ה: <i>ויהי חתת אלקים על הערים</i>.\n<b>כתיב</b> ויהי חתת אלקים וגו' חתת ר\"ת חומש תהלים תניא<sup data-n=\"1\">54</sup>, והבקי באותיותיהם משבר כל ההעלמות וההסתרים<sup data-n=\"2\">55</sup>.",[["1","54","ראה גם ספר השיחות תרצ\"ו ע' 145 ואילך."],["2","55","מכתב כ\"ק אדמו\"ר מהוריי\"צ – קיצורים והערות לתניא ע' קכז. אגרות-קודש שלו ח\"ד ע' רסח. ושם לפנ\"ז: \"[סיפר אדמו\"ר הצמח צדק:] בשנת תר\"ג כשנקראתי לאסיפת הרבנים בפעטערבורג הייתי על ציון אמי הרבנית הצדקנית בליאזנא, ותספר לי, אשר בגלל המסירות נפש שהי' לה בשביל חסידים וחסידות זכתה להיות גם בהיכל הבעש\"ט לעורר רחמים עבורי, ותבקש מהבעש\"ט שיתן לה איזה סגולה עבורי שאוכל בעזה\"י לעמוד נגד המנגדים על תורת החסידות. ויאמר לה הבעש\"ט בנך הנהו בקי בחמשה חומשי תורה בתהלים ובתניא בע\"פ באותיותי'. וכתיב ויהי . . .\" [ההמשך בפנים]."]]],[300010538,"יז\n\nמקץ מג, י: <i>כי לולא התמהמהנו כי עתה שבנו זה פעמים</i>.\n<b>דער</b> רבי האָט אונז געזאָגט, וואָס ער האָט געהערט פון דעם רבי'ן דעם בעש\"ט נ\"ע.\nכי לולא התמהמהנו כי עתה שבנו זה פעמים, שבנו פעמים הם שני אופני תשובה, א) תשובה כללית דר\"ה בקבלת עול מלכות שמים. ב) תשובה פרטית דיוהכ\"פ לפרט חטאיו לכבסם ולהטהר. ושתי תשובות הללו תלויות בחשבון הנפש שהאדם עושה בחדש אלול. וזהו כי לולא התמהמהנו. לולא אותיות אלול, לולא התמהמהנו, כי האדם מתמהמה ומאריך בחשבון נפשו בחדש אלול הנה אז שבנו פעמים, כלומר לפי אופן זה תהי' העבודה בשני אופני התשובה דר\"ה ויוהכ\"פ.\nאמנם ההכנה דחדש אלול היא הכנה כללית, וצריכה להיות גם הכנה פרטית, שההכנה הפרטית לעבודה דר\"ה היא בימי הסליחות בבקשת רחמים ותחנונים, כעבדים המתחננים אל אדונם בבקשת סליחה בהבנת האמת דלך ה' הצדקה ולנו בושת הפנים. וההכנה פרטית להעבודה דיוהכ\"פ היא בהימים שבין כסא לעשור<sup data-n=\"1\">56</sup>.",[["1","56","מכתב כ\"ק אדמו\"ר מהוריי\"צ בקובץ מכתבים א (נדפס בסו\"ס תהלים אהל יוסף יצחק ע' 204). אגרות-קודש שלו ח\"ד ע' קלא ואילך. ושם לפנ\"ז:\nיש ספור ארוך, מקובל מפי הוד כ\"ק אבותינו רבותינו הק' זצוקללה\"ה נבג\"מ זי\"ע, אודות אחת התורות אשר אמר הוד כ\"ק רבינו הזקן – בעל התניא ושלחן ערוך – בשבת מברכין חדש אלול שנת תקנ\"ה, מה ששמע מפי מורו ורבו הרב המגיד ממעזריטש בשם מורנו הבעש\"ט נ\"ע. ואלו דברי קדשו: [ההמשך בפנים]. וראה לקוטי שיחות ח\"ב ע' 623-622."]]],[300010539,"יח\n\nשמות ג, ב-ג: <i>וירא מלאך הוי' אליו בלבת אש מתוך הסנה וירא והנה הסנה בוער באש והסנה איננו אוכל, ויאמר משה אסורה נא ואראה את המראה הגדול הזה</i>.\n<b>דער</b> רבי, דער מעזריטשער מגיד, האָט פאַר מיר איבערגעזאָגט אַ תורה וואָס ער האָט געהערט פון רבי'ן מורנו הבעש\"ט:\nוירא מלאך הוי' אליו בלבת אש מתוך הסנה וירא והנה הסנה בוער באש והסנה איננו אוכל, ויאמר משה אסורה נא ואראה את המראה הגדול הזה. דער תרגום איז מפרש ואתגלי מלאכא דה' לי' בשלהובית אשתא מגו אסנא. ואתגלי הייסט התגלות. דער ענין פון התגלות איז אַז יעדער נאָך זיין דרגא זאָל באַנעמען דעם גילוי. התגלות איז דער טייטש אַז דער גילוי קען צוגענומען ווערן אויך אפילו אין די נידעריקע דרגות, דערפאַר איז אויפ'ן פסוק<sup data-n=\"1\">57</sup> וירד הוי' על הר סיני זאָגט דער תרגום ואתגלי ה' על טורא דסיני, וואָס דער תרגום פון וירד איז דאָך ונחת, ווי אויף דעם פּסוק<sup data-n=\"2\">58</sup> וירד יהודה זאָגט דער תרגום ונחת יהודה, אויפ'ן פּסוק<sup data-n=\"3\">59</sup> וירד הגבול זאָגט דער תרגום ונחת תחומא<sup data-n=\"4\">60</sup>, נאָר אויפ'ן פּסוק<sup data-n=\"5\">61</sup> ארדה נא זאָגט דער תרגום אתגלי כען, טייטשט ער דאָ דעם ארדה ווי דעם וירד פון מתן תורה וואָס די כוונה איז התגלות, וואָס התגלות מיינט אַ גילוי וועלכער קען צוגענומען ווערן אויך אַפילו אין די גאָר נידעריגסטע דרגות, ווי אין מתן תורה איז געווען אַז אַלע, פון דער העכסטער דרגא ווי משה רבינו ביז דעם פּחות שבישראל, האָבן מקבל געווען פון מתן תורה, און דאָס מיינט דער תרגום ואתגלי מלאכא דה' אַז דאָס איז אַ ענין פון התגלות.\nוואָס איז די התגלות בלבת אש זאָגט רש\"י בשלהבת של אש לבו של אש. וואו באַווייזט זיך דער שליח השם – אין דער האַרץ פון פייער. די האַרץ פון פייער איז די כוונה, די פּנימיות – ערנסטע תמימות'דיקע פאַרקאָכטקייט וואָס דאָס איז דער רשפי' רשפּי אש שלהבת י\"ה<sup data-n=\"6\">62</sup>.\nוואו איז דער לבת אש, די האַרץ פון פייער, מתוך הסנה. זאָגט רש\"י ולא אילן אחר משום עמו אנכי בצרה<sup data-n=\"7\">63</sup>. צרה איז די כוונה עולם הזה. עולם הזה ווערט אָנגערופן צרה ווייל ער איז אַ מקום צר. די עולמות העליונים וואו דער אור אין סוף איז בגילוי זיינען אַ מקום רחב, אָבער דער עולם הזה וואו דער אור אין סוף איז מלובש בדרכי הטבע, איז דאָס אַ מקום צר און דערום ווערט עולם הזה אָנגערופן צרה. די כוונה העליונה איז אַז דורך דער עבודה אין לימוד התורה און קיום המצות זאָל מען מאַכן פון צרה צהר<sup data-n=\"8\">64</sup>, באַלייכטן די וועלט מיט דעם אור התורה ומצות.\nווי עס שטייט<sup data-n=\"9\">65</sup> כי האדם עץ השדה, עס זיינען פאַראַן עצי מאכל ווי ר' יוחנן זאָגט (תענית ז, א), אַז דאָס זיינען די תלמידי חכמים און עס איז פאַראַן אַ סנה. דער לבת אש איז אין סנה. ת\"ח וועלכע לערנען תורה זיינען אש ווייל תורה נמשלה לאש<sup data-n=\"10\">66</sup>. אָבער דאָס איז ניט כי איננו אוכל, ווייל די ת\"ח זיינען מרוה זייער אש מיט די חדושי תורה וועלכע זיי זיינען מחדש. אָבער דער סנה, די אנשים פּשוטים, וואָס אין זיי איז דער לבת אש די האַרץ פון פייער, באַ זיי מיט זייער ערנסטע תמימות'דיקע תפלות און תהלים זאָגן הגם דלא ידעי מאי קאמרי אָבער ווייל דאָס קומט פון דער אמונה פּשוטה, איז דער לבת אש איננו אוכל, דאָס ווערט קיינמאָל ניט געשטילט און זיי האָבן אַ תשוקה צו ג-טלעכקייט און תורה ומצות.\nויאמר משה אסורה נא, זאָגט רש\"י אסורה מכאן להתקרב לשם, אַז משה רבינו האט פאַרשטאַנען די מחזה העליונה, וואָס מען באַווייזט אים די מעלה הגדולה פון אנשים פּשוטים לגבי תלמידי חכמים, אַז דער לבת אש איז נאָר אין סנה, איז ער געקומען צו דער דרגא פון תשובה, נאָר להיות משה רבינו איז דאָך געווען אַ צדיק גמור, וואָס דער אופן התשובה פון אַ צדיק גמור איז באופן אחר ווי די געוויינלעכע תשובה, באַ לידת משה רבינו זאָגט די תורה<sup data-n=\"11\">67</sup> ותרא אותו כי טוב הוא שנתמלא הבית כולו אורה (סוטה יב, א), איז זיין אופן תשובה אסורה מכאן להתקרב לשם, וואָס די כוונה איז אַז מען באַדאַרף זיך ניט מסתפּק זיין מיט דעם מעמד ומצב וואָס מען שטייט<sup data-n=\"12\">68</sup>. אַפילו אַ צדיק גמור ווי משה רבינו דאַרף האָבן די עבודה פון אסורה מכאן להתקרב לשם וואָס דאָס איז די תנועה פון תשובה<sup data-n=\"13\">69</sup>.",[["1","57","יתרו יט, כ."],["2","58","וישב לח, א."],["3","59","מסעי לד, יא-יב."],["4","60","בתרגום שלפנינו: ויחות תחומא."],["5","61","וירא יח, כא."],["6","62","שה\"ש ח, ו."],["7","63","תהלים צא, יד."],["8","64","ראה לעיל סימן ט ואילך. וש\"נ."],["9","65","שופטים כ, יט."],["10","66","ראה ברכות כב, א."],["11","67","שמות ב, ב."],["12","68","ראה גם שיחת חג הפסח תרצ\"ד סכ\"ט (לקוטי דיבורים ח\"א קלח, ב)."],["13","69","ספר השיחות תש\"ב ע' 47-46.\nתורה הנ\"ל אמר אדמו\"ר הזקן בהויכוח שהי' במינסק שנת תקמ\"ג, כמענה על שתי שאלות ששאלוהו אודות תורות הבעש\"ט, ומועתק בזה מספר השיחות שם:\nצווישן די טענות וועלכע די גאוני המנגדים האָבן אַרויסגעשטעלט קעגן דער שיטת הבעש\"ט ותלמידיו זיינען געווען צוויי אַלגעמיינע גרונד טענות.\nאיינס: שיטת הבעש\"ט איז מחייב אַז אויך פּשוט'ע מענטשן באַדאַרפן שטאַרק אַכטן זייער תפלה און זייער תהלים זאָגן, הגם אַז לא ידעי מאי דקאמרי, וואָס מיט דער שיטה גיט מען אַ רמות רוח די עמי הארצים און מען איז משפּיל דעם כבוד פון ת\"ח. אַלע ווייסן – האָבן די גאונים געשטורעמט – אַז פּורעניות וואָס איז בא לעולם איז נאָר צוליב די עמי הארצים (ב\"ב ח, א).\nצווייטנס: שיטת הבעש\"ט איז אַז אויך אַ גאון אַ צדיק באַדאַרף תשובה טאָן, וואָס מיט דער שיטה האַקט מען אונטער דעם כבוד התורה און כבוד תלמידי חכמים, וואָס כל התורה כולה שבכתב און שבעל פּה איז פול מיט דעם אַז ת\"ח זיינען דער יסוד העולם און מרבים שלום בעולם און זיי זיינען די אמת'ע בנאים, און שיטת הבעש\"ט מאַכט זיי פאַר אַזעלכע אַז זיי באַדאַרפן תשובה טאָן...\nאויף די אויבנדערמאָנטע צוויי גרונד טענות האָט דער רבי געענטפערט:\nדער יסוד פון שיטת מורנו הבעש\"ט און די תורות פון רבי'ן, דער מעזריטשער מגיד וואָס איז דער אור המאיר אין די דרכי העבודה פון תלמידי הרב המגיד ממעזריטש איז מיוסד אויף דער ערשטער ג-טליכער התגלות צו משה רבינו. דער רבי [ההמשך בפנים. ולאח\"ז ממשיך שם:]\nאין דער דאָזיקער תורה – האָט דער רבי געזאָגט – זאָגט דער בעש\"ט קלאָר אַרויס זיין שיטה אין עבודת הבורא ב\"ה, אַז דער לבת אש, די האַרץ פון פייער, איז באַ די פּשוט'ע תמימות'דיקע אידן. און דער אידישער סנה איז איננו אוכל, ער ווערט קיינמאָל ניט געשטילט. אין דער צייט וואָס דער אש התורה פון תלמידי חכמים בכלל און גאונים בפרט, ווערט געשטילט דורך דעם פאַרגעניגן פון זייערע חידושי תורה, איז באַ די אנשים פּשוטים דער לבת אש ניט געשטילט, אדרבה דורך זייערע האַרציקע תפלות און פּשוט'ן תהלים זאָגן ווערט באַ זיי דער לבת אש נאָך שטאַרקער מיט נאָך אַ גרעסערע תשוקה און המשכה צו ג-טליכקייט. דער רבי דער בעש\"ט זאָגט אַרויס ריין קלאָר זיין שיטה אין דער עבודת הצדיקים אַז עס באַדאַרף זיין אין אַ כסדר'דיקע עלי'. דער היינט באַדאַרף זיין אויף צוקומען צו אַ העכערער דרגא אין עבודת הבורא ווי די נעכטיקע דרגא, און די מאָרגנדיקע דרגא אין עבודת הבורא באַדאַרף זיין אַ העכערע פון דער היינטיקער, וואָס די כללות העבודה איז אַ תנועה פון תשובה.\nדי שיטה פון רבי'ן דעם בעש\"ט איז מיוסד אויף דער ערשטער ג-טליכער התגלות צו משה רבינו, וואָס ער איז געווען דער, וועמען השי\"ת האָט בוחר געווען צו זיין דער גואל ראשון און דער גואל אחרון (ראה שמו\"ר פ\"ב ס\"ד. זח\"א רנג, א. שה\"פ פ' ויחי. תו\"א ר\"פ משפטים).\nדי התגלות אלקות צו משה רבינו איז ניט גלייך צו דער התגלות אלקות צו נח'ן און אַפילו צו אברהם אבינו.\nדי התגלות אלקי צו נח'ן איז אַ התגלות פּרטית וואָס קומט מצד אהבה פּרטית. צי די אהבה און קירוב פון השי\"ת צו נח'ן איז געווען נאָר אַ ענין נשיאות חן ווי עס שטייט ונח מצא חן, צי די אהבה וקירוב איז געווען מצד זיין צדקות ווי עס שטייט כי אותך ראיתי צדיק לפני בדור הזה, אבל בכל אופן איז די התגלות געווען אין אַ אופן פּרטי.\nדי התגלות אלקי צו אברהם אבינו איז געווען גאָר אין איין אַנדער אופן, אַ התגלות אלקות מיט געוויסע הוראות אין דרכי עבודת השי\"ת און מיט גרויסע נסיונות. געוויס איז די התגלות אלקי צו אברהם אבינו אין אַ פיל העכערע דרגא ווי צו נח'ן, אָבער נאָך אַלעם דעם איז די אהבה וקירוב אין דער התגלות אלקית צו אברהם אבינו מער אַ פּרטיות'דיקע און על שם העתיד.\nעס שטייט כי ידעתיו למען אשר יצוה את בניו ואת ביתו אחריו ושמרו דרך הוי' לעשות צדקה ומשפּט, מאַכט רש\"י כי ידעתיו איז אַ אַויסשפּראַך פון אהבה און פאַרוואָס די אהבה, ווייל אברהם וועט לערנען און אָנזאָגן זיינע קינדער און הויז געזינד אָפּצוהיטן און צו גיין אין דרכי השי\"ת.\nדי התגלות אלקות צו אברהם אבינו איז בעיקרה געווען אַ פּרטיות'דיקע, נאָר אין אַ העכערע דרגא ווי די התגלות צו נח'ן, ווייל אברהם אבינו איז געווען אַ גרעסערער עובד הוי' פון נח'ן, און אויך איז אין דער התגלות אלקות צו אברהם אבינו געווען נאָך אַ ענין אָט דער כי ידעתיו למען אשר יצוה, וואָס דאס האָט געמאַכט גרעסער די התגלות אלקות צו אים און ער ווערט אָנגערופן (ב\"ר פמ\"ב ועוד) אוהבו של מלך.\nאָבער די התגלות אלקות צו משה רבינו איז ניט נאָר אַ פּרטיות'דיקע, ווייל ער איז געווען אַ עובד השי\"ת, נאָר עס איז אַ התגלות אלקות כללי, וואָס אַזאַ התגלות איז נאָר צו דעם וואָס השי\"ת האָט אים בוחר געווען פאַר אַ מנהיג און גואל ישראל.\nדי התגלות אלקות צום גואל און מנהיג איז געווען דאָס, וואָס מען האָט אים באַוויזן אַז אַ מנהיג ישראל וואָס באַדאַרף זיין דער שליח הגאולה באַדאַרף געפינען דעם לבת אש אין אַ סנה, אין דעם פּשוט'ן אידן. און זיין גאַנצע עבודה באַדאַרף זיין אַרויסצוברענגען און אַנטפּלעקן דעם לבת אש אין דעם סנה, וואָס דאָס איז נאָר דורך דער עבודה פון אסורה נא מכאן להתקרב לשם.\nמיט אַ גרויסן ברען – דערציילט הגאון ר' יצחק אייזיק – האט דער רבי געזאָגט די תורה פון דעם בעש\"ט, און האָט מסיים געווען – דעם \"בכן\" פון דער תורה:\nאון באמת וואָס מער בן תורה אַלץ מער בן עבודה באַדאַרף מען זיין. און אויב ניט – איז מען חלילה אַ פּושע קעגן מלכא עילאה, ווי עס שטייט הפּושעים בי בגופא דמלכא (זח\"ב פה, ב. ראה ג\"כ ת\"ז תי' ע קרוב לסופו). און מען באַדאַרף טאַקע תשובה טאָן מעומקא דליבא אַרויסצורייסן פון זיך דעם עמלק וואָס איז מקרר דעם דרך הוי' און די דרכי עבודת הבורא."]]],[300010540,"יט\n\n<b>ומורו</b> המגיד בשם מורו הבעש\"ט ביאר כי מראה הגדול הוא דבר והיפוכו מדוע לא יבער הסנה, והיינו דמאחר שהאש סובב את הסנה עד שהוא כולו באש בכל זה לא יבער שאינו אוכל ע\"ד ואתם בני יעקב לא כליתם<sup data-n=\"1\">70</sup> והיפוכו דהגם שהסנה בוער ע\"ד כתנור אש בכל זה הנה הסנה איננו אכל, וזהו מראה גדול<sup data-n=\"2\">71</sup>.",[["1","70","מלאכי ג, ו."],["2","71","ספר המאמרים תש\"ד ע' 105."]]],[300010541,"כ\n\nמשפטים כב, ח: <i>על כל דבר פּשע על שור על חמור על שה על שלמה על כל אבדה</i>.\n<b>מורנו</b> הבעש\"ט טייטשט דעם פּסוק, פּשע איז ר\"ת פּריקות של עול, על כל דבר פּשע מיינט, אַז אויף אַלעס איז דער פּריקת עול.\nלכאורה ווי קומט מען צו זיין אַ פּורק עול. דער גוף וואָס איז געבוירן געוואָרן בטהרה דורך אַ מקוה כשרה, וואָס דאָס, אַז מ' סאה במקוה זיינען מטהר איז אַ חוקה<sup data-n=\"1\">72</sup>, וואָס דאָס איז דאָך דער ענין פון קבלת עול, און מלאכים וואַרעמען זיך ביי די וואַסער וואָס מען הייצט פאַר אַ מקוה און בעת ירידת הנשמה בגוף זיינען די מלאכים מלוה די נשמה, טאָ ווי קומט צו אַ נשמה דער ענין פון פּריקת עול.\nאיז דער תירוץ<sup data-n=\"2\">73</sup> – על שור, שור איז דער יצר הרע, וואָס שרשו איז מפני שור, על חמור, חמור איז קרירות, חמרא אפילו בתקופת תמוז קרירא לי'<sup data-n=\"3\">74</sup>, עס מאַכט קאַלט דעם שמש הוי'<sup data-n=\"4\">75</sup>, על שה, שה פזורה<sup data-n=\"5\">76</sup>, ער צושפּרייט זיך אין אַלעס, אַלעס וויל ער, אַלעס דאַרף ער, על שלמה, שלמה מיינט די לבושים, על כל אבדה, וואָס דורך דעם פאַרלירט ער אַלעס און ווייסט ניט ביי וואָס ער האַלט<sup data-n=\"6\">77</sup>.",[["1","72","רמב\"ם סוף הל' מקואות."],["2","73","בהבא לקמן – ראה אוה\"ת משפטים ע' א'עו. ספר המאמרים תרל\"ד ע' קכח ואילך. תרפ\"ט ע' 157 ואילך. וש\"נ. לקוטי שיחות ח\"א ע' 155 ואילך."],["3","74","שבת נג, א."],["4","75","תהלים פד, יב."],["5","76","ירמי' נ, יט."],["6","77","ספר השיחות תש\"ד ע' 104 ואילך."]]],[300010542,"כא\n\nמשפטים כג, ה: <i>כי תראה חמור שונאך רובץ תחת משאו וחדלת מעזוב לו עזוב תעזוב עמו</i>.\n<b>אחת</b> מתורות הבעש\"ט:\nכי תראה חמור – כאשר תסתכל בעיון טוב בהחומר שלך שהוא הגוף, תראה – שונאך – שהוא שונא את הנשמה המתגעגעת לאלקות ורוחניות, ועוד תראה שהוא – רובץ תחת משאו – שנתן הקב\"ה להגוף שיזדכך ע\"י תומ\"צ והגוף מתעצל בקיומם. ואולי יעלה בלבבך – וחדלת מעזוב לו – שיוכל לקיים שליחותו, כי אם תתחיל בסיגופים לשבור את החומריות, הנה לא בזו הדרך ישכון אור התורה, כי אם – עזוב תעזוב עמו – לברר את הגוף ולזככו ולא לשברו בסיגופים<sup data-n=\"1\">78</sup>.",[["1","78","\"התמים\" חוברת ח' ע' מט [תא, א]. אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' שכה (הועתק ב\"היום יום\" כח שבט). וראה אגרות-קודש שם ע' קעד. ע' רפא. ספר המאמרים תש\"ד ע' 145. ספר השיחות תרצ\"ו ע' 121. תש\"א ע' 66. לקוטי שיחות ח\"א ע' 32 ואילך. ע' 71. ח\"ב ע' 351. ע' 474. ס\"ע 530 ואילך. ע' 561. ע' 692. ח\"ג ע' 850. ח\"ד ע' 1184. ח\"ו ע' 257. ועוד."]]],[300010543,"כב\n\nקדושים יט, יז: <i>לא תשנא את אחיך בלבבך הוכח תוכיח את עמיתך ולא תשא עליו חטא</i>.\n<b>לא</b> תשנא את אחיך בלבבך, דער וואָס האָט פיינט אַ אידען אַפילו מער ניט ווי אין האַרצן ניט אַז ער חלילה טוט אים אַ רעה מצד השנאה אָדער רעדט אויף אים, נאָר מער ניט וואָס ער האָט אים פיינט אין האַרצן, איז עובר בלאו, וואָס איז די עצה אַז אַ איד זאָל ניט עובר זיין אויף דעם לאו פון לא תשנא את אחיך בלבבך, די עצה אויף דעם איז הוכח תוכיח את עמיתך, זאָלסט גיין צו יענעם וואָס דו ווייסט אַז ער האָט דיך פיינט, די שנאה האָט דאָך אַ סיבה פאַרוואָס ער האָט דיך פיינט און די סיבה פון דער שנאה איז דאָך געוויס אַ ענין פון יראת שמים. מסתמא האָט יענער געזען אין דיר דרכים אָדער הנהגות וואָס ער רעכנט אַז עפּ\"י תורה בעדאַרפמען זאך אַזוי ניט פירן, אשר על כן איז די עצה צו דעם הוכח תוכיח זאָלסט גיין צו אים און אויסבאווייזן אַז דיין דרך מיט דיינע הנהגות איז ווי עס בעדאַרף זיין, ולא תשא עליו חטא, אַי דו וועסט זאָגן צו וואָס ביסטו דאָס מחוייב צו טאָן, איז דער חיוב מצד אהבת ישראל, און דאָס איז ולא תשא עליו חטא, דער אהבת ישראל בעדאַרף אויף דיר פועל זיין אַז דו זאָלסט ניט לאָזן אַז ער זאָל טראָגן אויף זיך אַ חטא, אָבער מיט דעם וואָס דו וועסט אים אויסווייזן ווי דיין דרך איז גוט און דיין הנהגה איז ווי עפּ\"י תוה\"ק בעדארף זיין, וועסטו פון אים אַראָפּנעמען דעם חטא פון לא תשנא את אחיך בלבבך, אַז ער זאָל ניט עובר זיין אויף קיין לאו נאָר וויבאַלד אַז דו ווייסט אַז דו ביסט גערעכט, און דער אַנדערער וואָס האָט דיך פיינט איז אומגערעכט, און טוסט אַזאַ גרויסע מצוה פון אהבת ישראל בכדי מציל זיין פון אַ חטא, דער לאו פון לא תשנא את אחיך, במילא קען דאָך זיין אַז דו וועסט חלילה אַרויס מיט האַרבע ווערטער, אויף דעם זאָגט רש\"י אויף די ווערטער ולא תשא עליו חטא, לא תלבין את פניו ברבים<sup data-n=\"1\">79</sup>.",[["1","79","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' רעח."]]],[300010544,"כג\n\nקדושים יט, יח: <i>ואהבת לרעך כמוך</i><sup data-n=\"1\">80</sup>.\n<b>דער</b> רבי – אדמו\"ר הזקן – האָט געזאָגט פון מעזריטשער מגיד פון בעש\"ט'ס וועגן:\nואהבת לרעך כמוך איז אַ פירוש וביאור אויף ואהבת את ה' אלקיך<sup data-n=\"2\">81</sup>. אַז מ'האָט האָלט אַ אידען, האָט מען האָלט דעם אויבערשטען, ווייל א איד האָט דאָך אין זיך אַ חלק אלקה ממעל<sup data-n=\"3\">82</sup>, איז אַז מ'האָט האָלט דעם אידען, דעם אינוועניג פון איהם, ממילא האָט מען האָלט דעם אויבערשטען<sup data-n=\"4\">83</sup>.",[["1","80","ראה גם לקמן סימן קלב ואילך."],["2","81","ואתחנן ו, ה."],["3","82","תניא רפ\"ב."],["4","83","\"היום יום\" יב מנחם אב – משיחת י\"ט כסלו תרפ\"ט (ספר השיחות תרפ\"ט ע' 56). – ולהעיר מתורת הה\"מ (או\"ת לתהלים) עה\"פ אל תבוא במשפט עמנו, פי' דכל הדנים את ישראל דנים כביכול אותו יתברך כי הוא אחדות עמנו (הערת כ\"ק אדמו\"ר זי\"ע בקונטרס אהבת ישראל (קה\"ת, תשל\"ז) ע' 9)."]]],[300010545,"כד\n\n<b>האָט</b> הוד כ\"ק רבינו הזקן דאַן פאַר זיי איבערגעזאָגט די תורה וואָס דער מעזריטשער מגיד האָט אים איבערגעגעבן בשם מורנו הבעש\"ט:\nהאָלט האָבן אַ אידן איז אַ מצוה דאורייתא. אין יעדער מצוה איז פאַראַן די עשה פון דער מצוה און די לא תעשה. און אַזוי אויך אין דער מצוה פון אהבת ישראל איז ואהבת לרעך די עשה און לא תשנא את אחיך<sup data-n=\"1\">84</sup> די לא תעשה. די פּשיטות פון דעם פּשוט'ן אידן, זיין תפלה, זיין זאָגן תהלים נאָכן דאַוונען, זיין טאָן אַ מצוה ווייל השי\"ת האָט געהייסן, איז גורם אַ נחת רוח למעלה<sup data-n=\"2\">85</sup>.",[["1","84","כשיראה לו שנאה וידע שהוא שונאו אינו עובר ע\"ז הלאו, אמנם עובר על לא תקום ולא תטור (ס' החינוך מצוה רלח), בכ\"ז כתב כאן ל\"ת דלא תשנא. וי\"ל: א) ע\"פ מש\"כ הרמב\"ם [הל' דעות פ\"ו] ה\"ה. אבל לכאורה אין זה מספיק, שהרי ברמב\"ם שם מבאר בזה: ולא הזהירה תורה אלא כו'. וראה ג\"כ שם ספ\"ז (ע\"ד מש\"כ בס' החינוך). וי\"ל ב) מפני שלא תשנא – היא קודמת והסיבה (בנפש האדם) ל\"לא תקום ולא תטור\" – כמובן. ג) ס\"ל בדברי הרמב\"ם בהכס\"מ שם דגם כשמראה השנאה עובר. וידוע שקו\"ט האחרונים בדברי הכס\"מ ובהסתירה מסהמ\"צ להרמב\"ם מל\"ת שב (הערת כ\"ק אדמו\"ר זי\"ע בקונטרס אהבת ישראל (קה\"ת, תשל\"ז) ע' 9)."],["2","85","ספר השיחות תש\"ז ע' 123. ושם לפנ\"ז:\nהוד כ\"ק רבינו הזקן האָט געהאַט יונגעלייט, גדולים בתורה, פאַר וועלכע ער פלעגט זאָגן אַ שיעור גמרא והלכה, און זיי האָבן געהאַט זייער אייגענעם מנין און האָבן זיך מתרחק געווען בכל מיני ריחוק והבדלה פון די פּשוט'ע אידן.\nווען הוד כ\"ק רבינו הזקן איז צוריקגעקומען פון מעזריטש, האָבן זיינע תלמידים יונגעלייט באַמערקט אַ שינוי אין זיין הנהגה בהנוגע צו די פּראָסטע אידן. ניט נאָר האט ער אויפגעהערט זיך מתרחק זיין פון זיי, נאָר ער האָט זיי גאָר אָנגעהויבן מקרב זיין.\nבאַ די יונגעלייט איז די זאַך געוואָרן זייער מוקשה, זיי האָבן אָבער ניט געהאַט די דרייסטקייט צו פרעגן אים וועגן דעם.\nהוד כ\"ק רבינו הזקן האָט מרגיש געווען אַז די יונגעלייט זיינען פאַרוואונדערט אויף זיין נייער הנהגה [ההמשך בפנים]."]]],[300010546,"כה\n\nאמור כג, ד: <i>אלה מועדי ה' מקראי קודש אשר תקראו אותם במועדם</i>.\n<b>\"אלה</b> מועדי הוי' מקראי קודש אשר תקראו אותם במועדם\", די \"מועדי הוי'\" ענינם \"מקראי קודש\", וואָס זיי שטייען אין תורה, און אלפיים שנה קדמה תורה לעולם<sup data-n=\"1\">86</sup>, וואָס זיי האָבן געוואַרט אלפיים שנה אויף מ\"ת און אידן, \"מקראי קודש\" שממשיכים קדש העליון, \"אשר תקראו אותם במועדם\" ע\"י ההכנה שקודם המועד<sup data-n=\"2\">87</sup>.",[["1","86","ראה מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. תנחומא וישב ד. וש\"נ. זח\"ב מט, א."],["2","87","ספר השיחות תרצ\"ו ע' 144. ושם לפנ\"ז: דעם ענין וואָס מ'האָט גערעדט אין \"מועדי הוי'\", איז דאָס די ערשטע תורה וואָס דער מגיד האָט געהערט פון בעש\"ט, און דאָס איז געווען די תורה וואָס דער מגיד האָט מיט דעם גענומען דעם רבי'ן פאַר אַ תלמיד. און אַז דער רבי האָט געמאַכט דעם מיטעלן רבי'ן אין אַ ציור פון אַ כללי האָט ער געזאָגט די תורה, און האָט געזאָגט אַז די תורה האָט מיט איר דער זיידע (הבעש\"ט) מקדש געווען דעם מגיד, און דעם זיידענס קידושין איז אַ ענין פון מ\"ת, און די תורה האָב איך די ערשטע געהערט פון רבי'ן [ההמשך בפנים]. – תורה זו הובאה ונתבארה בשיחת יום ב' דחג השבועות תשט\"ז סי\"ט (תורת מנחם התוועדויות תשט\"ז ח\"ב ע' 338)."]]],[300010547,"כו\n\nאמור כג, מב: <i>כל האזרח בישראל ישבו בסוכות</i>.\n<b>. . . וכ\"ק</b> אאמו\"ר הרה\"ק<sup data-n=\"1\">88</sup> בשם הבעש\"ט נ\"ע פי' דכל האזרח בישראל ישבו בסוכות שהוא הבטחה, דכאשר בסוכות תשבו שבעת ימים אז הנה הקב\"ה מבטיח בתורתו אשר כל האזרח בישראל שהוא מהמדרי' מקיפים שבנשמה הנעלית ביותר ממדרי' הפנימית, בכ\"ז ישבו בסוכות בהתיישבות פנימית<sup data-n=\"2\">89</sup>.",[["1","88","כ\"ק אדמו\"ר מהורש\"ב נ\"ע."],["2","89","ספר המאמרים תש\"ד ע' 32. ושם:\nוביאר דהנה ארז\"ל (מד\"ר בראשית פי\"ד, ט) חמשה שמות נקראו לה נפש רוח נשמה חי' יחידה דשלש בחינות נר\"נ הן פני' וחי' יחידה הן מקיפי' דחי' היא מקיף הקרוב ויחידה היא מקיף הרחוק שמקבל מבחי' יחיד פי' התקשרות החלק בהעצם, הנה כאשר בסוכות תשבו שבעת ימים והעבודה דנר\"נ אז הנה מלמעלה יתנו לו גילוי מקיפים דנשמה, וזהו ההבטחה דכל האזרח בישראל ישבו בסוכות."]]],[300010548,"כז\n\nבהר כה, ב: <i>ושבתה הארץ</i>.\n<b>דער</b> פירוש על פי תורת הבעל שם טוב: ושבתה הארץ – שביתה וביטול אין ארץ<sup data-n=\"1\">90</sup>; מען טראָגט אַריין שביתה אין די ענינים ארציים גופא<sup data-n=\"2\">91</sup>.",[["1","90","ראה תולדות יעקב יוסף ר\"פ בהר."],["2","91","לקוטי שיחות חלק א ע' 275."]]],[300010549,"כח\n\nקרח טז, ל: <i>ואם בריאה יברא ה'</i>.\n<b>מורנו</b> הבעש\"ט האָט מבאר געווען דעם פסוק ואם בריאה יברא ה' איז ר\"ת אביי.\nדי גמרא אין נדרים<sup data-n=\"1\">92</sup> (וברש\"י במקומו) פרעגט: והלא אין כל חדש וגו'<sup data-n=\"2\">93</sup>, און ענטפערט, אַז דאָס איז דער פי הארץ שנברא בע\"ש בין השמשות, נאָר מען האָט איהם מקרב געווען צו דעם זמן.\nהאָט מען ביי איהם געפרעגט דער \"ואם\" הויבט זיך דאָך אָן מיט אַ \"ואו\". האָט מורנו הבעש\"ט געענטפערט, אַז אפילו אביי האָט אויך ניט געקענט גאָרניט טאָן אָן דעם \"ואו\", ווייל ו' איז מרמז דעם ענין פון המשכת התורה. אביי איז געווען דער מקור פון תורה שבעל פה, כידוע מהגמרא<sup data-n=\"3\">94</sup>, אביי ורבא תרווייהו מבית עלי וכו' אביי דעסק בתורה וכו', ווייל דורך תורה קען מען ממשיך זיין דעם פי גן עדן און אויך דעם פי<sup data-n=\"4\">95</sup> הגיהנם<sup data-n=\"5\">96</sup>.",[["1","92","לט, ב."],["2","93","קהלת א, ט."],["3","94","ראש השנה יח, א."],["4","95","ראה נדרים שם."],["5","96","ספר השיחות ה'תש\"א ע' 37. ושם לפנ\"ז: אַמאָל האָט מורנו הבעש\"ט געפּראַוועט אַ מופת אין דער שטאָט בראָד, האָט מען אים געוואָלט מחרים זיין, האָט מורנו הבעש\"ט זיי געזאָגט, אַז ער טוט דאָס ניט אַליין נאָר בשותפות מיט אביי. און מורנו הבעש\"ט [ההמשך בפנים]."]]],[300010550,"כט\n\nבלק כג, י: <i>מי מנה עפר יעקב</i>.\n<b>. . . עס</b> איז געווען דער הייליגער בעל שם-טוב – ר' ישראל בעל שם טוב – האָט ער אויסגעטייטשט דעם פּסוק מי מנה עפר יעקב, אידען זיינען געגליכען צום ערד-קוגעל ווי עס שטעהט<sup data-n=\"1\">97</sup> כי תהיו אתם לי ארץ חפץ, אין דעם ערד-קוגעל ליגען די גרעסטע אוצרות ווי מעטאַלען, אַלע מיני וואַסערען – עס איז נאָך ניט גענוג אויסגעפאָרשט געוואָרען אַלעס וואָס די ערד פאַרמאָגט אין זיך, עס זיינען נאָך דאָ פיל זאַכען וואָס מען וועט נאָך געפינען אין די ווייטערע אויספאָרשונגען – און בפרט דער גרעסטער בעסטער וואוקס קראַפט – כח הצומח – וואָס דער ליבער ג-ט ברוך-הוא האָט געגעבן דער ערד, אַז זי – די ערד – איז די באַשעפעניש וועלכע גיט שפּייז פאַר אַלע באַשעפענישען.\nדי ערד ווערט פון אַלעמען געטראָטען און אַלע מוזען אָנקומען צו איהר צו באַקומען איהר פּראָדוקציע פון שפּייז און וואַסער, אָבער צו באַקומען די ערד-פּראָדוקציע מוז מען לעגען פיל מיה, צו גראָבען אין דער טיפעניש פון דער ערד ווי אויך אַקערען און זייען.\nדאָס איז דער מיין פון דעם וואָס אונזער ליבער ג-ט ב\"ה רופט אונז אידען מיט'ן נאָמען ארץ חפץ, ליבע ערד. אידען זיינען געגליכען צו דער ערד, ווייל אידען אַנטהאַלטען אין זיך געבירטליכע אמונת ה' און אהבת ה', די גרעסטע וועלט מאָראַלישע און וויסענשאַפטליכע אוצרות. אויף אַלע געביטען זיינען ב\"ה די אידען – לויט דעם פּראָצענט פון דער באַפעלקערונג – די מעהרסטע בעסטע שעהנסטע און וויכטיגסטע, פאַר דער מענשהייט, וועלט און וויסענשאַפט אַנטוויקלונג.\nדי ערד, אַלע טרעטען אויף איהר און אַלע מוזען זי האָבען, ביים לעבען און אויך נאָכ'ן טויט. אויך די אידען ווערען געטראָטען אויף פאַרשידענע אופנים און אַלע מוזען צו זיי אָנקומען.\nאידען, ווער זיי זאָלען ניט זיין, אַלט און יונג, מענער און פרויען, פרום און פריי, און אין וועלכען פּלאַץ עס זאָל ניט זיין האָבען זיי דעם אויבענדערמאָהנטען גלויבען – אמונה – און ליבשאַפט – אהבה – און פורכט – יראה – אוצרות צו און פאַר אונזער ליבען ג-ט ב\"ה נאָר מען באַדאַרף דאָס מיט גרויס מיה אויפדעקן, אָט אַזוי ווי מען דעקט אויף די טיף אין דער ערד באַהאַלטענע אוצרות<sup data-n=\"2\">98</sup>.",[["1","97","מלאכי ג, יב."],["2","98","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ה ס\"ע שמח ואילך. וראה לקמן סימן נז. קכה."]]],[300010551,"ל\n\nמסעי לג, א: <i>אלה מסעי בני ישראל אשר יצאו מארץ מצרים</i>.\n<b>וועגן</b> די מ\"ב מסעות שבפרשת מסעי, זאָגט דער בעש\"ט<sup data-n=\"1\">99</sup> אַז זיי זיינען אַלע פאַראַן ביי יעדער אידן, במשך שנות חייו: \"אשר יצאו מארץ מצרים\" – לידת האדם, דערנאָך במשך ימי חייו – שאר המסעות, ביז ער קומט צו ארץ החיים העליונה<sup data-n=\"2\">100</sup>.",[["1","99","הובא בדגל מחנה אפרים ר\"פ מסעי."],["2","100","לקוטי שיחות ח\"ד ע' 1083. חכ\"ג ע' 225 (ושם: ביז ער קומט צום ברעג פון ארץ החיים העליונה). וראה גם לקוטי שיחות ח\"ב ע' 615. ובלקוטי שיחות ח\"ד שם (ועד\"ז בלקוטי שיחות חכ\"ג שם):\nאון כאָטש אַז צווישן די מסעות זיינען דאָך דאָ מסעות היפּך הרצון העליון, איז לכאורה ווי קען מען אויסשטעלן אַ סדר אַז בחיי כל אחד ואחד <i>מוזן</i> זיין ענינים היפּך הרצון? איז דאָס מובן על פּי ביאור הבעש\"ט, אַז די מסעות מצד עצמם זיינען קדושה, נאָר (עס איז דאָך געגעבן געוואָרן בחירה, איז) מצד מעשיהם זיינען אַרויסגעקומען די ענינים היפּך הטוב. אָבער בשעת די בחירת האדם איז ווי עס דאַרף זיין, \"ובחרת בחיים\" (און מען האָט אויך אַ נתינת כח וסיוע אויף דעם, ווייל די <i>תורה</i> זאָגט דאָך אים \"ובחרת בחיים\"), דאַן זיינען <i>אַלע</i> מסעות – עליות מחיל אל חיל בקדושה.\nולדוגמא ברענגט ער דעם מסע פון קברות התאוה, וואָס \"שם קברו את העם המתאוים\". איז דער ענין אין קדושה, ובמדריגה נעלית בקדושה, אַ מדריגה וואו ס'איז ניט שייך קיין תאוה, ניט נאָר וואָס <i>בפּועל</i> איז ניטאָ קיין תאוה נאָר \"<i>קברו</i> גו' המתאוים\", אַז ס'איז גאָרניט בגדר עס זאָל זיין שייך תאוה. נאָר מצד התערבות הלעומת זה איז געוואָרן אין אַ ציור היפּך הטוב. ע\"כ תוכן הביאור."]]],[300010552,"לא\n\nמסעי לה, יד: <i>את שלש הערים . . ואת שלש הערים גו'</i>.\n<b>בשם</b> הבעש\"ט ראיתי<sup data-n=\"1\">101</sup>, ג' ערי מקלט ג' בחי' מחדו\"מ<sup data-n=\"2\">102</sup>.",[["1","101","ראה קדושת לוי ליקוטים קח, ב."],["2","102","אור התורה מסעי ע' א'תטו."]]],[300010553,"לב\n\nדברים א, טז: <i>שמוע בין אחיכם ושפטתם צדק</i>.\n<b>שמוע</b> בין אחיכם ושפטתם צדק, וכדרשת רז\"ל בעניני דינין ומשפטים.\nלפי המסורה אמר אז מורנו הבעש\"ט נ\"ע לשלוחי וועד ארבע הארצות אשר בלימוד התורה יש שתי בחי': א) תורת המוח ב) תורת הלב, המוח משכיל מבין ומשיג, והלב מרגיש.\nאתם – אמר מורנו הבעש\"ט להשלוחים – וגדולי התורה יודעים את התורה כמו שבאה בהשגת המוח, ואנכי באתי לגלות את התורה כמו שהיא באה גם בהרגש הלב, ויבאר להם את הכתוב שמוע בין אחיכם על שלשה אופנים:\nא. שמוע בין אחיכם, שמוע דער וואָס האָט אַ חוש השמיעה רוחני און הערט ווי גרויס ס'איז די אהבת השם ב\"ה צו יעדער אידן, ווי יעדער איד איז טייער למעלה, דער איד איז בין אחיכם, בין לשון הבנה, אָט דער פאַרשטייט די גרויסקייט פון אַ אידן.\nב. שמוע בין אחיכם דער וואָס האָט אַ חוש השמיעה רוחני דער איז בין אחיכם, ער איז אויסגעבונדן מיט אידן און פילט אַ עונג רוחני אין און פון יעדן אידן באַזונדער.\nג. שמוע בין אחיכם. שמוע בכדי דער מענטש זאָל קריגן אַ חוש השמיעה רוחני, דערהערן און דערפילן די גרויסקייט פון אַ אידן, איז בין אחיכם, איז נאָר ווען מען איז אויסגעבונדן מיט אידן און אַלע אידן אפילו די גאָר פּשוט'ע זיינען זיינע אחים.\nכראות השלוחים שמורנו הבעש\"ט הוא חזק בדעתו שאלוהו במה כחו גדול, הלא יש לו רק ששים תלמידים וגדולי התורה יש להם בהישיבות תלמידים למאות ואלפים.\nעל זה השיב להם מורנו הבעש\"ט במשל:\nשתי דעות בעובדי אדמה. יש הזורע את שדהו ונוטע את כרמו מבלי השאיר מקום פנוי ובוטח על הריבוי. ויש הזורע את שדהו ונוטע את כרמו רק תלמים אחדים אבל הוא נותן נפשו עליהם לעודד ולנכש ולנקות ולהשקות הכל בעתו. לראשון צומחים פירות ותבואה הרבה אבל רובם מתולעים והמוץ מרובה בהם והקמח מעט וסולת אין כלל, וכשנותנים מהם לזרע, אזי רוב תולדותיהם רימה ותולעה. אבל להשני צומחים פירות ותבואה מועטים אבל מלאים דשן ורובם סולת, וכשנותנים אותם לזרע הנה תולדותיהם ותולדות תולדותיהם כיוצא בהם<sup data-n=\"1\">103</sup>.",[["1","103","מכתב כ\"ק אדמו\"ר מהוריי\"צ (ספר המאמרים ה'שי\"ת ע' 218-217. אגרות-קודש שלו ח\"ד ע' צו ואילך), ושם לפנ\"ז:\nכבר סיפרתי בארוכה אודות וועד ד' ארצות אשר שלחו שלשה אנשים למורנו הבעש\"ט נ\"ע למסור לו התראת בי\"ד אשר יפסיק הנהגתו ובאם לאו ינדוהו ויכריזו עליו חרם.\nכבוא השלוחים למורנו הבעש\"ט נ\"ע קבלם בסבר פנים יפות ודבר עמהם בדברי תורה בסוגיות עמוקות מה שהפליא אותם מאד, ונוכחו לדעת שהוא אדם גדול בתורה בנגלה ונסתר, ואיש בעל שיטה, עם רצון תקיף ודעת חזק.\nשני ימים ושני לילות התווכחו עם מורנו הבעש\"ט נ\"ע, והגם שרבינו הבעש\"ט נ\"ע נצח בכל הענינים מ\"מ אמר להם שהוא מוכן לעמוד לויכוח עם גדולי התורה בוועד ארבע הארצות ולעמוד אחרי כן למשפטם, והוכיח את השלוחים על אשר הגדולים דנוהו שלא בפניו ועברו על מה שכתוב בתורה [ההמשך בפנים].\nבכל הנ\"ל – ראה גם ספר השיחות תרצ\"ו ע' 133."]]],[300010554,"לג\n\nואתחנן ד, ז: <i>כי מי גו' כה' אלקינו בכל קראנו אליו</i> (<i>אליו ולא למדותיו</i> (ספרי הובא בפרדס שער לב (שער הכוונות) פ\"ב)).\n<b>בשם</b> הבעש\"ט נ\"ע דאין ר\"ל שהשמות הן הכלים עצמן דהא הכלים הם המדות והשם קאי להבורא עצמו שהוא עצמו כביכול נק' א-ל וכמאמר אליו ולא למדותיו אלא מ\"ש שהשמות הן בהכלים פי' שהם החיות וההארה מאור א\"ס המלובש בהכלי ומחי' את הכלי כי הכלים יש בהן חיות מאוא\"ס מלבד האור המלובש בהם, וזהו ענין שאר השמות שאינן נמחקין, אמנם שם הוי' הוא המשכת האור בהכלי שמחבר וממשיך האור בהכלי<sup data-n=\"1\">104</sup>.",[["1","104","לקו\"ת בהר מג, ב."]]],[300010555,"לד\n\n<b>בשם</b> הבעש\"ט<sup data-n=\"1\">105</sup> ז\"ל נ\"ע זי\"ע כי כל מה שנמצא בכתבי האריז\"ל ובשאר ספרי הקבלה שיחסו ז' השמות שאינן נמחקין ושארי כינויים למדות וספירות עליונות שם א-ל בחסד ואלקים בגבורה כו' וכיוצא אין הכוונה ח\"ו על הספירות ממש שספירת חסד נק' א-ל ח\"ו כי כלל גדול שכל התפלות הן אליו ולא למדותיו ח\"ו וכן השמות שאנו קוראים א-ל או אלקים היינו לו ית' ממש ולא למדותיו ח\"ו ומ\"ש בקבלה דשם אלקים עד\"מ הוא במדת הגבורה ר\"ל בחי' אלקותו ית' ממש המלובש במדת הגבורה כו' ולא שהשם אלקים הוא מדת הגבורה עצמה ח\"ו כי אין מקרא יוצא מתוך פשוטו שהשמות א-ל ואלקים הן לעצם אלקות ממש ולא להמדות וכו' רק שבבחי' התלבשות במדת חסד נק' א-ל ובהתלבשות במדת גבורה נק' אלקים כו'<sup data-n=\"2\">106</sup>.",[["1","105","מועתק בזה קטע ממכתב כ\"ק אדמו\"ר מהוריי\"צ (נדפס בספר המאמרים תש\"ט ע' 100. אגרות-קודש שלו ח\"ג ע' קמד. הועתק ב\"היום יום\" יא תשרי):\nבשנת תקנ\"ו במוצאי יוהכ\"פ בליאזנא, אמר רבינו הגדול נ\"ע תורה ברבים (כנהוג אז בדרושים קצרים) ע\"פ מי כהוי' אלקינו וגו' אליו, אליו ולא למדותיו, דער פרדס זאָגט אַז אליו איז אורות המתלבשים בכלים דע\"ס דאצילות. דער רבי דער בעש\"ט זאָגט אַז אליו איז דער אלקות וואָס אין כלים דע\"ס דאצי'. דער פירוש הפשוט איז אליו דער עצמות א\"ס וואָס עס איז באַ יעדער פּשוט'ן אידן בידיעה עצמית דורך אמונה פּשוטה. און דאָס איז קרובים אליו, און בכל קראנו אליו, די ביידע אליו'ס איז עצמות א\"ס און עצמות הנשמה, די תפלה באמונה פּשוטה איז מחבר עצמות הנשמה מיט עצמות א\"ס, אַז עצמות א\"ס זאָל זיין דער רופא חולים און מברך השנים. וראה גם רשימת היומן של רבינו – סוכות תרצ\"ה (\"רשימות\" חוברת קיד ע' 23). ד\"ה באתי לגני וד\"ה ויהי בשלח תשכ\"א (ספר המאמרים תשכ\"א ע' 248. ע' 259. ע' 266)."],["2","106","אוה\"ת יתרו ע' תתמט-תתנ. וראה גם בשם הבעש\"ט אוה\"ת ענינים ע' רלח. ספר המאמרים תרמ\"ד ע' רצב. תרמ\"ט ע' ערה. עזר\"ת ע' לח. עטר\"ת ע' ט.\nובאוה\"ת פ' שמות ע' קו לאחרי שמביא דברי הבעש\"ט כותב:\nובאמת שזה מוכרח ג\"כ מהתורה שהרי ארז\"ל בכל קראינו אליו ולא למדותיו למדותיו הן הע\"ס ואי תימא ששאר השמות שאינן נמחקין כוונתן להספירות ממש א\"כ כשאנו אומרי' הטה אלקי אזנך ושמע כו' אד' שמעה כו' וכהנה רבות היתכן שאנו קוראי' למדות' ח\"ו ולא אליו מה שאסרו זה בפי', אלא ודאי עכצ\"ל כדפי' הבעש\"ט נ\"ע שכל השמות שאינן נמחקין מורים על מהו\"ע ית' רק החילוק הוא בהתלבשותו בכלים שם אל\"ף למ\"ד הוא מצד התלבשותו בחסד כו', וא\"כ זה סותר למש\"ל דהאור המלובש בכלים הוא נק' הכל שם בן ד' ושאר השמות הן בהכלים ממש שהרי הבעש\"ט נ\"ע פי' שכל השמות הן לאור א\"ס המלובש בהכלים ולא שם בן ד' לבד ומוכרח הוא באין ספק. והתירוץ הוא לענ\"ד מוכרח עפ\"י מ\"ש במ\"א* בפי' וכד אנת תסתלק מנייהו אשתארו כגופא בלא כו', דפי' אנת הוא בחי' אור א\"ס המלובש בהכלים כדלעיל בפי' אנת חכים כו' ובהסתלקותו אשתארת כגופא כו'. וקשה דבהסתלקותו הי' ראוי לומר שיתבטלו ממציאותן לגמרי כמו קודם התהוותן כנודע בענין לעולם* הוי' דברך נצב כו', אבל הטעם דמ\"מ אשתארו כגופא מבו' שם שהוא מפני שהכלים יש להן שרש בפ\"ע מאור א\"ס בזולת האורות שמתלבשים בהן אח\"כ והיינו שהאורות שרשן מהקו וחוט והכלים שרשן מבחי' הרשימו כו' יעו\"ש. והנה הרשימו הוא מבחי' אור א\"ס ממש רק שהוא מה שנשאר אחר הצמצום כנודע וא\"כ הוא למעלה מעלה ממהות הכלים עצמן חכמה וחסד כו' דהא רשימו זו הוא מאור א\"ס דלאו מכל אינון מדות איהו כלל רק שרשימו זו נעשה חיות להכלים ומהווה אותן מאין ליש. וא\"כ מובן ומבואר שגם בהכלים יש ב' בחינות היינו הכלי עצמה ובחי' החיות המלובש בה מאור אין סוף מהרשימו, ובחינת השמות שבכלים היינו בחינת אין סוף מהרשימו המלובש בהכלים. אמנם בחינת האורות שהן מהקו הוא גבוה מהרשימו כי הוא מבחי' האור שלמעלה מהצמצום כמ\"ש במ\"א. ולכן האורות מלובשים בכלים וחשיבו לגבי הכלים כנשמה לגבי גוף. ונמצא צדקו דברי הבעש\"ט נ\"ע שכל השמות אינן להכלים ממש רק להאור אין סוף המלובש בהכלים והוא מבחי' הרשימו כנ\"ל, וגם צדקו דברי האריז\"ל דהאורות הן מבחי' שם הוי' ושאר השמות הן בהכלים דר\"ל דהאורות הן מבחי' הקו שלמעלה מהרשימו כנ\"ל. וזהו בחי' שם הוי' ושאר השמות הן לבחי' אור א\"ס המחיה הכלים שהוא ע\"י בחי' רשימו.\n-----שולי הגליון-----\n<i>מ\"ש במ\"א</i>: ראה בסידור ד\"ה וכד אנת.\n<i>לעולם</i>: ראה שער היחוד והאמונה פ\"א. אגה\"ק סכ\"ה."]]],[300010556,"לה\n\n<b>ומזה</b> הטעם אמר קדוש ה' הרישב\"ש נ\"ע אשר בלמוד ספרי הקבלה יש להזהר שלא ידמה הדברים כפשטותן, שהע\"ס נקרא א-ל או אלו-ה כו' וגם שלא יומשך אחר שאר כינוים גשמיים הנז' שם עד\"מ<sup data-n=\"1\">107</sup>.",[["1","107","לקו\"ת הוספות לויקרא נא, ג [לאחר שמבאר בארוכה שהכוונה בהשמות הוא להבורא ממש]. וכ\"ה\nבסהמ\"צ להצ\"צ (קטו, ב): ומזה הטעם ציוה הבעש\"ט שלא ללמוד ס' הקבלה כי מי שאינו יודע להפשיט הדברים מגשמיותן מתגשם מאד ע\"י לימוד זה כשנותן ציור בעניות דעתו לאלקותו ית' לפי מדות פרטיים. ועד\"ז הובא בשם הבעש\"ט במאמרי אדמו\"ר הזקן ענינים ע' שיח. אוה\"ת ויקרא ע' תרצט.\nוראה גם (לענין \"אליו ולא למדותיו\", \"לכוון בשם\") סידור שער הק\"ש ד\"ה איתא בספרי. אמרי בינה פתח השער פט\"ז ואילך (אבל לא הובא שם הנ\"ל בשם הבעש\"ט)."]]],[300010557,"לו\n\nואתחנן ו, ד: <i>שמע ישראל הוי' אלקינו הוי' אחד</i>.\n<b>שמע</b> ישראל הוי' אלקינו הוי' אחד, זיינען די אתוון רברבין <b>עד דע</b>. דער פּירוש איז אַז עס דאַרף זיין דער דע, מען זאָל וויסן דעם עד שבנשמה, וואָס דאַמאָלסט האָט ער אַ השגה אין עצמות הנשמה<sup data-n=\"1\">108</sup>.",[["1","108","שיחת א' דחג הסוכות ה'שי\"ת (ספר השיחות ה'שי\"ת ס\"ע 366 ואילך) – נתבאר בשיחת ליל שמחת תורה תש\"כ (תורת מנחם התוועדויות תש\"כ ח\"א ע' 78 ואילך)."]]],[300010558,"לז\n\nואתחנן ו, ה: <i>ואהבת את הוי' אלקיך</i>.\n<b>ואמר</b> הבעש\"ט תורה ע\"פ ואהבת את הוי' אלקיך, ואהבת בגימטריא ב' פעמים אור<sup data-n=\"1\">109</sup>, אור בגימט' רז<sup data-n=\"2\">110</sup> זר, עבודת הצדיקים לגלות את הרז שישנו גם בזר ואז נעשה אור, ע\"י ואהבת הוא ב' פעמים אור, אור ישר ואור חוזר<sup data-n=\"3\">111</sup>, אור במספר קטן ט' ב\"פ אור הוא ב\"פ ט' עולה י\"ח, בעוד י\"ח ימים אזכה לאור חוזר כמ\"ש<sup data-n=\"4\">112</sup> והרוח תשוב אל האלקים אשר נתנה, ורוח אייתי רוח ואמשיך רוח<sup data-n=\"5\">113</sup> באור חדש יאיר עד כי יבוא מלך המשיח<sup data-n=\"6\">114</sup>.",[["1","109","פע\"ח שער הק\"ש פכ\"ג. תניא ספמ\"ג."],["2","110","תקו\"ז תי\"ט (לט, ב). זח\"ג כח, ב ברע\"מ. וראה לקוטי שיחות ח\"י ע' 8. חכ\"ה ע' 7."],["3","111","ראה תו\"ח תולדות קמב, ד. קמט, ג. ועוד."],["4","112","קהלת יב, ז."],["5","113","ראה זח\"ב קסב, ב. וראה תו\"א מקץ מב, ג. אוה\"ת חנוכה רפו, א. אגרות-קודש אדמו\"ר מהוריי\"צ חלק ד ע' ע (הועתק ב\"היום יום\" כ אדר שני)."],["6","114","ראה ספר המאמרים תרצ\"ט ע' 8. ספר המאמרים תש\"א ע' 116 ובהערות שם. תש\"ט ע' 40. לקו\"א להרב המגיד הוספות סימן יב."]]],[300010559,"לח\n\n<b>שמעתי</b> פּא\"פּ מאדמו\"ר נ\"ע בזה\"ל כך קבלתי מהה\"מ דמעזריטש<sup data-n=\"1\">115</sup> וכך קבל הוא ז\"ל מהבעש\"ט שמצות ואהבת היא לתקוע מחשבתו ודעתו (ובל\"א אמר בזה\"ל מע זאָל זיך אַריין טאָן) בדברים המעוררים את האהבה ומה שיבא מזה אין זה מעיקר המצוה<sup data-n=\"2\">116</sup>.",[["1","115","ראה ספר המאמרים תרצ\"ט ע' 8. ספר המאמרים תש\"א ע' 116 ובהערות שם. תש\"ט ע' 40. לקו\"א להרב המגיד הוספות סימן יב."],["2","116","שני המאורות (למהרי\"א הלוי עפּשטיין מהאָמיל תלמיד רבינו הזקן) ח\"ב ס\"ב. הועתק בהערות כ\"ק אדמו\"ר זי\"ע בספר המאמרים תש\"א שם."]]],[300010560,"לט\n\nואתחנן ו, ז: <i>ושננתם לבניך ודברת בם בשבתך בביתך ובלכתך בדרך ובשכבך ובקומך</i>.\n<b>ושננתם</b> דו זאָלסט משנן זיין, לשון שינון, לבניך צו די וואָס ווילן פאַרשטיין, ודברת בם זאָלסט אַריינרעדן אין זיי, דורך דעם וועט זיין בשבתך בביתך, די אייגענע ניצוצות מברר זיין, ובלכתך בדרך מברר זיין אין יענעם און אין עולם, דאָס איז נוגע ובשכבך יום המיתה, ובקומך תחית המתים<sup data-n=\"1\">117</sup>.",[["1","117","ספר השיחות תש\"ד ע' 143. מועתק בזה ע\"ד תורה הנ\"ל:\nאַמאָל איז הוד כ\"ק רבינו הזקן אַרויסגעקומען צו די תלמידים – עס איז דאַן געווען אַ צייט, וואָס הוד כ\"ק רבינו הזקן האָט מרגיש געווען אַז אייניגע תלמידים האָבען גענומען די זאַך ניט ריכטיג – און האָט זיי געזאָגט אַ תורה פון מורנו הבעש\"ט אויפ'ן פּסוק ושננתם לבניך: [ההמשך בפנים].\nאַז די תלמידים האָבן דאָס געהערט, זיינען זיי פיל מאָל געפאַלן אין חלשות.\nזיי האָבען גע'חלש'ט ניט ווייל זיי האָבען זיך דערשראָקען פאַר'ן יום המיתה און ניט ווייל זיי האָבן געזשאַלעוועט דעם יום הקימה. נאָר אַז מען דערזעט אַ עצמי חלש'ט מען."]]],[300010561,"מ\n\nראה יד, א: <i>בנים אתם לה' אלקיכם</i>.\n<b>בנים</b> אתם להוי' אלקיכם, באַ יצחק'ן שטייט<sup data-n=\"1\">118</sup> אלה תולדות יצחק בן אברהם אברהם הוליד את יצחק, יצחק איז געווען אברהם'ס אַ זוהן אָבער דאָס איז נאָך ניט אַלץ, ישמעאל איז אויך אברהם'ס אַ זוהן, ישמעאל בן אברהם, אמת אברהם האָט נאָך דאַן ניט געהאַט די מצות מילה און די גרויסע מעלה פון תמימות און אַז יצחק איז געבאָרען האָט שוין אברהם מקיים געווען די מצות מילה און איז שוין געווען אַ תמים און פון דעם וואס עס שטייט אלה תולדות יצחק בן אברהם וואָלטען מיר אַ טעות האָבן און מיינען אַז יצחק איז אויך מער ניט ווי אברהם הגשמית אַ זוהן האָט השי\"ת געזאָגט באַ תולדות יצחק איר זאָלט קיין טעות ניט האָבען און מיינען אַז דער יחוס פון יצחק איז מער ניט ווי דאָס וואָס יצחק בן אברהם, עס איז אַ גרעסערע יחוס וואָס איז מער ניט פאַראַן ווי באַ יצחק'ן דאָס איז אברהם הוליד את יצחק וואָס דער קלסתר פנים פון אברהם האָט נאָר יצחק און דאָס איבערגעגעבן צו יעקב אבינו בירושה לכל ישראל, און דאָס איז בנים אתם להוי' אלקיכם אַז נשמות ישראל זיינען אַ חלק מעצמות א\"ס ב\"ה<sup data-n=\"2\">119</sup>.",[["1","118","תולדות כה, יט."],["2","119","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ה ע' רמו."]]],[300010562,"מא\n\nנצבים כט, ט: <i>אתם נצבים היום</i>.\n<b>אדמו\"ר</b> הזקן סיפּר: בהיותי במעזריטש שמעתי ממורי ורבי הה\"מ בשם מורו ורבו הבעש\"ט נ\"ע:\n\"החדש השביעי שהוא החדש הראשון לחדשי השנה<sup data-n=\"1\">120</sup>, הקב\"ה בעצמו מברכו בשבת מברכים שהוא השבת האחרון דחדש אלול, ובכח זה ישראל מברכים את החדשים<sup data-n=\"2\">121</sup> י\"א פעמים בשנה, כתיב אתם נצבים היום, דהיום קאי על ר\"ה<sup data-n=\"3\">122</sup> שהוא יום הדין, וכמ\"ש<sup data-n=\"4\">123</sup> ויהי היום וגו' ותרגם והוה יום דינא רבא, ואתם נצבים קיימים ועומדים<sup data-n=\"5\">124</sup>, והיינו שזוכים בדין, ובשבת שלפני ר\"ה שהוא השבת האחרון דחדש אלול קורין אז פּרשת אתם נצבים<sup data-n=\"6\">125</sup>, דזהו ברכתו של הקב\"ה, בשבת מברכים חדש השביעי שהוא המושבע<sup data-n=\"7\">126</sup> והמשביע<sup data-n=\"8\">127</sup> ברוב טוב לכל ישראל על כל השנה\"<sup data-n=\"9\">128</sup>.",[["1","120","לשון הכתוב (שמות יב, ב). אבל הפירוש משתנה, כי כאן ההדגשה בתיבת <i>השנה</i>, כמובן. ובכ\"מ מצינו לשון אחר בכוונות מתחלפות – ראה תוד\"ה אדם (חולין סח, א. וצע\"ק בתוד\"ה אלימא קדושין מח, א) ובמקומות שהובאו ביד מלאכי כלל שעד. שדי חמד כללים ל', צח."],["2","121","ענין זה אשר הכח לברכת החדש ע\"י ישראל הוא בא מברכת החדש של הקב\"ה מרומז (ככל הענינים דפנימיות התורה) גם בנגלה והוא מפסיקתא דר\"כ פ\"ה: \"עד שלא יצאו ישראל ממצרים, הי' הקב\"ה יושב ומחשב חשבונות . . . ומחדש את החדשים כיון שיצאו ישראל ממצרים מסרן להם . . . מכאן ואילך הרי הם מסורים לכם\". דלשון \"מסרן\" \"מסורים\" משמע שמוסר להם את הכח של קידוש החדשים, שהי' הקב\"ה מקדשם, וראה במג\"א (שו\"ע או\"ח סתי\"ז, סק\"א) שברכת החדש דעכשיו שייכת לקידוש החדש דב\"ד."],["3","122","ראה פענח רזא ס\"פ נצבים. לקו\"ת ר\"פ נצבים."],["4","123","איוב ב, א."],["5","124","ראה תנחומא ר\"פ נצבים."],["6","125","תוד\"ה קללות שבת\"כ מגילה לא, ב. שו\"ע או\"ח סתכ\"ח, ס\"ד. לקו\"ת ר\"פ נצבים."],["7","126","בויק\"ר שבהערה הבאה: \"משובע\" – \"ולפענ\"ד גם ב\"היום יום\" וכש\"ט כצ\"ל\" – הערת כ\"ק אדמו\"ר זי\"ע בלקוטי שיחות ח\"כ ע' 555."],["8","127","ראה ויק\"ר פכ\"ט, ח. קיצורים והערות לתניא ע' נח."],["9","128","קובץ מכתבים בסו\"ס תהלים אהל יוסף יצחק ע' 193. אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ס\"ע תל ואילך. \"היום יום\" כה אלול. ספר השיחות קייץ ה'ש\"ת ע' 175. – ראה בביאור תורה זו – לקוטי שיחות ח\"ד ע' 1139 ואילך. ח\"ט ע' 184 ואילך. חכ\"ט ע' 173 ואילך. ועוד."]]],[300010563,"מב\n\nוילך לא, יח: <i>ואנכי הסתר אסתיר פּני ביום ההוא</i>.\n<b>עס</b> איז ידוע די תורה פון בעש\"ט<sup data-n=\"1\">129</sup> אויפן פּסוק \"ואנכי הסתר אסתיר פּני ביום ההוא\", אַז דער פּירוש פון \"הסתר אסתיר\" – <i>צוויי</i> מאָל הסתר – איז, אַז דער הסתר גופא איז פאַרבּאָרגן. ד. ה. אַז דער פאַרשטעל איז אַזוי גרויס, אַז מען פילט גאָרניט אַז דאָס איז אַ הסתר ביז אַז עס קאָן קומען ח\"ו צו – \"שמים<sup data-n=\"2\">130</sup> חשך לאור\"<sup data-n=\"3\">131</sup>.",[["1","129","ספר תולדות יעקב יוסף ר\"פ בראשית."],["2","130","ישעי' ה, כ."],["3","131","לקוטי שיחות ח\"ט ע' 193. וראה לקוטי שיחות ח\"ז ע' 41 ואילך. ח\"ו ע' 191 הערה 22. חי\"ח ע' 298 הערה 53."]]],[300010564,"מג\n\n<b>וזהו</b> בחי' אחוריים כמאן דשדי לשונאו<sup data-n=\"1\">132</sup> שאינו רוצה ליתן לו ברצון הטוב בפנים מאירות פנים בפנים, ושדי בתר כתפוי בהסתרת פנים, כמ\"ש ואנכי הסתר אסתיר פני מהם, וכמ\"ש בספר בן פורת יוסף<sup data-n=\"2\">133</sup> בשם הבעש\"ט ז\"ל שנותן להם בהסתר פנים<sup data-n=\"3\">134</sup>.",[["1","132","ראה תניא פכ\"ב."],["2","133","קיא, א."],["3","134","בונה ירושלים ע' קמ. מאמרי אדה\"ז ענינים ע' רנז. ושם:\nאבל צד הקדושה ומדו\"מ של צד הקדושה מקבלים חיותם מהקב\"ה בבחי' פּנים בפנים ע\"י השתלשלות העולמות, וזהו ישא ה' פּניו אליך, יאר ה' פּניו אליך, והם לאחדים ממש עם הש\"י, ואף שהס\"א מקבלת ג\"כ חיותה מהש\"י, אך אעפ\"כ הם מבחי' אחוריים שאינו פּנים בפנים ואינו כ\"כ לאחדים, וכמו כן אה\"ע נשמתם וחיותם הם מג' קליפות הטמאות המקבלים חיותם ג\"כ מאחוריים ומשמרים ותמצית, ולכן כל עניני עה\"ז קשים ורעים והרשעים גוברים בו, אבל ישראל נשמתם הם חלק אלוה ממעל וחיותם מאור א\"ס ב\"ה פּנים בפנים."]]],[300010565,"מד\n\nשמואל-א א, ב: <i>ויהי לפנינה ילדים ולחנה אין ילדים</i>.\n<b>ידוע</b> פי' הבעש\"ט ז\"ל ותהי לפנינה ילדים ולחנה כו', הובא בסר\"ז<sup data-n=\"1\">135</sup> ד\"ח<sup data-n=\"2\">136</sup>, כי פנינה רומז לסט\"א, כמאמר חז\"ל<sup data-n=\"3\">137</sup> שטן ופנינה כו' לש\"ש נתכוונו, וחנה רומז לשכינה, ומתרעם הכתוב על העדר הצדיקים כו' וילדים דסט\"א רבים<sup data-n=\"4\">138</sup>.",[["1","135","= בספר ר' זאב [וואלף] מזיטאמיר. – אור המאיר פ' לך לך. וראה שם פ' האזינו."],["2","136","באור המאיר דפוס ווארשא (תרמ\"ג) הוא בפ' לך לך דף ז, א. וראה שם פ' האזינו דף לה, א."],["3","137","בבא בתרא טז, א."],["4","138","אור התורה משפטים ע' א'רסה. עקב ע' תקיא. וראה אור התורה משפטים ע' א'רנח."]]],[300010566,"מה\n\nמלכים-א ה, יב: <i>וידבר שלשת אלפים משל</i>.\n<b>חשמ\"ל</b><sup data-n=\"1\">139</sup> הוא מלבוש לז\"א והיא מחיצוניות דבינה כי קליפת נוגה וחשמל היא אחת אלא שחשמ\"ל הוא קדושה וקליפת נוגה הוא חיצוניות דחשמ\"ל והיא ממוצעת בין החשמל וג\"ק שאין להם עלי' הלכך יש בנוגה בחי' טוב מחמת שהיא מקבלת מחשמל ועל ידם נשפעת הג\"ק.\nולהבין בחי' חשמ\"ל ע\"ד שאמר הבעש\"ט על וידבר ג' אלפים משל כלומר שעל כל דבר ודבר הי' לו כח להשתלשל עד שילשול קטן של ג' אלפים משל. והמשל גופא היא גדולה מהנמשל ע\"ד כל מקום שאתה מוצא גדולתו של הקב\"ה שם אתה מוצא ענוותנותו<sup data-n=\"2\">140</sup>, עד\"מ שהוא רק שכל גדול יכול לצמצם שכלו הגדול עד שהתינוק יכול להבין, משא\"כ אדם בינוני והפעולה של המשל שיכול לדבר אפילו לימוד גדול בפני כל אדם בפרהסיא כי האחרים אינם מבינים וזהו חשמ\"ל לזה הוא חשות ולזה הוא ממלל נמצא הוא מלבוש להגן מהחיצונים<sup data-n=\"3\">141</sup>.",[["1","139","ראה תו\"א לך יב, ג. סהמ\"צ להצ\"צ ז, א."],["2","140","מגילה לא, א ע\"פ הגירסא בילקוט שמעוני תהלים רמז תשצד. וראה הערת כ\"ק אדמו\"ר זי\"ע בספר המאמרים תש\"ח ע' 228."],["3","141","מאמרי אדה\"ז אתהלך לאזניא ע' כג."]]],[300010567,"מו\n\nישעי' א, טו: <i>ובפרשכם כפיכם אעלים עיני מכם גם כי תרבו תפלה אינני שומע ידיכם דמים מלאו</i>.\n<b>דער</b> בעש\"ט האָט . . דאַן מבאר געווען אַז הגם די עבודה עיקרית אין עבודת השי\"ת איז טאַקע עבודת המוח און עבודת הלב, וואָס דאָס מיינט עבודה אין לימוד התורה און עבודה אין תפלה, וואָס דורך די צוויי עבודות איז שוין במילא די עבודה אין מדות און עניני עולם ווי עס באַדאַרף צו זיין, דאָך קען אָבער זיין ידיכם דמים מלאו, אַז אפילו ווען מען גיט דעם אָרימאַן אַ נדבה ביד רחבה אָבער עס פעלט דער הרגש במצב זולתו איז דאָס שפיכת דמים, און דאָס איז ובפרשכם כפּיכם, ווען איר שפּרייט פאַנאַנדער אייערע הענט און גיט צדקה ביד רחבה, וואָס דאָס איז די עבודה פון עבודת הלב, דאָך איז אעלים עיני מכם, וועל איך דאָס ניט זעהן, ווייל דאָס איז ניט קיין עבודה אמיתית. אמיתית העבודה איז ווען מען איז מרגיש דעם זולת. גם כי תרבו תפלה וואָס מיינט עבודת המוח איז דאָס אויך קיין עבודה, ווייל מען דערהערט ניט דעם זולת מיט אַ הרגש אמיתי, איז דאָס שפיכת דמים, וואָס דאָס איז דער טייטש ידיכם דמים מלאו, אייערע מדות אַפילו די מדות טובות זיינען דמים מלאו<sup data-n=\"1\">142</sup>.",[["1","142","ספר המאמרים אידיש ע' 216 ואילך. וראה שם כל הסיפור בזה."]]],[300010568,"מז\n\nישעי' ד, ד: <i>אם רחץ ה' את צואת בנות ציון</i>.\n<b>באגה\"ק</b> סי' כב שע\"ז נאמר אם רחץ ה' צואת בני ציון כו' ברוח משפט כו' בישעי' סי' ד'. ולכן רחץ בגימטר' רחמים כ\"כ בשם הבעש\"ט נ\"ע<sup data-n=\"1\">143</sup>. וזהו ענין משפט דאיהו רחמי<sup data-n=\"2\">144</sup>.",[["1","143","ראה צוואת הריב\"ש סימן קמד."],["2","144","אור התורה תולדות קמ, א. ד\"ה ויהיו חיי שרה תשכ\"ג פ\"ב."]]],[300010569,"מח\n\nישעי' ו, ב: <i>שרפים עומדים ממעל לו</i>.\n<b>צ\"ל</b> האיך השרפים עומדים ממעל לו הוא שם אד' שנאמר תחלה, כן הקשה הבעש\"ט ז\"ל, ותי'<sup data-n=\"1\">145</sup> לפי שמח' ורצונם בהשגתם הוא בבחי' קדוש ומובדל שזהו למעלה משם אד' לכן ה\"ה כאלו<sup data-n=\"2\">146</sup> עומדים שם<sup data-n=\"3\">147</sup>.",[["1","145","ראה לקו\"ת אמור לב, סע\"ב."],["2","146","וידועה הראי' מעירובי תחומין דבמקום שדעתו שם, שם הוא מקומו (ראה שו\"ע אדה\"ז סת\"ח: לפי שדעתו של אדם כו'. פרש\"י חוץ מן המים ומן המלח – עירובין כו, ב). ובירושלמי ברכות ספ\"ו: הסיע דעתו כמו שהוא שינוי מקום. ובזח\"ג רמז, ב: אדם דאיהו מחשבה (עפ\"י לקוטי שיחות ח\"ח ע' 348. חי\"ג ע' 151. חכ\"ה ע' 124. ע' 297. ח\"ל ע' 23)."],["3","147","המשך מים רבים תרל\"ו פרק קיג. ועד\"ז הוא בלקו\"ת לג\"פ (ג, ג) נדפס באוה\"ת בראשית ח\"ו תתרכז, ריש ע\"ב: ועוי\"ל ע\"פ מ\"ש במ\"א בשם הבעש\"ט ז\"ל בתי' הקושי' על שרפי' עומדים ממעל לו היתכן שיעמדו למעלה מש' אד' המהוום. אלא מפני שרצונם בקריאתם ובאמירת קדוש ליכלל וליבטל באוא\"ס הסוכ\"ע שלמעלה מש' אד' לשון אדון כו' וה\"ה כאילו עומדים שם.\nוראה עד\"ז ספר המאמרים תרנ\"ה (ס\"ע ריב ואילך): וכמ\"ש שרפים עומדים ממעל לו, ואיתא בזוהר ממעל לשכינתא, שזהו מ\"ש קודם ואראה את אד' יושב כו' ועז\"א שרפים עומדים ממעל לו, להיות כי נק' שרפים ע\"ש הרשפי אש התשוקה שלהם וכל מהותם הוא הרצון והרשפי אש. וידוע מ\"ש הבעש\"ט ז\"ל ע\"ז דבכ\"מ שרצון האדם שם ה\"ה עומד שם, כי כל הכחות נמשכי' אחר הרצון כו' כמ\"ש במ\"א. ובפרט דהשרפים שנק' כן ע\"ש הרשפי אש שלהם. ולכן אומר שרפים עומדים ממעל לו לשכינתא, דשכינה היא בחי' מל' ששוכנת בבי\"ע ומהווה ומחי' את הנבראי' דבריאה, והם משיגים איך שהחיות הזה הוא בחי' הארה לבד, אבל עצמות אוא\"ס הוא קדוש ומובדל מהם. לכן כל חפצם ותשוקתם לעלות בבחי' עצמות אוא\"ס.\nוראה ספר המאמרים תרח\"ץ ע' רז: ומ\"ש עומדים ממעל לו הנה משמע דעמידתם היא ממעל, ובאמת הנה עמידתם ממש במקומם שהם נבראים מהאין הנמשך משם אד', אך הענין הוא דהנה כל רצוא הוא לפי ההשגה וההתעוררות המביאי' אותו, ורצוא דהשרפים בא מהשגתם באוא\"ס הסוכ\"ע, וכמא' הבעש\"ט נ\"ע דבמקום שהוא הרצון של הנברא שם הוא כולו, וכהמעשה הידוע* אשר פעם הראה הבעש\"ט נ\"ע לתלמידיו שור מלובש בבגדי ש\"ק ויושב אצל שולחן, כי הי' צדיק א' שאכל בשר לקיים מצות שבת ומפני תוקף רצונו לקיים את המצוה באכילת בשר בשבת נעשה עצמו כן, ולבושי שבת ידוע דאינם משתנים, וכן השרפים להיות הרצוא שלהם הוא בתשוקה גדולה ביותר בההשגה שלהם לכן הוא כאלו עומדים שם.\nוראה גם בשם הבעש\"ט – ספר המאמרים תרל\"ה ח\"א ע' ו. ח\"ב ע' שב. וש\"נ. תר\"ם ח\"א ע' לו. תרמ\"ג ע' סה. תרמ\"ו ס\"ע תח. תרנ\"א ע' רלח. תרנ\"ה ע' קמב. תרנ\"ו ע' של. המשך תער\"ב ח\"א ע' תקסז. ח\"ב ע' תתי. ספר המאמרים תרפ\"ח ע' לא.\nתורה זו הובאה גם בכ\"מ בשם הבעש\"ט אבל לא עה\"פ \"שרפים עומדים ממעל לו\" – ראה כתר שם טוב סימן נו. סימן ערה. אוה\"ת במדבר ח\"ד ע' א'תמב. ועד\"ז הוא בלקוטי דיבורים ח\"א קיג, ב. ספר המאמרים תרפ\"ה ע' רפה. ספר השיחות תש\"ד ע' 79-78. ע' 132. לקוטי שיחות ח\"א ע' 66. ח\"ג ע' 807. שיחת יום ב' דחג השבועות תשי\"ד (תורת מנחם התוועדויות תשי\"ד ח\"ג ע' 37).\nוראה פלח הרמון בראשית (סו, ג): כי באור הכתר אין שינוי מצד ההשתל' ולכן נאמר בשם הבעש\"ט ז\"ל שכל מקום שרצונו של אדם שם הוא בעצמו והגם שמקושר ברצונו במקום שלמעלה ממדריגתו והיינו מטעם הנ\"ל שבאור הכתר שהוא הרצון אין שינוי מצד ההשתל'. ובפלח הרמון תרומה (ע' רצד): ידוע בשם הבעש\"ט נבג\"מ כי כ\"מ שהרצון הוא שם כולו וכן בזוהר (ח\"א דס\"ט ע\"ב) א' [= איתא] מאן דכסיף אע\"ג דלא יכול.\n-----שולי הגליון-----\n*) <i>ספר המאמרים תר\"ם ח\"א ע' לו</i>.<i> תרמ\"ג ע' סה</i>.<i> שיחת ש\"פ מקץ תשד\"מ (התוועדויות תשד\"מ ח\"ב ע' 694)</i>.<i> לקמן סימן שפד</i>.<i> שעה</i>.<i> שעט</i>."]]],[300010570,"מט\n\nישעי' ס, כא: <i>ועמך כולם צדיקים לעולם יירשו ארץ</i>.\n<b>יהודים</b> פשוטים העומדים בשוק, סובבים בכפרים ובאחוזות האצילים, ומזכירים שם שמים, מתפרנסים מיגיע כפיהם ומחזיקים בני תורה ומביאים ספר לבית הכנסת בשמחה רבה, הנה ועמך כולם צדיקים והם לעולם יירשו ארץ, כי הם המרבים יראת שמים בארץ<sup data-n=\"1\">148</sup>.",[["1","148","מאמר אבות החסידות – \"התמים\" חוברת ח' ע' מ [שצו, ב]."]]],[300010571,"נ\n\nירמי' יז, ז: <i>ברוך הגבר אשר יבטח בהוי' והי' הוי' מבטחו</i>.\n<b>בשם</b> הבעש\"ט ע\"פ ברוך הגבר אשר יבטח בה' והי' ה' מבטחו דהי' לי' לכתוב והי' ה' בטחונו, אך דהנה יש ג' דברים בוטח ובטוח ומבטח והקב\"ה הוא עצמו המבטח וכו' וד\"ל<sup data-n=\"1\">149</sup>.",[["1","149","מאמרי אדמו\"ר הזקן נביאים ע' רח."]]],[300010572,"נא\n\n<b>יש</b> להבין מה ששמעתי מאדמו\"ר שליט\"א<sup data-n=\"1\">150</sup> שאמר בשם הבעש\"ט נ\"ע<sup data-n=\"2\">151</sup> על פסוק (ירמי' יז) ברוך הגבר אשר יבטח בהוי' והי' הוי' מבטחו<sup data-n=\"3\">152</sup>. שלכאורה הוא כפל לשון ואמר הפי' שמש\"א אשר יבטח בהוי' הכוונה על השפעת השפע שיושפע מאתו דייקא. ואינו מעמיד הבטחון שלו על הכלי רק ברכת הוי' היא תעשיר כו' כנ\"ל באריכות.\nואח\"כ אמר והי' הוי' מבטחו הכוונה שהוא בוטח בה' שגם הכלי יושלח לו מלמעלה וכמאמר (תהלים נ\"ה) השלך על הוי' יהבך והוא יכלכלך בריבוי כלים<sup data-n=\"4\">153</sup> אל הברכה אשר יושלח מאתו<sup data-n=\"5\">154</sup>.",[["1","150","הכוונה לאדמו\"ר הצ\"צ."],["2","151","ראה דגל מחנה אפרים עה\"פ בשלח טז, טו. אור המאיר פ' בהעלותך."],["3","152","ראה גם ספר המאמרים עזר\"ת ס\"ע קו ואילך. תרפ\"ח ע' כח."],["4","153","ראה גם מקומות שצויינו בהערה הקודמת. ספר המאמרים תרצ\"ט ריש ע' 21. אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ב ע' שכח. ח\"ד ע' תנג."],["5","154","פלח הרמון וירא סב, ג. ושם: ואח\"כ אמר [אדמו\"ר הצ\"צ] שבמדרש פירשו בזה הפסוק דרך יותר עמוק והיינו בפ' שופטים פ\"ה אמרו כל הבוטח בה' זוכה להיות כיוצא בו שנאמר ברוך הגבר כו'. ולכאורה אינו מובן, ואמר שהכוונה הוא ע\"ד (פ\"ה דב\"ב ע\"ה ע\"ב) עתידים צדיקים שיאמרו לפניהם קדוש, וזהו כיוצא בו שעכשיו אומרים המלאכים קדוש לפני הוי' ולעתיד יאמרו קדוש לפני הצדיקים עכד\"ק. והנה לפ\"ד לא היתה כוונת אדמו\"ר שליט\"א אשר דרך המדרש הוא דרך אחר לגמרי מדרך הבעש\"ט נ\"ע, רק באמת שני הדרכים עולים בקנה אחד, רק שהמדרש דיבר במקום עליון ועמוק יותר כמשי\"ת (עיי\"ש הביאור).\nוראה ד\"ה בשם הבעש\"ט נ\"ע על הפסוק ברוך הגבר דשנת תרי\"ד – הנחת הר\"ה מפּאַריטש."]]],[300010573,"נב\n\nירמי' כג, כד: <i>אם יסתר איש במסתרים ואני לא אראנו נאם ה'</i>.\n<b>וכפירוש</b> הבעש\"ט אויף דעם פּסוק \"אם יסתר איש במסתרים ואני לא אראנו נאם ה'\" – בניחותא: \"אם יסתר איש במסתרים ואני – לא אראנו\", אַז בשעת אַ מענטש איז \"ואני\", ער איז ביי זיך אַ \"איך\", איז \"לא אראנו\", דער אויבערשטער כביכול זעט אים ניט<sup data-n=\"1\">155</sup>.",[["1","155","לקוטי שיחות ח\"ד ע' 1033."]]],[300010574,"נג\n\nירמי' לא, יב: <i>אז תשמח בתולה במחול</i>.\n<b>הנה</b> הבעש\"ט ז\"ל המשיל כ\"ז במשל אחד (אשר בו מלובש הנמשל העמוק מאד סודות התורה מה שמבאר ר' חיים וויטאל בס' ע\"ח כולו הלביש זה במשל א') והיינו משל לסולם העגולה (שקורי' בל\"א שווינדעל טרעפ\"ף) העשוי ע\"ג עמוד א' והמדריגות סובבי' את העמוד בעיגול והמדריגות הם זה למעלה מזה בעיגול וסיבוב העמוד עד שמגעת המדרגה העגולה העליונה לראש העמוד אשר בראש העמוד נחקק ונצטייר איזה צורה או נבנה איזה בית קטן, והנה העולה על סולם הזה למעלה עד שמגיע קרוב לעמוד אזי הוא רואה מקום עמידתו סמוך לעמוד ממש למעלה את הצורה הנמצאת בראש העמוד מפני שהמדריגו' סובבים העמוד ובתוכם נשאר חלל (היינו סמוך לעמוד ממש הוא החלל כו') ולכן כנתקרב סמוך לעמוד ממש אזי מביט בעיניו למעלה אל הצורה שבראש העמוד שאין שום דבר מסתיר לו המראה וכיון שהוא מתחיל לצעוד על המדריגה השני' שלמעלה מן הראשונה בסיבוב ועיגול המדריגה אזי בתחלת הילוכו עליה הוא נתרחק מעל העמוד מעט מאחר שהמדריגו' עגולות כו' ואזי אינו רואה את הצורה שבראש העמוד שנסתרה ונעלמה ממנו מפני שהמדריגות מסתירי' כו' וכאשר נסמך לעמוד בקירוב ממש אזי יראנה כנ\"ל וכאשר יצעוד על מדריגה השלישית אז יהי' נכסה ממנו הצורה כו' כנ\"ל (מאחר שהמדריגות מעוגלים ומסובבי' על העמוד והעמוד הוא בתווך והצורה על ראש העמוד ממש לכך כשנסמך לעמוד יראה וכשיעלה לראש המדריגה שני' שאז נתרחק מן העמוד אזי יהי' נכסה הצורה הימנו והיינו כזה<sup data-n=\"1\">156</sup> ודו\"ק היטב) נמצא העולה מזה שכאשר לא יראה הצורה שיהי' נכסה ממנו אז הוא במדריגה הנעלה מכאשר רואה את הצורה שאז הי' במדריגה התחתונה הימנה סמוך לעמוד ממש ועתה שאינו רואה אותה הוא עומד על ראש המדריגה השני' שלמעלה והוא רחוק מן העמוד לכך לא יראנה וכן מקום עמידתו במדריגה השני' סמוך לעמוד שאז רואה הצורה הוא נחשב למדריגה התחתונה לגבי מקום עמידתו על ראש המדריגה השלישית שאז אינו רואה שנכסי' ממנה שאז נתרחק מן העמוד כו' נמצא בכ\"מ מקום הראי' הוא למטה מן המקום שאינו רואה משום (שהראי' הוא במקום התחתון וההעלמ' הוא במקום העליון כשתחיל לעלו' על המדרי' הנעלה הימנה כנ\"ל) וכן מקום שרואה משם הוא תמיד בקירוב מקום לגבי העמוד שהוא סמוך אליו ממש ומקום הנעלם ונכסה הוא תמיד בקירוב מקום לגבי העמוד שהוא סמוך אליו ממש ומקום הנעלם ונכסה אז הוא רחוק מן העמוד בריחוק מקום כו', ע\"כ המשל מהבעש\"ט ז\"ל<sup data-n=\"2\">157</sup>.",[["1","156","במאמרי אדה\"ז כאן יש ציור."],["2","157","מאמרי אדמו\"ר הזקן תקס\"ה ח\"א ע' ריד ואילך. וממשיך שם: והנמשל הוא עמוק עמוק מאד [עיי\"ש בארוכה]. ובאוה\"ת נ\"ך ח\"ב ע' תתפד: הנה הבעש\"ט אמר משל (ובו מלובש נמשל עמוק מאד מסודות התורה שביאר הרח\"ו ז\"ל בע\"ח כמו שית' הלביש כ\"ז הבעש\"ט במשל אחד) ממעלות אחורנית הנקרא בלשון אשכנז שווינדעל טרע\"פּ אשר כשעומד אצל העמוד רואה למעלה (ר\"ל שרואה הצורה שנחקק בראש העמוד עד\"מ) וכשנצרך לו לילך למעלה השנייה שהיא יותר גבוה ממעלה הראשונה ואז יתקרב יותר אל הצורה אשר בראש העמוד צריך מקודם לסבב העמוד עד שנראה כאילו מתרחק ומסתתר (כי כשמסבב העמוד מאחוריו כדי שיבא למעלה שניה הרי בינתיים הוא מאחורי העמוד ואז אינו רואה כלום הרי נראה כאילו מתרחק כו' ובאמת אז הוא יותר קרוב שהרי עי\"ז יבא למעלה שניה לראות בטוב יותר וכן אח\"כ לעלות בכל המעלות ממעלה למעלה צריך מקודם לסבב העמוד מאחוריו ואז אינו רואה כו', ובמלכים א' סי' ו' ובלולים יעלו וע\"ש בפרש\"י שזהו ענין שוינדעל טרע\"פּ וכ\"כ בלשון אשכנז שם ורש\"י קראו שווינדעל שטיין) כו' כמו כן מבואר בע\"ח בעליות המלכות להיות פּב\"פּ צ\"ל מקודם אב\"א (וכמ\"ש במ\"ח דס\"ט ע\"ב מאחורי ז\"א ומסבב מאחוריו ותבא לפניו כו') [עיי\"ש בארוכה]."]]],[300010575,"נד\n\n<b>כמ\"ש</b> במ\"א בשם הבעש\"ט ע\"פ אז תשמח בתולה במחול ממשל הבלילות שאחר פּב\"פּ וקירוב מוכרח להיות הסתר בכדי שאזי דוקא יוכל לבא לבחי' פב\"פ בקירוב יותר וכדרך הריקוד שמתקרבים וחוזרים ומתרחקים<sup data-n=\"1\">158</sup>.",[["1","158","אור התורה עקב ע' תקכב. ד\"ה ויענך תשי\"ז פ\"ה (תורת מנחם – התוועדויות ח\"כ ס\"ע 209). וראה אור תורה להרב המגיד נב, סע\"א (ושם קה, א – לא בשם הבעש\"ט). אור התורה נ\"ך ח\"ב ע' רלח. המשך תער\"ב ח\"ב ס\"ע תשכב ואילך. וברשימת היומן מכ\"ק אדמו\"ר מהוריי\"צ מוצש\"ק וירא תרנ\"ד (\"התמים\" חוברת ג' ע' כו [קכט, ב]): אחרי כן אמר כ\"ק אאמו\"ר מאמר, אז תשמח בתולה במחול, המשל מהבעש\"ט בשווינדעל-טרעפּ, בענין העלי' מדרגא לדרגא בדרך קירוב וריחוק. כ\"ק אאמו\"ר סיפר, כי מאמר זה אמר כ\"ק אביו אאזמו\"ר בשנת תרל\"ט, בעת שנולדה בת לדודתי מ' דבורה לאה. וראה גם ספר השיחות תרצ\"ט ע' 306: והראה – הצ\"צ – בפאַטשיילע שילכו לרקוד. ואמר [הצ\"צ] שהבעש\"ט אמר כי מחול הוא קירוב וריחוק וכידוע במשל השווינדעל טרעפּ."]]],[300010576,"נה\n\nירמי' לא, כו: <i>וזרעתי את בית ישראל</i>.\n<b>כל</b> אחד מישראל הוא גרעין של זריעה, ובגרעינים הנזרעים ישנם גרעיני תבואה וגרעיני פירות<sup data-n=\"1\">159</sup>.",[["1","159","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' קכו. ח\"י ע' תיט.\nוממשיך שם: כ\"ק אדמו\"ר הזקן הרחיב לבאר בההפרש שבין גרעיני תבואה וגרעיני פירות אם כי שניהם כאחד מצמיחים בחלקת אדמה חרושה דוקא, מכל מקום חלוקים הם בזה כי התבואה צריכים לזרוע בכל שנה ושנה וגרעיני פירות הנה כשנוטעים אותם פעם הם עושים פירות שנים רבות.\nובאחת משיחות הקדש בימי מועד ושמחה אשר שח הוד כ\"ק אאמו\"ר הרה\"ק בעניני עבודה הואיל לבאר בההפרש שבין זריעה לנטיעה, ונושא הדיבור הי' כי החסידים הראשונים היו כאילנות נטועים על פלגי מים, ובגודל המסירות נפש שלהם על דרכי החסידות פעלו אשר בהדורות הבאים מהם יהי' בהם רגש פנימי של יראת שמים.\nאז – בשיחה ההיא – הפליא במעלת גזע החסידים, וביאר המארז\"ל אחד מכם גולה לברבריא כו' וכה הי' דברי קדשו, \"אַז אַ חסידות'ר אייניקל פאַר פאָרט אפילו אין אַ ארץ רחוקה לעבט ער אויף דעם אָרט עס ווערט אַ מקוה, אַ חדר, אַ מנין, מי לערנט אַ וואָרט חסידות מי מאַכט אַ הכנה לביאת משיח צדקנו בב\"א\"."]]],[300010577,"נו\n\nהושע יד, ב: <i>שובה ישראל עד הוי' אלקיך כי כשלת בעוניך</i>.\n<b>רבינו</b> בשם . . המגיד ממעזריטש בשם מורו הבעש\"ט נ\"ע פי' שובה ישראל עד הוי' אלקיך כי כשלת בעוניך לכן שובה ישראל, ואופן התשובה הוא עד כי הוי' יהי' אלקיך והוא ע\"י התעוררות פנימי בתוקף עצמי<sup data-n=\"1\">160</sup>.",[["1","160","ספר המאמרים תש\"ה ע' 21. ושם: וביאר רבינו נ\"ע דבכל השילובים הנה האות הראשון גובר ובשמות הוי' ואלקים הנה האות הראשון הוא היו\"ד דשם הוי' ואות השני הוא הא' דשם אלקים וכן כולם עד אות י' דשם אלקים וההמשכה היא באות מ' דשם אלקים דאותיות השילוב הם הוי' אלקי ופירושו דשם הוי' נרגש בפנימיותו שהוא אלקי ממש וזה גורם התעוררות פנימי בתוקף עצמי להיות מושל ומולך על עצמו שהוא אות מ' דשם אלקים המרמז לענין התוקף עוז דספי' המל' מצד שרשה הנעלם לכן היא מ\"ם סתומה ומתגלה ע\"י תשובה עילאה שהיא התשובה דמדרי' ישראל . . ופי' . . של מורנו הבעש\"ט נ\"ע שובה ישראל עד שהוי' יהי' אלקיך היא תשובה עילאה. וראה גם לקו\"ת ד\"ה שובה ישראל (הראשון). אוה\"ת דרושים לשבת תשובה ד\"ה שובה ישראל. ובכ\"מ. וראה גם ספר לקו\"א להרב המגיד הוספות ע' 12."]]],[300010578,"נז\n\nמלאכי ג, יב: <i>כי תהיו אתם ארץ חפץ אמר ה' צבאות</i>.\n<b>עס</b> שטייט כי תהיו אתם ארץ חפץ אמר ה' צבאות, אָט אַזוי ווי די גרעסטע חכמים וועלן אייביג ניט דערגיין די גרויסע טבעיות'דיקע אוצרות, וועלכע השי\"ת האט טובע געווען בארץ, אַז הכל הי' מן העפר<sup data-n=\"1\">161</sup>, אָט אַזוי קען קיינער ניט דערגיין די גרויסע אוצרות וואָס ליגן אין אידן, וואָס זיי זיינען דעם אויבערשטנ'ס ב\"ה ארץ חפץ. וסיים הבעש\"ט: איך וויל מאַכן פון אידן, אַז זיי זאָלן געבן דעם יבול, וואָס דעם אויבערשטנ'ס ב\"ה אַ ארץ חפץ קען געבן<sup data-n=\"2\">162</sup>.",[["1","161","קהלת ג, כ."],["2","162","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' רפה (הועתק ב\"היום יום\" יז אייר). וראה אגרות-קודש שם ע' קפ. ע' קפח. ע' רפה. ח\"ד ע' קיט (הועתק ב\"היום יום\" ב אלול). מאמר ד\"ה ארשב\"נ תר\"ץ. ספר השיחות תרצ\"ו ע' 41. ע' 123. וראה לעיל סימן כט. לקמן סימן קכה. קמב."]]],[300010579,"נח\n\nתהלים טז, ח: <i>שויתי ה' לנגדי תמיד כי מימיני בל אמוט</i>.\n<b>דער</b> שם הוי' דאַרף זיין אַזוי ווי אַ חבר, אַז מ'גיט אַ חבר שלום איז דאָך ימינו כנגד שמאל חבירו, אַזוי דאַרף דער שם הוי' פּועל זיין על שמאלו. וואָרום כי מימיני איז דאָך בל אמוט, איז דער שם הוי' דאַרף פּועל זיין על שמאלו<sup data-n=\"1\">163</sup>.",[["1","163","ספר השיחות תש\"ג ע' 50. ושם, שרבינו הזקן קבלו בשם מורנו הבעש\"ט שהי' לו בקבלה בשם הרב אלי' בעל שם."]]],[300010580,"נט\n\nתהלים יט, ח: <i>תורת ה' תמימה משיבת נפש</i>.\n<b>די</b> תורה איז נאָך גאָר גאַנץ, קיינער האָט זי נאָך ניט אָנגערירט, ווייל תורת ה' משיבת נפש, אַז מען גייט צו לערנען די תורה באמונה טהורה ויראת שמים איז דער אור התורה משיב נפש, גיט אַ גרויסע התחזקות אין דער הבנה פון גדולת הבורא ב\"ה. במילא בלייבט די תורה תמימה, קיין מענטש האָט זי נאָך ניט באַרירט (ראה יל\"ש תהלים רמז תרעד)<sup data-n=\"1\">164</sup>.",[["1","164","ספר השיחות תש\"ג ע' 180. וראה מאור עינים אבות בסופו. סד\"ה ואהי' אצלו אמון תשכ\"א (ספר המאמרים תשכ\"א ע' 359). שיחת יום ב' דחג השבועות תשכ\"א בתחילתו."]]],[300010581,"ס\n\nתהלים כב, ד: <i>ואתה קדוש יושב תהלות ישראל</i>.\n<b>. . . האָט</b> דער רבי דער בעש\"ט געפרעגט ביי דעם גאון ווי גייט עס אים אין געזונט, צי האָט ער זיין הצטרכות און הספּקה, דער גאון האָט זיך אויף דעם רבי'ן, וועלכער איז געווען געקליידעט ווי אַ פּשוט'ער דאָרפסמאַן, ניט אומגעקוקט. דער רבי האָט עטליכע מאָל געפרעגט די פראַגען ביז דער גאון איז געוואָרן זייער בייז און מאַכט צום רבי'ן מיט דער האַנט אָנווייזענדיג אויף דער טיר אַז ער זאָל אַוועקגיין. זאָגט דער רבי דער בעש\"ט צום גאון, רבי פאַרוואָס גיט איר ניט דעם כביכול זיין פּרנסה כו'<sup data-n=\"1\">165</sup>. הערענדיג די דאָזיגע רייד איז דער גאון געבליבן ווי צעטומעלט. עפּעס אַ איד אַ דאָרפסמאַן רעדט וועגן דעם כביכול אַז מען דאַרף דעם כביכול געבען פּרנסה א.ז.וו.\nדער רבי דער בעש\"ט האט דערקענט די מחשבות פון דעם גאון, זאָגט ער צו אים די אידן זיצען אויף דער פּרנסה וואָס השי\"ת גיט זיי, אויף וואָס פאַר אַ פּרנסה זיצט דער כביכול. דאָס זאָגט אונז דוד המלך אין תהלים ואתה קדוש און דו הייליגער אויף וואָס פאַר אַ פּרנסה זיצסטו יושב תהלות ישראל, דער כביכול זיצט אויף די אידישע לויבונגען וואָס אידן לויבן אים ב\"ה פאַר דעם געזונט און פּרנסה וואָס ער ב\"ה גיט זיי, און פאַר די לויב ווערטער וואָס אידן לויבען השי\"ת גיט ער ב\"ה זיי בני חיי ומזוני רויחא<sup data-n=\"2\">166</sup>.",[["1","165","ראה במאמר שם ס\"ב בביאור מרז\"ל (שהש\"ר פ\"א, ט בסופו) \"רעיתי – מפרנסתי\"."],["2","166","ספר המאמרים אידיש ע' 138 ואילך. מועתק בזה קטע מהמאמר ע\"ד תורה הנ\"ל שסיפר הרב המגיד לאדמו\"ר הזקן וביאורו בלקוטי שיחות ח\"ז ע' 135 ואילך:\nדער הייליגער בעש\"ט ווען ער איז נאָך געווען אַ נסתר און האָט געוואַנדערט פון שטאָדט צו שטאָדט און פון דאָרף צו דאָרף איז ביי דעם הייליגען בעש\"ט געווען איינע פון זיינע עבודות הקודש צו פרעגן ביי יעדער אידן, מענער און פרויען, אַלט און יונג, ווי עס גייט זיי אין געזונט . . אין פּרנסה, און איז זייער געווען צופרידען צו הערען די אים ליבע ענטפערס וואָס די אידען, מענער, פרויען און קינדער פלעגן אים ענטפערן מיט פאַרשידענע ג-ט לויבענישן אויסשפּראַכן, ברוך השם, געלויבט השי\"ת . . .\nאיין מאָל האָט פּאַסירט אַז דער רבי דער בעש\"ט איז געקומען אין אַ געוויסן ישוב, האָט דער רבי דער בעש\"ט זיך געפירט מיט זיין הייליגען דרך אין עבודת השם אויף מזכה צו זיין די אידן, מענער, פרויען און קינדער, מיט דעם גרויסען זכות וואָס זיי לויבען ג-ט ב\"ה'ס הייליגען נאָמען. אין יענעם ישוב איז געווען אַ איד אַ גאָר טיפער זקן אַ גרויסער תלמיד חכם, אַ פּרוש פון אַלע וועלטליכע זאַכן. שוין איבער אַ יובל, פופציג יאָר, אַז ער זיצט יומם ולילה און לערנט די הייליגע תורה בפרישות ובקדושה. אַלע זיינע יאָרן איז ער אַ יושב בתענית אין טלית ותפלין ביז שפּעטיגער מנחה און ערשט נאָך תפלת ערבית איז ער טועם אַ שטיקעל ברויט מיט וואַסער.\nווען דער רבי דער בעש\"ט איז אַריינגעגאַנגען צו דעם גאון איז דער פּרישות שטיבל וואָס איז געווען אין אַ ווינקעל פון דער שוהל האָט [ההמשך בפנים. וממשיך בלקוטי שיחות שם:]\nדאַרף מען פאַרשטיין: אמת טאַקע אַז בכדי דער \"ואתה קדוש\" [וואָס מצד עצמו איז ער קדוש ומובדל פון עולמות] זאָל זיין \"יושב\" [ד. ה. ער זאָל נמשך ווערן למטה, וואָס די המשכה ווערט אָנגערופן \"בשם ישיבה כמו היושב שמשפּיל קומתו\"<sup data-n=\"3\">1</sup>], דאַרף זיין די עבודה פון אידן – אָבער, לכאורה, קען מען דאָס אויפטאָן אויך דורך לימוד התורה<sup data-n=\"4\">2</sup>.\nהיינט פאַרוואָס האָט דער בעש\"ט געזאָגט צום גאון, וועלכער האָט געלערנט תורה יומם ולילה במשך פון איבער אַ יובל<sup data-n=\"5\">3</sup> יאָרן, \"פאַרוואָס גיט איר ניט דעם כביכול זיין פּרנסה כו'\" – ובפרט אַז אויך דאַן, בעת דער בעש\"ט האָט אים דאָס געזאָגט, האָט ער געהאַלטן אינמיטן לערנען?\nואפילו אַז מ'וועט שוין מבאר זיין אַז דער \"ואתה קדוש\" טוט זיך אויף דוקא דורך \"תהלות ישראל\"\n– האָט דאָך דער בעש\"ט געקענט מעורר זיין דעם גאון ער זאָל לויבן דעם אויבערשטן אויף דעם וואָס ער לערנט \"בפרישות ובקדושה\", פאַרוואָס האָט ער אים געדאַרפט פרעגן וועגן ענינים גשמיים (געזונט וכו')?\nנאָר דער ביאור אין דעם איז:\nדער תכלית כוונת הבריאה איז, עס זאָל זיין אַ דירה לו ית' <i>בתחתונים</i><sup data-n=\"6\">4</sup>, אַז פון די <i>נידעריקע</i> ענינים זאָל מען מאַכען אַ דירה צום אויבערשטן. און אָט די \"דירה\" ווערט אויפגעטאָן\n[בעיקר – דורך עבודת האדם בתחתונים, ניט אַזוי דורך לימוד התורה, אָדער דורך לויבן דעם אויבערשטן פאַר לימוד התורה – ווייל לימוד התורה איז בעיקר שייך צו דעם \"עליון\" וואָס איז דאָ באַ אַ אידן, צו דער <i>נפש האלקית</i> – נאָר]\nדורך לויבן דעם אויבערשטן \"פאַר געזונט און פּרנסה\" – ענינים וועלכע זיינען שייך צום גוף און נפש החיונית<sup data-n=\"7\">5</sup>: דורך דעם וואָס אידן \"דערהערן\" אַז (אויך) זייערע גשמיות'דיקע צרכים קומען פון אויבערשטן און זיי לויבן אים דערפאַר – דורך דעם מאַכט מען אַ דירה לו ית' <i>בתחתונים</i>.\nאון דעריבער, ווען דער בעש\"ט האָט געזען ווי דער גאון זיצט אין אַ <i>פּרישות</i>-שטיבל, אָפּגעשיידט פון אַלע וועלטליכע זאַכן, ניט האָבנדיק צו טאָן מיט זיין גוף, נה\"ב וחלקו בעולם – מיט \"תחתונים\"\n(וואָרום דאָס וואָס ער האָט געגעסן איז געווען בלויז להכרח קיומו, ער האט זיך אָבער ניט אָפּגעגעבן מיט מברר זיין דעם גוף, נה\"ב וחלקו בעולם),\nהאָט ער אים געזאָגט \"פאַרוואָס גיט איר ניט דעם כביכול זיין פּרנסה\"<sup data-n=\"8\">6</sup> עס זאָל מקויים ווערן דער נתאווה הקב\"ה להיות לו ית' <i>דירה בתחתונים</i>.\nאון דערפאַר האָט דער בעש\"ט געזאָגט, אַז \"דער כביכול זיצט אויף די אידישע לויבונגען וואָס אידען לויבן אים ב\"ה פאַר דעם <i>געזונט און פּרנסה</i> וואָס ער ב\"ה גיט זיי\"<sup data-n=\"9\">7</sup>.\n-----שולי הגליון-----"],["3","1","<i>לקו\"ת קדושים כט</i>,<i> ג</i>."],["4","2","<i>וראה לקו\"ת בהר מ, סע\"א ואילך, שענין \"רעיתי\" (ראה לקו\"ש ח\"ז ע' 136 הערה 10) הוא ע\"י התורה – לכו </i>לחמו בלחמי."],["5","3","<i>שנקרא </i>\"<i>עולם</i>\"<i> (תדבא\"ר פ\"ו</i>.<i> מכילתא ורש\"י משפטים כא</i>,<i> ו</i>.<i> וראה בחיי וציוני שם)</i>."],["6","4","<i>תנחומא נשא טז</i>.<i> וראה לקוטי שיחות ח\"ו ע' 17 הערה 42</i>."],["7","5","<i>ראה תניא פל\"ז (מח</i>,<i> ב)</i>."],["8","6","<i>וע\"ד – להבדיל באין קץ – הפרנסה (המזון) כפשוטה</i>,<i> שבהעדר המזון אז נפרדת הנשמה מהגוף – עד\"ז הוא גם בענין מפרנסתי למעלה – בזה תלוי קיום הענין דנתאווה הק' להיות לו ית' דירה בתחתונים</i>.<i> וכמחז\"ל מה הקב\"ה מלא כל העולם אף הנשמה מלאה את כל הגוף (ברכות י</i>,<i> א</i>.<i> וראה ויק\"ר ספ\"ד (ובכ\"מ) בסדר הפוך – שהובא בכ\"מ</i>:<i> הנפש הזו ממלא את הגוף והקב\"ה ממלא את עולמו כו')</i>."],["9","7","<i>ועפ\"ז יובן מה שהבעש\"ט הפסיקו באמצע לימודו – אף שת\"ת גדולה מכל המצות (הל' ת\"ת לאדה\"ז פ\"ד רה\"ג) – כי בלי הילול זה</i>,<i> חסר גם בהתורה שלומד</i>.<i> וכמרז\"ל (יבמות קט</i>,<i> ב) כל האומר אין לי אלא תורה אפילו תורה אין לו</i>."]]],[300010582,"סא\n\nתהלים לד, טו: <i>סור מרע ועשה טוב בקש שלום ורדפהו</i>.\n<b>אין</b> יעדער דבר גשמי פון דברים המותרים זיינען פאַראַן טוב ורע: דער גשמי איז רע און דער חיות אלקי וואָס איז מחי' דעם גשמי איז טוב. באַדאַרף דער מענטש וואָס באַנוצט דעם גשמי זיין אַ סור מרע, ניט וועלען דעם תענוג וואָס איז פאַראַן אין דעם גשמי, און זיין ועשה טוב וועלען געשפּייזט און געהאלפען ווערן פון דעם חיות אלקי וואָס איז אין דעם דבר הגשמי. בקש שלום ורדפהו דער מענטש וואָס איז אַ סור מרע און אַ ועשה טוב, באַדאַרף זוכן און נאָכלויפן צו מאַכן שלום צווישן דעם גשמי און חיות אלקי וואָס איז אים מחי'<sup data-n=\"1\">167</sup>.",[["1","167","ספר המאמרים אידיש ע' 75 (הועתק ב\"היום יום\" ה מנחם-אב)."]]],[300010583,"סב\n\nתהלים מז, ו: <i>עלה אלקים בתרועה הוי' בקול שופר</i>.\n<b>ואמר</b> מורנו הבעש\"ט נ\"ע העלי' משם אלקים וההמשכה משם הוי'<sup data-n=\"1\">168</sup>.",[["1","168","ספר המאמרים תרצ\"ט ע' 10, ולאח\"ז שם: וביאר הה\"מ נ\"ע דכאשר העלי' הוא משם אלקים דשם אלקים עולה אז ההמשכה משם הוי' דשם הוי' נמשך. והסביר רבינו נ\"ע עלה אלקים בתרועה הוי' בקול שופר דיש ג' אופני עבודה בשופר דר\"ה תקיעה צעקה בקול פשוט שברים בקול נפסק דגנוחי גניח בלב נשבר, ותרועה ילולי יליל בקלא פנימאה דצעקת הלב וכתי' אשרי העם יודעי תרועה יודעי דייקא ואז הוי' באור פניך יהלכון בהילוך בהרחבה. וצ\"ל מהו ביאורו דהרב המגיד דכאשר העלי' הוא משם אלקים דשם אלקים עולה אז ההמשכה משם הוי' דשם הוי' נמשך, דמשמע מזה דיש איזה תנאי בהעלי' שנעשה משם אלקי' והתנאי הוא דשם אלקים עולה בעלי' זו, דממוצא דבר מובן דיש אופן עלי' אשר גם העלי' ההיא באה משם אלקים אבל בהעלי' ההיא אין שם אלקים עולה, וכן ההמשכה משם הוי' שנעשה ע\"י עלי' זו אינה דומה לההמשכה שנעשה דכאשר אלקי' עולה דאז דוקא הנה שם הוי' נמשך, וזהו שהסביר רבינו דבשופר דר\"ה יש ג' אופני עבודה, דתקיעה עם היותה בקול פשוט אבל היא צעקה בקול, ולמעלה מזה הוא העבודה דשברים דגנוחי גניח אבל זהו שבירה, ולמעלה מזה צעקת הלב בקלא פנימאה דעבודת התרועה ע\"י הידיעה הו\"ע ההזדככות שנעשה כלי לקבלה להיות באור פניך יהלכון.\nובספר המאמרים שם ע' 19 ממשיך: וזהו שאמר הבעש\"ט העלי' משם אלקים, וידוע דעי\"ז נמשך גילוי אור עליון משם הוי' שהוא בחינת גילוי, וזהו ההמשכה משם הוי', אמנם יש אופן עלי' דנעשה ע\"י שבירת הגשם והחומר, דזהו ג\"כ מהגבורות קשות דשם אלקים, וזהו שביאר הרב המגיד דענין העלי' הוא כאשר שם אלקים עולה היינו ע\"י הבירורים ולא בדרך שבירה ח\"ו, ואז הנה ההמשכה הוא משם הוי' גילוי אור עצמי, וזהו שהסביר רבינו דעלה אלקים היינו העלי' האמיתית הוא ע\"י העבודה דתרועה שהו\"ע ההזדככות דוקא, וכתיב אשרי העם יודעי תרועה, כאשר ההזדככות הוא ע\"י ידיעה דוקא, היינו ענין ההתבוננות בהשגה דשם אלקים ואז הנה הוי' באור פניך יהלכון דכל ההליכות שלהם גם בעניני עולם יהי' בהרחבה בטוב רוחני וגשמי."]]],[300010584,"סג\n\nתהלים סג, ב: <i>צמאה לך נפשי כמה לך בשרי</i>.\n<b>וכמו</b> שפירש מורנו הבעש\"ט נ\"ע מ\"ש ברש\"י ז\"ל כמה לשון תאוה ואין לו דמיון, שהתאוות בשרי' מה שהאדם מתאוה מצד טבע הגוף שהטביע הקב\"ה בתולדתו אין להם שום דמיון כלל לאותה התאוה שנתאוה דוד המע\"ה בבשרו לאלקות<sup data-n=\"1\">169</sup>.",[["1","169","ספר המאמרים תש\"ג ע' 178."]]],[300010585,"סד\n\nתהלים סג, ג: <i>כן בקודש חזיתיך</i>.\n<b>ואמר</b> רבינו הזקן נ\"ע בשם הבעש\"ט הלואי בזמן הבית חזיתיך<sup data-n=\"1\">170</sup>.",[["1","170","ספר המאמרים תרפ\"ט ע' 215. וראה שם ע' 121. ספר המאמרים ה'ש\"ת ע' 11. תש\"א ע' 150. תש\"ב ע' 57. ספר השיחות תרח\"ץ ע' 286 הערה 2. לקוטי שיחות ח\"ד ע' 1331. ובספר המאמרים תרפ\"ט שם: כלומר הלואי בזמן הבית חזיתי גילוי אור כמו הגילוי אור שממשיכים ע\"י העבודה בזמן הגלות. וטעם הדבר הוא לפי שבזמן הבית הוא העבודה במוח ולב, שיש בזה תענוג רב, ושמחת הנפש. אבל בזמן הגלות העבודה הוא בקבע\"ו ובמסירת נפש. איז דער מס\"נ וואָס אַ איד האָט בזמן הגלות אויף לערנען תורה וקיום המצות ובפרט בזמן הגזירה שמענישים ע\"ז, והוא מוסר נפשו ע\"ז הנה על ידי מסירת נפש זה ממשיכים אורות גדולים ועצומים הרבה יותר מכמו זמן הבית.\nוראה לקו\"ת שמע\"צ צב, ב. שה\"ש נ, ריש ע\"ג. מאמרי אדמו\"ר האמצעי ויקרא ח\"א ע' קה. דברים ח\"ג ע' א'צה. ספר המאמרים עטר\"ת ע' שיב. תרפ\"ג ס\"ע רכח ואילך. תש\"ט ע' 191. וראה זח\"ב קמ, סע\"א ואילך."]]],[300010586,"סה\n\nתהלים סה, ה: <i>אשרי תבחר ותקרב</i>.\n<b>אשרי</b> איז ר\"ת: אמן יהא שמי' רבא, הגם עס זיינען דאָ דרגות, ישכון חצריך ביתך קדוש היכלך וגו' (ווי עס שטייט אין לקו\"ת<sup data-n=\"1\">171</sup>), מ\"מ איז ביי איש\"ר זיינען אַלע גלייך<sup data-n=\"2\">172</sup>.",[["1","171","ד\"ה כי תשמע בקול ס\"ב [לקו\"ת פ' ראה כג, ב]."],["2","172","ספר השיחות תש\"ד ע' 140. ושם לפנ\"ז: הוד כ\"ק אאזמו\"ר הרה\"ק צ\"צ האָט דעמאָלט (חה\"ש תר\"ד) דערציילט, אַז דער בעש\"ט פלעגט פריער אַרומגיין פון ישוב צו ישוב און פון דאָרף צו דאָרף און האָט צונויפגענומען אַלע אנשים פּשוטים און האָט זיי זייער מקרב געווען. איין מאָל האָט ער צונויפגענומען אַלע מענטשן פון ישוב, אנשים נשים וטף און האָט פאַר זיי געזאָגט: [ההמשך בפנים]. ולאח\"ז מסיים: און מיט דעם האט דער בעש\"ט אַריינגעבראַכט אין זיי אַ חיבה צו איש\"ר. וראה שיחת יום ב' דחג השבועות תשי\"ד (תורת מנחם התוועדויות תשי\"ד ח\"ג ע' 28 ואילך). אחרון של פסח תשכ\"ט."]]],[300010587,"סו\n\nתהלים עא, ט: <i>אל תשליכני לעת זקנה</i>.\n<b>הבעש\"ט</b> פי' אל תשליכני לעת זקנה שלא יזדקנו דברי תורה אצלך אלא בכל יום יהיו בעיניך כחדשים<sup data-n=\"1\">173</sup>.",[["1","173","אור התורה יתרו ע' תתב בשם אור המאיר (פ' יתרו). וראה לקוטי שיחות ח\"ז ע' 230 ואילך ובהערות שם. וממשיך באוה\"ת שם: וזהו\"ע כנפי נשרים שבנשר נאמר תתחדש כנשר נעוריכי, אך במא\"א אות נו\"ן סנ\"ה כ' נשר נק' מט\"ט המתחדש כנשר זה קרוי נער.\nוראה אוה\"ת בשלח ע' שפב: ובזה יובן מה שאנו מבקשים אל תשליכנו לעת זקנה והקשה באוה\"מ פ' יתרו בשם הבעש\"ט אטו בעת נעורינו א\"צ לעזרתו ית' ולפי הנ\"ל יש ליישב דכד הוינא זוטרי ודאי כי נער ישראל ואוהבהו, וה' הולך לפניהם וא\"כ עזרתו מצוי', אבל לעת זקנה הרי אמר הנני שולח מלאך, א\"נ ע\"ד אם נזדקנו ד\"ת אצלך כו' ומי איכא זקנה קמי קודשא בריך הוא, וזהו נער הייתי גם זקנתי, ולכן מבקשים אשר הוא ית' ממש אל ישליכנו מלפניו בכבודו ובעצמו ממש וכמו שביקש משה אם אין פניך הולכים, וזהו תתחדש כנשר נעוריכי וזהו חנוך לנער על פי דרכו גם כי יזקין לא יסור ממנה, וע' בתניא בהקדמה לחינוך שהקשה וי\"ל התירוץ דגם כשיזקין יהי' לו בחי' נער ומעלתו שהוא ענין תוקף החסידות בתחילתו גם ע\"ד לאתבא צדיקייא בתיובתא, וזהו ואשא אתכם על כנפי נשרים בחי' תתחדש כנשר כו' הנער בן מאה שנה כו' זקנים עם נערים כו'."]]],[300010588,"סז\n\nתהלים פט, טז: <i>אשרי העם יודעי תרועה ה' באור פניך יהלכון</i>.\n<b>מורנו</b> הבעש\"ט פירש אשרי העם יודעי תרועה, אשרי שבח והודי' להשי\"ת אשר כל עם ישראל יודעי תרועה, תרועת מלחמה עם היצה\"ר ולכן הנה כלם הוי' באור פניך יהלכון<sup data-n=\"1\">174</sup>.",[["1","174","ספר המאמרים תש\"ג ע' 191. ובספר השיחות תש\"ד ע' 10: אשרי העם יודעי תרועה, אשרי שבח והודי' להשי\"ת אשר כל עם ישראל בלי הבדל גאוני תורה, מדרש, עין יעקב אידן אדער תהלים אידן ווייסן תרועת מלחמה מיט דעם נפש הבהמית און האבן א פנימיות געפיל צו די המשכות פון נפש האלקית. וראה אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ד ע' ד בשוה\"ג. וראה גם שיחת יום ב' דראש השנה תשי\"ט (תורת מנחם התוועדויות תשי\"ט ח\"א ע' 14)."]]],[300010589,"סח\n\n<b>כמו</b> שאמר רבינו בשם מורנו הבעש\"ט נ\"ע בפירוש הכתוב אשרי העם יודעי תרועה, דהשבירה דשברים יודעים הכל והכל מגיעים לזה, אבל להשבירה דתרועה צריכים דעת, וע\"י הדעת מגיעים לזה<sup data-n=\"1\">175</sup>.",[["1","175","ספר המאמרים תרצ\"ז ע' 159."]]],[300010590,"סט\n\n<b>פירש</b> מורנו הבעש\"ט נ\"ע דער תכלית העבודה איז לב נשבר, תכלית אופן העבודה איז הצנע לכת, און וויבאַלד אזוי איז דאָס, איז אשרי העם יודעי תרועה, שיודעים איך להריע, ווי צו ברעכן זיך אַז בפנימיות זיינען זיי בלב נשבר און בחיצוניות זיינען זיי שמח וואָס זיי זיינען זוכה צו זיין עבדי השם, און אויף דעם איז ער מבקש הוי', הוי' דלעילא, באור פניך יהלכון, וואו זיי וועלן גיין זאָל זיין באור פניך<sup data-n=\"1\">176</sup>.",[["1","176","ספר המאמרים תש\"ח ס\"ע 284 ואילך. וראה לעיל סימן ג."]]],[300010591,"ע\n\nתהלים ק, א: <i>הריעו לה' כל הארץ</i>.\n<b>הריעו</b> להוי' כל הארץ איז ר\"ת הלכה<sup data-n=\"1\">177</sup>. דער הילוך איז אין אַלע מדריגות הנשמה, חמש מדריגות זיינען אין נשמה ווי זי איז בא פון עצמות א\"ס, יחידה, חי', נשמה, רוח ונפש, וועלכע טיילן זיך אין צוויי דרגות נר\"נ און חי' יחידה. אין נר\"ן ווערט דערהערט דורך השגה, אין חי' יחידה דורך אַ הרגש געפיל<sup data-n=\"2\">178</sup>.",[["1","177","לקוטי תורה להאריז\"ל תהלים ק' ובשער הפסוקים שם. – נתבאר ע\"פ דא\"ח בסידור ע\"פ מזמור לתודה [מד, ג ואילך]; בפירוש המלות מהד\"ב פרק קמא ואילך. ועוד."],["2","178","ספר השיחות תש\"ח ע' 244."]]],[300010592,"עא\n\nתהלים קד, כג: <i>יצא אדם לפעלו ולעבודתו עדי ערב</i>.\n<b>דער</b> מענטש גייט צו זיין טואונג און זיין אַרבעט באַדאַרף ער טאָן ביז אָוונט.\nדער רבי נ\"ע זאָגט בשם הבעש\"ט נ\"ע אַז יעדע נשמה וואָס ג-ט ב\"ה שיקט אַראָפּ אויף דער וועלט האָט אַ שליחות וואָס די נשמה דאַרף אויפטאָהן אויף דער וועלט, וואָס די שליחות מוז די נשמה דורכפירן, ווייל אַזוי איז די גזירה עליונה אַז דאָס איז דער פּועל פון דער נשמה, און דער בעש\"ט נ\"ע האָט געטייטשט דעם פּסוק יצא אדם לפעלו, דער מענטש גייט צו זיין טואונג, דאָס מיינט צו זיין נשמה שליחות וואָס דאָס איז פּעלו וואָס צוליב דעם איז די נשמה געשיקט געוואָרן אויף דער וועלט און יעדער דאַרף וויסן און געדענקען אַז ולעבודתו עדי ערב אַז זיין נשמה שליחות אַרבעט בעדאַרף ער טאָן און מוז דורכפירן עדי ערב ביז עס ווערט ערב, דאָס מיינט אַז מען בעדאַרף דורכפירן די נשמה שליחות איידער עס ווערט שפּעט<sup data-n=\"1\">179</sup>.",[["1","179","ספר המאמרים אידיש ע' 200 (הובא ונתבאר בלקוטי שיחות חי\"ד ע' 176 ואילך). וראה אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ג ס\"ע תלא ואילך (הועתק ב\"היום יום\" א אדר א)."]]],[300010593,"עב\n\nתהלים קו, ב: <i>מי ימלל גבורות הוי' ישמיע כל תהלתו</i>.\n<b>שמעתי</b> בשם הבעל שם טוב ז\"ל ע\"פ מי ימלל גבורות ה' ישמיע כל תהלתו, פי' ימלל ישברם ויבטלם כמו מוללין מלילות<sup data-n=\"1\">180</sup>, והכוונה שיבטל גבורות ה' פי' דינין, ישמיע כל תהלתו היינו שיאמרו תהלים שכולו תהלות ד', ועי\"ז יבטל וישבר הדינין הבאין עליו<sup data-n=\"2\">181</sup>.",[["1","180","ביצה יב, ב."],["2","181","מאמרי אדמו\"ר הזקן כתובים ח\"א ס\"ע צה. וראה אגרות-קודש כ\"ק אדמו\"ר זי\"ע חט\"ו ע' קיא: בספרו היהודי הטוב מגוסטינין, ע' פז, מביא הפתגם שלו על הפסוק מי ימלל גבורות ה' וגו' – אבל באחד מספרי כ\"י תורת חסידות חב\"ד, שכנראה נכתב ע\"י אחד החסידים עוד בחיי רבינו הזקן (בעל התניא והשו\"ע) מובא זה בשם הבעש\"ט ותיקון בגוף הפתגם, שצ\"ל ימלל מלשון מוללין מלילות שפירושו שבירה. ואף ששבעים פנים לתורה, כנראה שבנדון דידן רק כך צ\"ל (ולא כמועתק בס' לשון מילה חתך וקריעה), כיון שהפירוש דמוללין מלילות מיוסד ע\"פ פתגם הזוהר המובא בכ\"מ בחסידות (ראה זח\"א רמט, א. זח\"ב פג, א. ביאורי הזוהר – לאדמו\"ר האמצעי – ויחי שם. פי' התהלים – לאדמו\"ר הצמח צדק – קו, ב [אוה\"ת (יהל אור) ע' תיב]). וראה גם תורת מנחם התוועדויות חי\"ט ע' 236. ח\"כ ע' 66."]]],[300010594,"עג\n\n<b>וכמאמר</b> הבעל שם טוב ע\"פ מי ימלל גבורות הוי' ישמיע כל תהלתו. ופירש הבעש\"ט ימלל מלשון שבירה כמ\"ש<sup data-n=\"1\">182</sup> וקטפת מלילות. ומי ימלל וישבור גבורות הוי', איזה ענין משבר ומבטל את הגבורות והדינים שלמעלה – ישמיע כל תהלתו, כל התהלים<sup data-n=\"2\">183</sup>.",[["1","182","תצא כג, כו."],["2","183","לקוטי שיחות ח\"ד ע' 1310. ושם לפנ\"ז: והנה בדוד מלך ישראל כתיב ולבי חלל בקרבי שאין לו יצה\"ר. וארז\"ל דוד מלך ישראל חי וקיים. מלך ענינו אשר הוא יוציאם והוא יביאם – את העם – בכל הצטרכותם. ומזה מובן אשר מהות המלך ניכר גם בעניני העם.\nההשפעה מה שדוד מלך ישראל משפיע לכל עם ישראל – נתינת כח לקיים תומ\"צ בלי שום פניות מהיצה\"ר, הנהגה עכ\"פ לעת מן העתים כאילו ולבי חלל בקרבי, קיום תומ\"צ לשמה בלי תערובת ענינים זרים.\nובכדי לקבל השפעה זו צריכה להיות התקשרות בדוד המלך. וההתקשרות הוא ע\"י אמירת תהלים, מזמורי דוד מלך ישראל, שעי\"ז נעשים כלי לקבל השפעתו ומעין אופן עבודתו.\nביטולו של ה\"יורד ומסית\" מבטל במילא ה\"עולה ומשטין\".\nכי גדולה מעלת אמירת תהלים שבכחה לבטל את הדינים שלמעלה ולבטל את הגזירות גם אחרי שנחתמו דינם [ההמשך בפנים. ולאח\"ז ממשיך שם:] ופרסם כ\"ק מו\"ח אדמו\"ר והנהיג לומר בכל יום אחרי התפלה שיעור התהלים כפי שנחלק לימי החודש.\nוראה בארוכה קובץ מכתבים בסו\"ס תהלים אהל יוסף יצחק – בענין אמירת תהלים."]]],[300010595,"עד\n\nתהלים קז, כג: <i>יורדי הים באניות עושי מלאכה במים רבים</i>.\n<b>בתיבת</b> אני' יש ב' פירושים, אני' ספינה, אני' מספד. יורדי הים קאי על הנשמה היורדת להתלבש בגוף שהיא בדוגמת הים כמו מי הים מכסים על מה שבתוכם כן הגוף מכסה על הנשמה האלקית שבתוכו, וביורדי הים, היינו בנשמות היורדות יש ב' אופני ירידה, יש ירידה הגם שהיא ירידה בים, בכל זה יש לו ספינה והוא חינוך וסביבה, של בני תורה ושומרי מצוה, אבל ישנה ירידה של תאני' ואני', הנשמה היורדת בגוף של ישראל שאינו בסביבה של בני תורה ושומרי מצוה, אבל ישנם העושי מלאכה במים רבים, והם אלו הנשמות שצריכות לרדת לים, לעשות מלאכה גם במים רבים להציל את אלו הנשמות אשר ירדו בתאני' ואני'<sup data-n=\"1\">184</sup>.",[["1","184","ספר הזכרונות ח\"ב ע' 427. וראה שיחת יו\"ד שבט תשכ\"ה."]]],[300010596,"עה\n\nתהלים קיט, ט: <i>במה יזכה נער את ארחו</i>.\n<b>כה</b> אמר הבעש\"ט – במה יזכה נער, פאַר וועלכער מצוה איז מען זוכה צו האָבען אַ בן זכר טוב, את ארחו, דורך דער מצוה פון הכנסת אורחים בשמחה ובקורת רוח<sup data-n=\"1\">185</sup>.",[["1","185","אגרות-קודש אדמו\"ר מהוריי\"צ חי\"ג ע' שפט. ושם לפנ\"ז: הנני בזה לברכם כי תתקיים בידידי ובזוגתו תחי' ברכת מורנו הבעש\"ט נ\"ע שאמר לאחד מהמקושרים אליו אשר בקשו להתפלל ולעורר רחמים עבורו ועבור זוגתו שיוולד להם בן זכר, ויאמר להם מורנו הבעש\"ט נ\"ע תזהרו בכל כחכם לקיים מצות הכנסת אורחים בשמחה ובקורת רוח והשי\"ת ימלא את משאלות לבבכם בבן זכר כאמור – [ההמשך בפנים:].\nראה גם אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ב ע' רמו. ספר השיחות תרצ\"ז ע' 161. אגרות-קודש כ\"ק אדמו\"ר זי\"ע ח\"ד ע' ל. חי\"ט ע' שלג."]]],[300010597,"עו\n\nתהלים קיט, נט: <i>חשבתי דרכי ואשיבה רגלי אל עדותיך</i>.\n<b>חשבתי</b> דרכי הוא שדוד הי' חושב בדרכיו הגשמיים . . ואשיבה רגלי גו' – אשובה להרגיל (רגלי מלשון הרגל) אל עדותיך<sup data-n=\"1\">186</sup>.",[["1","186","ד\"ה באתי לגני תשל\"א (ספר המאמרים מלוקט ח\"ה ע' קסד. בהוצאה החדשה – ח\"ב ע' שסד). וש\"נ."]]],[300010598,"עז\n\nתהלים קיט, פט: <i>לעולם ה' דברך נצב בשמים</i>.\n<b>לעולם</b> ה' דברך נצב בשמים<sup data-n=\"1\">187</sup> ופי'<sup data-n=\"2\">188</sup> הבעש\"ט ז\"ל<sup data-n=\"3\">189</sup> כי דברך שאמרת יהי רקיע בתוך המים וגו'<sup data-n=\"4\">190</sup> תיבות ואותיות אלו הן נצבות ועומדות לעולם בתוך רקיע השמים ומלובשות בתוך כל הרקיעים לעולם להחיותם כדכתיב<sup data-n=\"5\">191</sup> ודבר אלקינו יקום לעולם ודבריו חיים וקיימים לעד כו' כי אילו היו האותיות מסתלקות כרגע<sup data-n=\"6\">192</sup> ח\"ו וחוזרות למקורן היו כל השמים אין ואפס ממש והיו כלא היו כלל וכמו קודם מאמר יהי רקיע כו' ממש וכן בכל הברואים שבכל העולמות עליונים ותחתונים ואפי' ארץ הלזו הגשמית ובחי' דומם ממש אילו היו מסתלקות ממנה כרגע{192} ח\"ו האותיות מעשרה מאמרות שבהן נבראת הארץ בששת ימי בראשית היתה חוזרת לאין ואפס ממש כמו לפני ששת ימי בראשית ממש<sup data-n=\"7\">193</sup>.",[["1","187","ראה ספר המאמרים תרל\"ו ח\"ב ע' תח ואילך."],["2","188","החידוש בפירוש הבעש\"ט – ראה לקוטי שיחות חכ\"ה ע' 200 ואילך. חכ\"ט ע' 29 ואילך."],["3","189","\"הגם שיש ענין זה במדרש תהלים, וכמש\"נ גם בלקו\"ת בד\"ה כי ביום הזה יכפר, וכוונה מיוחדת בזה, כי ביום שני הי' המאמר יהי רקיע – שהוא הנצב בשמים – וזה יהי' לזכרון עולם, כי ביום שני ח\"י אלול נולד הבעש\"ט\" (\"היום יום\" כו תשרי – מספר השיחות קייץ ה'ש\"ת ע' 170). וראה ספר השיחות תש\"ג ע' 147-146 ובהערה 15 שם. שם ע' 151-150. שיחת שמחת בית השואבה תשי\"ב (תורת מנחם – התוועדויות ח\"ד ע' 55).\nובלקוטי שיחות (חכ\"ה ע' 331 הערה 29. וש\"נ): \"פּי' הבעש\"ט\" . . אף שנאמר כן במדרש תהלים . . כי הבעש\"ט פירש, האָט עס פאַנאַנדערגעשפּרייט, ועשה ופעל שהלימוד במדרש תהלים יהי' יסוד ודרך בעבודת ה' בתומ\"צ דכאו\"א מישראל במעשה בפועל. וראה אגרות-קודש כ\"ק אדמו\"ר זי\"ע ח\"ה ע' קלד."],["4","190","בראשית א, ו."],["5","191","בהערות ותיקונים לתניא: לרגע."],["6","192","ישעי' מ, ח."],["7","193","תניא שער היחוד והאמונה פרק א. וראה אגרת הקודש סימן כה."]]],[300010599,"עח\n\nתהלים קכא, ה: <i>ה' צלך</i>.\n<b>פירוש</b> הבעש\"ט<sup data-n=\"1\">194</sup> עה\"פ ה' צלך . . לויט די ענינים וואס א איד טוט למטה, טוען זיך אויף <i>דוגמתם</i> ענינים למעלה<sup data-n=\"2\">195</sup> – כמשל צל האדם, וואס לפי אופן התנועות פון דעם מענטשן טוט זיך דוגמתם ממש בהצל<sup data-n=\"3\">196</sup>.",[["1","194","קדושת לוי פ' בשלח (לט, ג. מ, סע\"ב). פ' נשא (ע, ג. ושם: הבעש\"ט הי' מוכיח תמיד את העולם בזה הפסוק ה' צלך, דהיינו כמו שהצל עושה מה שהאדם עושה כך הבורא ב\"ה כביכול עושה מה שהאדם עושה). ספר המאמרים תרכ\"ז ע' שכו. וראה אור תורה להרב המגיד פ, ג [הובא בד\"ה דרשו תשל\"א (ספר המאמרים תשל\"א ע' 319)]. לקו\"ת בלק עד, ג. ספר המאמרים תרל\"ג ח\"ב ע' תע."],["2","195","ראה גם תורת הבעש\"ט בפירוש המשנה (אבות פ\"ב מ\"א) \"דע מה למעלה ממך\" – כתר שם טוב סו\"ס קמה (יח, ג). נתבאר בספר המאמרים תרל\"ג ח\"ב ס\"ע תעג ואילך."],["3","196","לקוטי שיחות חי\"ח ע' 167. וראה גם בשם הבעש\"ט – לקוטי שיחות ח\"ב ע' 421. ח\"ט ע' 148 הערה 44. ע' 429. ד\"ה ובחמשה עשר יום תש\"ל (ספר המאמרים תש\"ל ע' 24)."]]],[300010600,"עט\n\nתהלים קכו, ו: <i>הלוך ילך ובכה נושא משך הזרע בא יבא ברינה נושא אלומותיו</i>.\n<b>מורנו</b> הבעש\"ט האָט געטייטשט דעם פּסוק<sup data-n=\"1\">197</sup>, הלוך ילך ובכה, אַז מען גייט מיט אַ מרירות נאָך דעם דאַוונען איז נושא משך הזרע, ווערט אַ זריעה פון דעם עבודת התפלה, ווי איז אָבער אַז בא יבא ברינה, אַז מען פילט זיך בהרחבה נאָך דעם דאַוונען, אַז מען איז צופרידן פון דער אייגענער עבודה אין תפלה, איז ער מער ניט ווי אַ נושא אלומותיו ער טראָגט פּוסטע שטרוי זאַנגען<sup data-n=\"2\">198</sup>.",[["1","197","ראה גם צפנת פענח פ' בא לז, ג [בדפוס ראשון: כח, ד ואילך]."],["2","198","ספר השיחות קייץ ה'ש\"ת ע' 93. ושם לפנ\"ז:\nהחסיד ר' בער מאָסייעוו איז געווען אַ תלמיד פון דעם מיטעלן רבי'נס חסידים ר' שמואל און ר' ברוך טאַמאַרעס. ר' שמואל איז געווען אַ האַרציקער און ר' ברוך איז געווען אַ בעל מוחין. ביי דער ערשטער יחידות וואָס ר' בער מאָסיווער איז אַריינגעגאַנגען צו דעם עלטער זיידן רבי צמח צדק, האָט אים כ\"ק אדמו\"ר געזאָגט:\nדער זיידע האָט געזאָגט: [ההמשך בפנים. ולאח\"ז ממשיך:]\nהאָט החסיד ר' בער מאָסייעוו געזאָגט, אַז מיט דעם האט דער רבי צמח צדק אים איבערגעמאַכט מן הקצה אל הקצה."]]],[300010601,"פ\n\nתהלים קלו, ד: <i>לעושה נפלאות גדולות לבדו כי לעולם חסדו</i>.\n<b>כ\"ק</b> אאמו\"ר נ\"ע פי' בשם הבעש\"ט נ\"ע לעושה נפלאות שהקב\"ה הנה כל מה שהוא עושה הוא נפלאות גדולות לבדו וגודל הפלאתם של הנפלאות הוא רק לבדו יודע זאת.\nכי לעולם חסדו איתא בע\"ח<sup data-n=\"1\">199</sup> דלמ\"ד כלים דזו\"נ דאצי' נעשים נר\"ן לבי\"ע ובהם ועל ידם הוא המשכת חסדו שהוא רב חסד דעתיקא קדישא שהוא חסדו ית' האמיתי, וזהו לעושה נפלאות דכל עשיותיו של הקב\"ה הם נפלאות וגדולתן של הנפלאות ידוע רק לו ית'. וזהו גדולות לבדו, וא' מגדולתם של הנפלאות הוא זה מה שע\"י כ\"י שהם ל' כלים דזו\"נ דאצי' יהי' גילוי חסדו ית' שהוא רב חסד דעתיקא קדישא בעולם<sup data-n=\"2\">200</sup>.",[["1","199","ראה עץ חיים שער מד (שער השמות) פ\"א. תניא קו\"א ד\"ה להבין מ\"ש בפע\"ח (קנו, ב)."],["2","200","ספר המאמרים תש\"ד ע' 49. וראה ד\"ה לעושה נפלאות גדולות תשל\"ד. שיחת ליל ויום שמח\"ת תשל\"ט."]]],[300010602,"פא\n\nתהלים קמד, טו: <i>אשרי העם שככה לו</i>.\n<b>שהככה</b> הוא שלו<sup data-n=\"1\">201</sup>.",[["1","201","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ב ס\"ע קמא ואילך. ושם לפנ\"ז: וידוע הפירוש שאמר הוד כ\"ק רבינו הגדול נ\"ע בשם רבו דרבו הוד כ\"ק מורנו הבעש\"ט נ\"ע [ההמשך בפנים. וממשיך שם:] דאיתא בזוהר ח\"ג (ברע\"מ דקי\"א ע\"ב) קמו מרי מתיבתא ואמרו אשרי העם שככה לו, שככה בגימטריא משה.\nוהנה ככה פירושו הדבר כמו שהוא, אָט אַזיי ויא עס איז, דהדבר כמו שהוא, הוא האמת של הדבר, און דער זיק היהדות דאָס איז דער ככה פון אַ אידין."]]],[300010603,"פב\n\nמשלי ג, יח: <i>עץ חיים היא למחזיקים בה ותומכי' מאושר</i>.\n<b>בשם</b> הבעש\"ט \"עץ חיים היא למחזיקים בה ותומכי' מאושר\" – \"ושומחי' מאושר\"<sup data-n=\"1\">202</sup>, מי ששומח עצמו עם התורה ומשמח את התורה, הוא מאושר – גליקלעך – בבנים ובני בנים עוסקים בתורה<sup data-n=\"2\">203</sup>.",[["1","202","מצד מבטא התי\"ו שבתיבת \"ו<i>ת</i>ומכי'\" (תי\"ו רפה) אפשר לקראה \"ו<i>ש</i>ומחי'\" (בשׂי\"ן שמאלית). – שיחת ליל שמח\"ת תשי\"ט ס\"ב (תורת מנחם התוועדויות תשי\"ט ח\"א ס\"ע 119)."],["2","203","ספר השיחות תרצ\"ט ע' 306. ושם לפנ\"ז: בשמחת תורה תר\"ז האָט דער צמח צדק געזאָגט אַ תורה וואָס ער האָט געהערט פון החסיד ר' פּינחס רייזעס, וואָס ער האָט געהערט פון דעם אַלטן רבי'ן בשם הבעש\"ט [ההמשך בפנים. ומסיים שם:] ואמר אדמו\"ר כ\"ק אדמו\"ר הצ\"צ: זה מאה שנה שהבעש\"ט אמר תורה זו. וגם עתה הוא אומר תורה זו בגן עדן. – תורה זו הובאה ונתבארה בשיחת ליל שמח\"ת תשי\"ט (תורת מנחם שם)."]]],[300010604,"פג\n\nמשלי ד, ב: <i>כי לקח טוב נתתי לכם תורתי אל תעזובו</i>.\n<b>כי</b> לקח טוב נתתי לכם, דאָס איז תורת הנגלה, וואָס פון דעם קען זיין אַז מען זאָל מיינען אַז נתתי \"לכם\", אַז דאָס איז לכם און פאַרגעסן אויפן נותן התורה, מען זוכט היתרים און מען פרעגט קושיות, אָבער אַז תורתי, אַז מען לערנט פּנימיות התורה, גלייבט מען אין השגחה פּרטית, דעמאָלט איז, אל תעזובו, איז מען ניט פאַרלאָזן<sup data-n=\"1\">204</sup>.",[["1","204","ספר השיחות תש\"ב ע' 128. וראה ספר המאמרים תש\"ב ע' 109. ומועתק בזה הסיפור ע\"ד תורה הנ\"ל (ספר השיחות שם):\nדער בעש\"ט איז אַמאָל געוען אין סלוצק. מען האָט אים דאַן איינגעלאַדן צו קומען צו אַ חנוכת הבית פון ביהמ\"ד און די פאַרזאַמלונג איז געווען אין חצר פון ביהמ\"ד. מען האָט דאָרט דעם בעש\"ט אָפּגעגעבן אַ גרויסן כבוד. דער בעש\"ט האָט דאַן געזאָגט תורה זיצנדיק אויף אַ שטיין, וואָס די אידן האָבן אַליין געבראַכט צום בנין פון ביהמ\"ד, וועלכן מען האָט נאָך ניט שוקע געווען אין בנין. האָט דאַן דער בעש\"ט געזאָגט, אַז דער שטיין וואָס אַ איד האָט אים געטראָגן צו בויען אַ ביהמ\"ד איז זייער טייער, ע\"ד שמובא ברחב\"ד (שהש\"ר וקה\"ר בתחלתו) און האָט געזאָגט תורה אויף דעם שטיין און די תורה איז זייער געפעלן די אנשים פּשוטים.\nדי לומדים פון שטאָט האָבן דאַן געפרעגט: וואָס האָט איר אויפגעטאָן אין תורה, מען האָט דאָך פריער אויך געלערנט, עס שטייט דאָך כי לקח טוב נתתי לכם, האָבן מיר דאָך תורה.\nהאָט זיי מורנו בעש\"ט געענטפערט, איך בין ניט געקומען צו מחדש זיין קיין זאַך, נאָר מפרש זיין פּשטי הכתובים, און טאַקע דער זעלבער פּסוק וואָס איר האָט געברענגט, דער פּירוש איז אַזוי [כבפנים]."]]],[300010605,"פג-א\n\nמשלי כב, ט: <i>טוב עין הוא יבורך</i>.\n<b>מאמר</b> הבעש\"ט: טוב עין הוא יבורך – א טוב עין בענטשט דעם הוא. <i>הוא</i> איז עצמות א\"ס הנעלם און דער <i>טוב עין</i> איז דאס מגלה<sup data-n=\"1\">205</sup>.",[["1","205","\"היום יום\" חלק שני ע' יט, ומציין שם ל\"<i>שמח\"ת תש\"ד</i>\". ובספר השיחות תש\"ד ע' 32 הובא זה בשם אאמו\"ר [כ\"ק אדמו\"ר מהורש\"ב נ\"ע])."]]],[300010606,"פד\n\nמשלי כד, כא: <i>ירא את ה' בני ומלך עם שונים אל תתערב</i>.\n<b>ירא</b> את השם, ווער איז א ירא שמים, אז בני ומלך, אז דו ביסט א מלך אויף זיך. ועם שונים – הלכות בלבד – בלי יראת שמים – אל תתערב<sup data-n=\"1\">206</sup>.",[["1","206","ספר השיחות תרצ\"ז ע' 241. ושם ע' 242 נוסחא אחרת: ירא את ה' בני ומלך ועם שונים אל תתערב. ופי' הבעש\"ט, ירא את ה' – ווער הייסט אַ יר\"ש, בני ומלך – דער וואָס איז אויף זיך אַ בעה\"ב. ועם שונים – דעם וואָס איז מער ניט נאָר תורה לערנען אַליין – אל תתערב."]]],[300010607,"פה\n\nאיוב ח, ז: <i>והי' ראשיתך מצער ואחריתך ישגה מאד</i>.\n<b>מורנו</b> הבעש\"ט נ\"ע זאָגט אַז דער ראשיתך מצער איז אַ געוויסער יסוד מוסד אויף דעם אחריתך ישגא מאד<sup data-n=\"1\">207</sup>.",[["1","207","ספר השיחות קייץ ה'ש\"ת ע' 21."]]],[300010608,"פו\n\n<b>סדר</b> העבודה צריך להיות ראשיתך מצער כו' בסדר והדרגה דוקא, מן הקל אל החמור, כלומר לבלי ללכת בגדולות ונפלאות כי אם במה שבערך, ולאט לאט עולה בעילוי אחר עילוי, מדרגא לדרגא<sup data-n=\"1\">208</sup>.",[["1","208","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ב ע' לא. וראה שם ח\"ז ע' קנח. ע' רנה. ע' שפא. חי\"ג ע' רנב. חי\"ד ע' רסג. ע' שכה."]]],[300010609,"פז\n\nאיכה ג, כא: <i>זאת אשיב אל לבי על כן אוחיל</i>.\n<b>פי'</b> הבעל שם טוב<sup data-n=\"1\">209</sup> עה\"פ <i>זאת</i> אשיב אל לבי על כן אוחיל, זאת – השכינה<sup data-n=\"2\">210</sup>.",[["1","209","צפע\"נ (לבעל המחבר תולדות יעקב יוסף) צב, ג [בדפוס ראשון: עג, ד]."],["2","210","ד\"ה איכה ה'תשל\"א ס\"ה (ספר המאמרים מלוקט ח\"א ע' קכג. בהוצאה החדשה – ח\"ד ע' קסד)."]]],[300010610,"פח\n\nאיכה ה, א: <i>זכור ה' מה הי' לנו הביטה וראה את חרפתנו</i>.\n<b>צווישן</b> די תורות וואָס דער אַלטער רבי, דער בעל התניא והשלחן ערוך, האָט געבראַכט קומענדיק דעם ערשטן מאָל פון מעזריטש זיינען געווען צוויי פאַרשידנאַרטיגע תורה אויסטייטשונגען אויף דעם פסוק זכור ה' מה הי' לנו הביטה וראה את חרפתנו, וואָס מורנו הבעש\"ט נ\"ע האָט אָט די צוויי פאַרשידנאַרטיגע תורות אויף איינעם און דעם זעלבן פּסוק זכור ה' וגו' געזאָגט אויף צוויי פאַרשידנאַרטיגע מסיבות אין באַזונדערע צייטן מיט איין און דער זעלבער הקדמה. אין דער אַלגעמיינער הקדמה האָט זיך דער בעש\"ט נ\"ע אָפּגעשטעלט אויף דער הייליגקייט פון דער געבורט פון אַ אידישן קערפּער, אָן אונטערשייד צי אַ זכר אָדער אַ נקבה. דער בעש\"ט האָט גאָר ברייט אַרומגערעדט און קלאָר דייטליך ערקלערט די הייליגע ג-טליכע ליבשאַפט פון ג-ט ב\"ה צו אידן, די ליבשאַפט פון ג-ט ב\"ה צו די אידן איז ניט נאָר צו דער אידישער נשמה נאָר אויך דעם אידישן קערפּער, און די ג-טליכע ליבשאַפט איז צו אַלע געבאָרענע אידן אָן אונטערשייד, פון דעם גאון הגאונים ביז דעם פּשוט שבפּשוטים. דער גאון הגאונים האָט ג-ט ב\"ה ניט מער ליב ווי דעם פּשוט שבפּשוטים, און דעם אידישן פּשוט שבפּשוטים האָט ג-ט ב\"ה ניט ווייניגער ליב ח\"ו ווי דעם גאון הגאונים. אין אַ ברייטערן שמועס ערקלערט דער בעש\"ט זיין באַהויפּטונג אַז די ג-טליכע ליבשאַפט איז צום עצם מהות איד און אידישקייט, גאון און פּשוט דאָס זיינען צוויי נעמען פון טיטול באַגרייפונג, קענער און ניט קענער. קענער און ניט קענער זיינען נאָר באַגריפן וועלכע זיינען שייך צו כחות הגלוים אָבער אין עצם מהות איד און אידישקייט זיינען אַלע גלייך, ווייל אַלע אידן זיינען פון שם מ\"ה דאצילות, ווי עס שטייט אין דעם מאמר פון פתח אליהו אַז שם מ\"ה איהו אורח אצילות, דער בעש\"ט ערקלערט מיט פעסטע באַווייזן פון טהרת המשפּחה, מילה און פּקוח נפשות אַז אַלע אידן זיינען גלייך באַליבט ביי ג-ט ב\"ה. נאָך דער הקדמה האָט דער בעש\"ט זייענדיג אין אַ מסיבה פון גרויסע גאונים וועלכע האָבן זיך שטאַרק מפלפּל געווען אין זאָגן חידושי תורה, און דער בעש\"ט האָט געזען אַז די גאונים האָבן זיך אינערליך זייער איבערגענומען ביי זיך אַליין, מיט אַ שטאַרקער צופרידנקייט פון זייערע חדושי תורה, אין יענער מסיבה האָט דער בעש\"ט געזאָגט די תורה זכור ה' מה הי' לנו, געדענק ג-ט וואָס עס איז געוואָרן פון אונזער מ\"ה שבנשמה, הביטה וראה את חרפּתנו, קוק זיך צו און מאַך אונז זעהענדיג אונזער אייגענע שאַנדע. ביי אַ צווייטער געלעגנהייט אין אַ ישוב פון פּראָסטע אידן וועלכע האָבן געהאַט מסירת נפש אויף פּדיון שבוים מצד אהבת ישראל האָט דער בעש\"ט געזאָגט זיינע תלמידים זכור ה' מה הי' לנו, געדענק ג-ט וואָס איז געוואָרן דורך זייער מ\"ה שבנשמה, הביטה וגו' קוק זיך צו ווי זיי זיינען מחרף את נפשם צוליב אהבת ישראל<sup data-n=\"1\">211</sup>.",[["1","211","ספר המאמרים אידיש ע' 212."]]],[300010611,"פט\n\nמגלת אסתר.\n<b>אין</b> דער תורה וואָס דער בעש\"ט האָט געזאָגט יענעם פּורים – תק\"ה – האָט ער גערעדט וועגן דעם וואָס אין דער מגילה ווערן די אידן אָנגערופן מיטן נאָמען יהודים און זעקס מאָל אין דער מגילה שטייט יהודים מיט צוויי יודי\"ן. אין די תורה ווערן אידן אָנגערופן בני ישראל און אין די מגילה – יהודים. עס איז ידוע אַז דער נאָמען \"יהודים\" איז צוליב דעם ענין מס\"נ וואָס איז פאַראַן ביי אידן, און דאָס וואָס זיי ווערן אָנגערופן \"בני ישראל\", אַ בן פון יש ששים רבוא אותיות לתורה<sup data-n=\"1\">212</sup>, דאָס גיט זיי אַ כח אויף מס\"נ. די צוויי יודי\"ן וואָס איז פאַראַן אין נאָמען יהודיים, דאָס באַווייזט אויף די עשר כחות פון נפש האלקית און עשר כחות פון נפש הטבעית<sup data-n=\"2\">213</sup>.",[["1","212","ראה מגלה עמוקות אופן קפו."],["2","213","ספר השיחות תש\"ה ע' 71. ושם לפנ\"ז:\nאָט דער סיפּור האָט דערציילט הר' ישכר בער קאַבילניקער, וועלכער איז געווען באותו מעמד ביים בעש\"ט, צו החסיד ר' משה ווילענקער און הר\"מ האָט דאָס איבערדערציילט צו דודי זקני הרב\"ש. ווי עס איז ידוע, אַז הוד כ\"ק אאזמו\"ר הרה\"ק צ\"צ פלעגט רופן רב\"ש'ן: מיין בעל השמועה, ביי רב\"ש'ן פלעגט מען פרעגן מכח ענינים צו הנהגה און סיפּורים. [ההמשך בפנים. ולאח\"ז ממשיך:]\nנאָר אין דעם ענין פון מסירת נפש אויף תורה און עבודה האָט זיך יעדערער זיין עבודה אויף מס\"נ, ווי עס איז מבואר אין דעם ענין פון עבודה זרה, עבודה שהיא זרה לכם, ווי זי איז זרה צו יעדן לפי אופנו.\nשנת תק\"ה איז געווען אַן איבער-יאָר, האָט דער בעש\"ט דאַן געזאָגט: איצטער איז די וועלט אין עיבור.\nנאָך פּורים האָט דער בעש\"ט גערופן הר' ישכר בער קאָבילניקער, וועלכער איז געווען דעם בעש\"ט'ס אַ איד, און נאָך איינעם אַ מלמד און האָט זיי געזאָגט, אַז זיי זאָלן גיין אין די הוטע פון הר' ברוך אין ליאָזנא און זאָלן בענטשן זיין ווייב רבקה'ן, וועלכע איז דאַן געווען מעוברת מיט הוד כ\"ק רבינו הזקן אין פערטן חודש."]]],[300010612,"צ\n\nאסתר ט, כג: <i>וקבל היהודים את אשר החלו לעשות</i>.\n<b>דער</b> רבי נ\"ע זאָגט בשם הבעש\"ט נ\"ע וקבל היהודים מיט מסירות-נפש'דיגן קבלת-עול האָבן זיי מתקן געווען את אשר החלו, אָט דאָס וואָס זיי האָבן וואָכעדיג געמאַכט מצד זייער וואָכעדיגקייט וואָס קומט פון חולאת רוחני<sup data-n=\"1\">214</sup>.",[["1","214","ספר המאמרים אידיש ע' 104, ושם מבאר:\nדאָס זיינען צוויי טייטשען אין דעם וואָרט החלו. איין טייטש איז החלו מלשון חולין, וואכעדיג, דער מיין פון דעם וואָרט וואָכעדיג איז אין צוויי אופנים, א) וואָכעדיג געוואָרען, ב) וואָכעדיג געמאַכט, דער צווייטער טייטש פון החלו איז מלשון חולי, קראַנקשאַפט, די אידען בזמן מרדכי זיינען קראַנק געוואָרען אויף דער מחלה רוחנית פון נהי' ככל הגוים, וואָס דער אויסגאַנג פון דער מחלה איז אַז מען ווערט וואָכעדיג, דאָס מיינט מען ווערט אַ מגושם מיט די אַלע גראָבע גשמיות'דיגע אייגענשאַפטען, אַז דער גאַנצער מהות פון דעם מענשען איז נאָר גשמיות הון ורכוש, גוט עסען, גוט טרינקען, שיין קליידען זיך, פאַרברענגען די צייט אין כל-ערליי פאַרגעניגענס גשמיים און אַלץ זיך נאָכגעבן אָהן קיינע גרעניצען פון די איסורי התורה, און מען איז אַזוי קראַנק אַז מען גייט אויך אַריבער די גרעניצען פון אנושיות אַז נמשלו כבהמות נדמו, מען ווערט אַזוי וואָכעדיג אַז מען וואַרפט פון זיך אַראָפּ אַפילו בושה, מען שעמט זיך ניט, אָט אַזוי ווי בעלי חיים וועלכע טוען אַלע זייערע קערפּערליכע באַדערפענישען ברבים אָהן בושה, אָט אַזוי זיינען די מגושמ'דיגע בעלי תאוות וואָס מיט זייערע אויפפירונגען ווערען זיי נאָך וואָכעדיגער פון די נידעריגסטע גרעבסטע פאַרדאָרבענע בעלי חיים. מיר זעהען במוחש אין די טבעי הבעלי חיים אַז נאָכדעם ווי זיי טוען אָפּ אַ קערפּערליכען תאוה פאַרלאַנג, אַפילו די חיות הטורפות, באַפאַלט זיי נאָכדעם אַ געוויסער אומעט און מאַנכעס מאָל זאָגאַר אַ מין אַראָפּגעפאַלענקייט און נידערגעשלאָגענקייט. חוקרים זאָגען אַז דאָס איז אַ בעל-חיים'דיגער מוסר כליות, דאָס מיינט אַז ווען אַ בעל חי ערפילט שוין זיין קערפּערליכע טבעיות'דיגע באַדערפעניש ווערט ביי אים עפּעס אַ העכערער געפיהל וואָס דאָס שאַפט ביי אים אַ אומעט פון אַ נידערלאַגע, אָבער ביי די מגושמ'דיגע בעלי תאות איז לא זו בלבד וואָס לא יתבוששו, זיי האָבען ניט קיין בושה, איז נאָך כי הלל רשע על תאות נפשו, ער באַרימט זיך נאָך מיט זיינע תאוות און ער מאַכט וואָכעדיג תורה ומצות, דער בעל-תאוה פאַרשוועכט אַלע אידישע הייליגקייטען וואָס מיט דעם מאַכט ער וואָכעדיג די מצות פון שבת, טהרה, תפילין וכו', און דאָס איז דער מיין פון דעם בעש\"ט'ס טייטש אין דעם וואָרט החלו, די אידען אין יענער צייט, ווי אַ טייל אידען אין דער איצטיגער צייט, זיינען קראַנק געווען מיט דער מחלה נהי' ככל הגוים און זיינען געוואָרען אַזוי וואָכעדיג מגושם אַז זיי האָבען וואָכעדיג געמאַכט שבת, טהרת-המשפּחה וכו', האָט השי\"ת געטאָן די תוכחה עצה, ווי ער ית' האָט מתרה געווען אַז די אידען פון אַלע דורות זאָלען וויסען אַז ווי זיי וועלען זיך פירען מיט תורה ומצות אַזוי וועט ער ית' זיך פירען מיט די אידען און וועט געבען די מאַכט אַ געוויסען המן'ען וועלכער וועט ברענגען די אידען צו תשובה, און דאָס מיינט וקבל היהודים, דער תשובה געשריי מיט אַ מסירת-נפש ווען המן האָט באַקומען די דערלויבעניש פון אחשורוש'ן להשמיד להרוג ולאבד את כל היהודים, האָבען די אידען דערפילט אַז דאָס איז די תוכחה עצה האָבן זיי גלייך תשובה געטאָן, חרטה געהאַט אויף די מעשים רעים און גענומען אויף זיך צו פירען לויט די תורה ומצות וועגען, אָט אַזוי ווי זיי האָבען אויף זיך מקבל געווען בשעת מתן תורה, און דאָס איז וקבל היהודים, דער קבלת-עול פון די אידען און די תשובה תנועה צו פאַרריכטען דאָס וואָס זיי האָבען פריער וואָכעדיג געמאַכט, אָט דאָס האָט געבראַכט די גרויסע ישועה אַז ונהפוך הוא אַז דער להשמיד להרוג ולאבד ווערט אויסגעפירט אויף המן'ען און אַלע שונאי ישראל."]]],[300010613,"צא\n\n<b>אין</b> זמן פון בעש\"ט איז אַמאָל געוועזן אַ שלעכטער יאָר, האָט דער בעש\"ט געזאָגט גזירה עבידא דבטל און האָט דאַן געשמועסט מיט זיין חבריא קדישא, וויפיל זמן גיט מען אויף תשובה, מיר געפינען ארבעים יום באַ נינוה, נאָר דאָס איז באַ אינו יהודי וואָס אפי' נאָך די תשובה איז ער אויך אַ גוי אַ בן נח. ביי אידן געפינען מיר די צייט אויף תשובה – אַ יאָר אַזוי ווי בימי מרדכי ואסתר.\nאַ נאַר לייגט אָפּ אויף מאָרגן און אַ קלוגער טוט גלייך<sup data-n=\"1\">215</sup>.",[["1","215","ספר השיחות תש\"ב ע' 117."]]],[300010614,"צב\n\nברכות ו, א: <i>תפילין דמארי עלמא מה כתיב בהו . . ומי כעמך ישראל גוי אחד בארץ</i>.\n<b>אַמאָל</b> האָט מורנו הבעש\"ט געזאָגט, אַז אידן זיינען די תפילין דמארי עלמא, כמאמר (ברכות ו, א) תפילין דמארי עלמא מה כתיב בהו<sup data-n=\"1\">216</sup> ומי כעמך ישראל גוי אחד בארץ, אידן זיינען ממשיך דעם אחד ה' בארץ.\nאין תפילין זיינען פאַראַן צוויי תפילין: תפלה של ראש און תפלה של יד. אידן וואָס זיינען די תפילין דמארי עלמא זיינען פאַראַן תפילין של ראש אידן בעלי מוחין און בעלי תורה, און תפילין של יד אידן בעלי מדות טובות.\nדי ברכה פון הנחת תפילין איז אשר קדשנו במצותיו וצונו וגו'. השי\"ת האָט אונז אידן געהייליקט מיט די מצות. די ברכה אויף תפילין מאַכט מען אויף ביידע תפילין, אויפן של ראש און אויפן של יד, און לייגן באַדאַרף מען ביידע תפילין, אָבער פריער לייגט מען תפלה של יד און נאָכדעם תפלה של ראש.\nאין הנחת תפילין שלמעלה מיינט דער של יד די פעולת עבודה פון אנשים פּשוטים, און דער של ראש מיינט די פעולת עבודה פון בעלי תורה. הנחת תפילין שלמעלה איז די עבודה בקבלת עול פון אנשים פּשוטים העכער פון דער עבודה פון די בעלי מוחין אין ידיעה והשגת התורה<sup data-n=\"2\">217</sup>.",[["1","216","דברי הימים-א ו, לג."],["2","217","ספר השיחות קייץ ה'ש\"ת ע' 133. וראה לקוטי שיחות ח\"ב ע' 299.\nובלקוטי שיחות ח\"ט ע' 348 הערה 7: ואף שהבעש\"ט הי' משבח ומפליא דוקא עבודת אנשים פּשוטים, וכידוע תורת הבעש\"ט . . בענין מה שתפלין של יד קודם לתש\"ר, שזהו לפי שהעבודה דקבלת עול של אנשים הפּשוטים היא נעלית יותר מהעבודה של בעלי מוחין בידיעת והשגת התורה –\nהרי מזה עצמו שביאר מעלת אנשים הפּשוטים בזה שהם תפלין של יד, מובן שגם מעלתם של אנשים הפּשוטים – שייכת וקשורה בענין <i>התורה</i> שבהם, שהרי תפלין הו\"ע המוחין (אלא שתש\"ר הוא מוחין דז\"א ותש\"י הוא מוחין דמל' – כדאיתא בכתהאריז\"ל ע\"ד תפלין. ו\"תש\"י הם תש\"ר דרחל\" (סי' האריז\"ל)), <i>תורה</i>, וכידוע (ראה בארוכה ד\"ה איתא במדרש תהלים תרנ\"ג – נדפס בספר המאמרים תש\"ח ע' 271. סה\"מ תרנ\"ג ע' רעט ואילך) בביאור מרז\"ל (מדרש תהלים עה\"פ (א, ב) כי אם בתורת ה' חפצו) קיימו מצות תפלין ומעלה אני עליכם כאילו אתם יגעים בתורה יומם ולילה."]]],[300010615,"צג\n\nברכות ח, א: <i>מיום שחרב בית המקדש אין לו להקב\"ה בעולמו אלא ד' אמות של הלכה בלבד</i>.\n<b>דער</b> אַלטער רבי האָט אַמאָל געזאָגט בשם מורנו הבעל שם טוב אויף דעם מאמר חז\"ל, משחרב בית המקדש אין לו להקב\"ה בעולמו אלא ד' אמות של הלכה – די ד' אמות וואָס מאַכן אים פאַר אַ מהלך<sup data-n=\"1\">218</sup>.",[["1","218","ספר השיחות תש\"ב ע' 108, ושם:\nשפּעטער האָט זיך גערעדט אַ ביאור אויף דעם און דער אַלטער רבי האָט דאַן גערעדט דעם הפרש פון די ענינים וואָס איז געווען אין ביהמ\"ק און וואָס מען האָט געזען ביים בעש\"ט.\nדי מעלה פון בעש\"ט לגבי די ענינים וואָס איז געווען אין ביהמ\"ק: אין ביהמ\"ק, זאָגן די חז\"ל, שמשם היו שואבים רוח הקודש, וואָס דער פּירוש פון רוה\"ק, איז רוח טהרה לטהר את הטהורים, איז ווען מ'איז געקומען אַהיים פון ביהמ\"ק האָט מען דאָס ניט געקענט איבערגעבן צו אַנדערע.\nביים בעש\"ט האָט מען שואב געווען רוה\"ק, דאָ איז דער פּירוש רוח תשובה, זייענדיק ביים בעש\"ט איז מען נתעורר געוואָרן לתשובה, און קומענדיק אַ היים איז צוקוקנדיק זיך צו זיין הנהגה האָט עס געמאַכט בעלי תשובה.\nאון דער אַלטער רבי האָט מסיים געווען אַז דעם כח האָט דער בעש\"ט איבערגעגעבן לכל ההולכים בדרכיו, אַז זייענדיק ביי אַ טיש אָדער אין די ד' אמות פון תלמידי תלמידיו נעמט מען תשובה."]]],[300010616,"צד\n\nשבת י, א: <i>חיי עולם . . חיי שעה</i>.\n<b>. . . האָט</b> דער רבי געזאָגט אַ תורה, אין דער תורה איז געבראַכט געוואָרן דער מאמר הגמרא אַז לימוד התורה ווערט אָנגערופן חיי עולם, און די עבודה פון תפלה ווערט אָנגערופן חיי שעה, האָט דער בעש\"ט געטייטשט, לימוד התורה איז חיי עולם, דאָס איז אַ הוראה – לערנונג – ווי דער מענטש באַדאַרף זיך פירן אין חיי עולם – אין דעם וועלט לעבן – אָבער תפלה איז חיי שעה, שעה הייסט קערן זיך<sup data-n=\"1\">219</sup>, די עבודה פון תפלה ווערט אָנגערופן חיי שעה דאָס לערנט דעם מענטשן ווי מ'באַדאַרף זיך קערן און בעטן ביים אויבערשטן ברוך הוא<sup data-n=\"2\">220</sup>.",[["1","219","ראה גם ספר המאמרים תרל\"ו ח\"ב ע' שמז. תרנ\"ד ע' שכט. ובכ\"מ."],["2","220","אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ג ע' קצא. וראה גם ספר השיחות תרצ\"ו ע' 122. וממשיך באגרות-קודש שם:\nאַז ר' מרדכי האָט דערהערט די תורה וואָס דער בעש\"ט האָט געזאָגט וועגען תורה און תפלה און דער אונטערשייד וואָס צווישען זיי, און ער – ר' מרדכי – איז דאָך געווען דער גרויסער למדן אין נגלה און האָט געהאַט די גרויסע ידיעה אין קבלה, האָט ער דאָך דערהערט די אמת'קייט פון דעם וואָרט, האָט די תורה וואָס דער בעש\"ט האָט געזאָגט מכח חיי עולם און חיי שעה באַ אים – ר' מרדכי'ן – געמאַכט אַ גאַנצע איבערקערעניש, און האָט אָנגעהויבן האָרעווען אויף די עבודה פון תפלה.\nבביאור מאחז\"ל מניחין חיי עולם ועוסקים בחיי שעה – ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' פז ואילך. שערי תשובה לאדמו\"ר האמצעי ח\"ב כו, א ואילך. ספר המאמרים תרכ\"ז ע' שסג ואילך. תרכ\"ט ע' רמד. ספר המאמרים קונטרסים ח\"א קח, א ואילך."]]],[300010617,"צה\n\nשבת סט, ב: <i>הי' מהלך במדבר ואינו יודע אימתי שבת כו'</i>.\n<b>ר'</b> מרדכי . . . האָט געהערט פון דעם בעש\"ט – אין די ערשטע צייטן וואָס ער איז געקומען צו דעם בעש\"ט – אויף דער גמרא שבת (ס\"ט ע\"ב) אויף דעם מאמר:\nאמר רב הונא הי' מהלך במדבר ואינו יודע אימתי שבת, מונה ששת ימים (מיום ששם אל לבו שכחתו, ומשמר השביעי – רש\"י) ומשמר יום אחד, חייא בר רב אומר משמר יום אחד ומונה ששה, במאי קמיפליגי מר – רב הונא – סבר כברייתו של עולם (ימי חול נמנו תחלה – רש\"י) ומר – חייא בר רב – סבר כאדם הראשון (שנברא בע\"ש, ויום ראשון למנינו שבת הי' – רש\"י). עס זיינען פאַראַן – זאָגט דער בעש\"ט צווייערליי עבודות, די עבודה פון ששת ימי החול, און די עבודה פון שבת, אין יעדער וואָך וואָס דאָס איז זעקס טעג, זעקס ספירות און מדות, חסד, גבורה, תפארת, נצח, הוד, יסוד, מוז זיין איין טאָג שבת וואָס דאָס איז די ספירה און מדה מלכות, אין דעם – אין דער עבודה פון ששת ימי החול און יום השבת – איז אויך פאַראַן צווייערליי סדרים, צי די זעקס טעג אַרבעט זיינען פריער און דער זיבעטער טאָג איז שבת דער שכר פון די ימי עבודה, צי פריער איז דער שבת און פון דעם שבת קומט די שפע אין די זעקס טעג, די עבודה פון ששת ימי החול איז תורה, און די עבודה פון שבת איז תפלה, תורה ווערט אָנגערופן מדבר, אמר רב הונא, הי' מהלך במדבר, איינער איז אַריינגעטאָן אין תורה, ואינו יודע אימתי שבת, און ווייסט ניט פון דער עבודה פון תפלה, איז די עצה צו דעם מונה ששה ימים, באַדאַרף ער האָרעווען מיט זיינע ששה מדות אויף צו פאַרשטיין און דערמאָנען זיך צוליב וואָס איז ער באַשאַפן געוואָרן, אַז דער עיקר איז צו דערקענען דעם גדלות ה' און דאָס איז נאָר אין דער עבודה פון תפלה, און דאָס זאָגט רש\"י מיום ששם לבו שכחתו, און נאָך די ששת ימים איז משמר יום א' וואָס דאָס איז דער יום השביעי די עבודה פון תפלה בקבלת עול מלכות שמים וואָס דערפאַר איז דאָס מלוכה, חייא בר רב, דער וואָס האָט אַ חיות אין תורה, דאָס הייסט דער וואָס לערנט תורה לשמה באַ דעם איז דער סדר אַז משמר יום אחד ומונה ששה ימים, באַ אים איז די עבודה פון תפלה גיט חיות אין דער עבודה פון תורה, בריתו של עולם איז דאָך בשביל עבודת הבירורים איז די עבודה פון תורה פריער, און דער שכר איז עבודת שבת, די עבודה פון תפלה, אדה\"ר יציר כפיו של הקב\"ה<sup data-n=\"1\">221</sup>, דאָס איז די עבודה פון שבת וואָס דאָס איז תפלה פריער און עס גיט אַ חיות אין תורה<sup data-n=\"2\">222</sup>.",[["1","221","ראה ב\"ר פכ\"ד, ה. קה\"ר פ\"ג, יא (ב)."],["2","222","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' קצא ואילך. וראה גם ספר השיחות תרצ\"ו ע' 122. וממשיך באגרות-קודש שם:\nאָט די תורה איז געווען איינע פון די ערשטע תורות וואָס ר' מרדכי האָט געהערט פון בעש\"ט און עס האָט אויף אים געמאַכט דעם גיהעריקן רושם אַז ער האָט זיך אָנגעהויבן עוסק זיין בעבודת התפלה, די תורה איז ר' מרדכי'ן געווען קלאָהר אותיות צו צייהלען, און פלעגט זי חזר'ן מיט דער זעלבער שטימע ווי ער האָט געהערט פון בעש\"ט, און נאָך יעדער מאָהל איבער'חזר'ן די תורה פלעגט ער נתעורר ווערען מיט אַ חשק ורצון אין דער עבודה פון תפלה און אַזוי איז געווען דעם מאָהל אויך, אַז ר' מרדכי איז געקומען פון דער טייכל וואו ער האָט זיך טובל געווען, האָט ער זיך גענומען מכין זיין צום דאַוונען און ער האָט אַ פּאָר מאָהל איבערגע'חזר'ט דעם רבינ'ס תורה האָט זיך גוט פאַרטיפט, און געשטעלט דאַוונען.\nוראה לקו\"ת ברכה צו, ב בפירוש מאמר אבא בנימין על תפלתי שתהא סמוכה למטתי."]]],[300010618,"צו\n\nשבת קיח, ב: <i>אבוך במאי זהיר טפי</i>.\n<b>והנה</b> קבלה לאבותינו מרבינו הגדול אשר קבל מרבו ורבו מרבו דפי' זהיר ל' זוהר ואור<sup data-n=\"1\">223</sup>, והכוונה אבוך במה הוי זהיר טפי באיזה מצוה האיר לו האור האלקי יותר<sup data-n=\"2\">224</sup>, אין וואָס פאַר אַ מצוה האָט אים געלייכט מער דער אור אלקי<sup data-n=\"3\">225</sup>.",[["1","223","ראה צוואת הריב\"ש בתחילתו: פי' זהיר מלשון והמשכילים יזהירו."],["2","224","ראה גם בשם אדמו\"ר האמצעי – אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' קכט ואילך."],["3","225","ספר המאמרים תרפ\"ח ע' קנד ואילך. תש\"ח ע' 240. מועתק בזה הערת כ\"ק אדמו\"ר זי\"ע שם:\nלכאורה צ\"ע ממ\"ש (בשער הגלגולים הקדמה טז ובספר הגלגולים פ\"ד) דמה שמצינו כמה מחז\"ל שהיו זהירים במצוה פרטית ביחוד הוא מפני שאותה מצוה היתה חסירה ממנו, כולה או פרט מפרטי', בגלגול הקודם עיי\"ש. (עייג\"כ בקונטרס העבודה ספ\"ו עד\"ז) ודלא כמ\"ש בפנים. – אך משנ\"ת כאן הוא עפמ\"ש (בע\"ח שער ק\"נ פ\"ה ובהקדמת הרח\"ו לשער ההקדמות) דגם בנשמות חדשות י\"ל אבוך במאי הוי זהיר טפי, והמצוה היתה לפי מקום תליית נשמתו בנשמת אדה\"ר, וא\"כ מוכרח דאין בזה סתירה ושני האופנים ישנם. – ואין להקשות דהא רוב הנשמות הם מהבאים כבר בגלגול, ובפנים כותב דכל אחד צ\"ל זהיר כו' וזה נותן חיות בכל המצות, שזהו כפירוש כתהאריז\"ל בנשמות חדשות. וקושיא מעיקרא ליתא, כי ענין זה ישנו בכל הנשמות, גם הישנות, כיון שזה בא משינוי מקום תלייתם בנשמת אדה\"ר כנ\"ל. אלא שבנשמות שהיו כבר בעולם נתוסף גם ענין קיום המצוה שהיתה חסרה אצלו. וק\"ל. – וע\"פ כהנ\"ל יש לך אדם שצ\"ל זהיר טפי בשתי מצות, אחת כפי מקום תליית נשמתו בנשמת אדה\"ר, ואחת מה שהחסיר מקודם. ובלאה\"כ צ\"ל כן כפי פי' הא' אם החסיר ב' או יותר מצות. ואכ\"מ."]]],[300010619,"צז\n\nפסחים נ, א: <i>עולם הפוך ראיתי עליונים למטה ותחתונים למעלה</i>.\n<b>מורנו</b> הבעש\"ט האָט אויפגעטאָן אַז די אויג נאַרט. דאָס וואָס די גמרא (פסחים נ, א) זאָגט עולם הפוך ראיתי עליונים למטה ותחתונים למעלה, קען מען דאָס אויך זעהן בזה העולם, אַז דער עליון איז קיין עליון ניט און דער תחתון איז קיין תחתון ניט<sup data-n=\"1\">226</sup>.",[["1","226","שיחת פורים תש\"ד – ספר המאמרים ה'שי\"ת ס\"ע 141 ואילך. ספר השיחות תש\"ד ע' 70."]]],[300010620,"צח\n\nראש השנה ח, ב: <i>איזהו חג שהחדש מתכסה בו</i>.\n<b>רבינו</b> בשם מורנו הבעש\"ט נ\"ע פי' המאמר איזה חג שהחדש מתכסה בו שהחידוש מתכסה בו, והוא חגינו לשון רבים חג להוי' וחג לישראל<sup data-n=\"1\">227</sup>.",[["1","227","ספר המאמרים תש\"א ע' 1, וממשיך שם: ומפירוש רבינו הבעש\"ט וביאור רבינו מובן דלהיות שהחידוש הוא מכוסה הנה לא זו בלבד שהוא חג אלא עוד זאת שהוא חגנו לשון רבים."]]],[300010621,"צט\n\nיומא עב, ב: <i>זכה נעשית לו סם חיים כו'</i>.\n<b>אמרו</b> חז\"ל זכה נעשית לו סם חיים, לא זכה נעשית לו סם מיתה. והיינו דאמר רבא באומן לה (כשהוא מאמין בה) סמא דחיי, בלא אומן לה (שאינו מאמין בה) סמא דמותא. והנה מה ענינם של זכות ושל אמונה בענין לימוד התורה, הלא התורה היא חכמה וכל חכמה ומדע ניקנית ביגיעת המוח, ועוד זאת הלא אמונה היא בדבר שלמעלה מן השכל ותורה שהיא חכמה אין נופל בה ענין האמונה. והנה בגמרא שבת (דפ\"ח ע\"ב) אמר רבא למיימינים בה סמא דחיי למשמאילים בה סמא דמותא ופירש\"י למיימינים עסוקים בכל כוחם וטרודים לדעת סודה. הלומד תורה צריך לדעת באמונה פשוטה כי בכל דיבור ודיבור של תורה יש סוד פנימי, וצריכים לייגע את המוח ולהטריד את השכל לדעת את הסוד פנימי שבה, ולימוד כזה פועל טוהר וזכות בהלומד את התורה. וזהו זכה אם הלומד תורה נעשה זך על ידי הלימוד אז הנה אם יוסיף ללמוד באופן כזה נעשית לו סם חיים, ואם הלומד תורה לא נעשה זך ע\"י לימוד התורה אלא אדרבא נעשה עב וגס אז נעשית לו סמא דמותא<sup data-n=\"1\">228</sup>.",[["1","228","ספר הזכרונות חלק א ע' 345."]]],[300010622,"ק\n\nמגילה יז, א: <i>הקורא את המגילה למפרע לא יצא</i>.\n<b>ס'איז</b> ידוע דער פירוש פון בעל-שם-טוב<sup data-n=\"1\">229</sup> אויף \"הקורא את המגילה למפרע לא יצא\": ווען איינער לייענט די מגילה און ער מיינט אַז דער סיפּור וואָס ווערט דאָרט דערציילט האט פּאַסירט (נאָר) <i>אַמאָל</i>, \"למפרע\", און ניט איצטער איז דער נס, איז – \"לא יצא\"<sup data-n=\"2\">230</sup>. דער תכלית פון קריאת המגילה איז אָפּצולערנען זיך פון איר ווי אַ איד דאַרף זיך פירן <i>איצטער</i><sup data-n=\"3\">231</sup>.",[["1","229","ספר דברי שלום פ' בא (לג, ג)."],["2","230","וי\"ל הפירוש לחידודי: \"לא יצא\" מגזירת המן שבדורו, נגד \"דתיהם שונות מכל עם\", נגד <i>יהודים</i> – מודים בהשם וכל התורה כולה – מגילה יג, רע\"א. קידושין מ, א. כי בכל דור ודור עומדים עלינו כו' (הגש\"פ פיסקא \"והיא שעמדה\"). – ספר השיחות תשמ\"ז ע' 351 הערה 36."],["3","231","לקוטי שיחות ח\"ו ע' 189. ע' 385. ח\"ז ע' 332. וראה שיחת פּורים תשל\"ו, שנתבאר פּירוש הבעש\"ט ע\"פּ פּירוש הפּשוט במחז\"ל זה."]]],[300010623,"קא\n\nחגיגה טו, א: <i>יצתה בת קול ואמרה שובו בנים</i>.\n<b>וכנודע</b> ממאמר הבעש\"ט נ\"ע בענין הבת-קול שמכרזת שובו בנים, דקשה מי הוא השומע כו'. וא\"כ מהו הפעולה מהכרוז, אלא היינו דמזליה חזי הכרוז ומזה נמשך ג\"כ הרגשה בנשמה שבגוף שנמשך לה מלמעלה מבחי' מזליה<sup data-n=\"1\">232</sup>.",[["1","232","לקו\"ת תצא לו, ד. וראה לקו\"ת שלח מו, ב: וכמאמר הבעש\"ט ז\"ל על הבת קול שמכרזת שהם הרהורי תשובה והם באים מלמעלה שאין אדם עושה מאומה מצד עצמו והיינו כמו תחלת הבריאה כי חפץ חסד הוא ועל המשכה זו ארז\"ל קדושתי למעלה מקדושתכם. אוה\"ת במדבר ח\"ה ס\"ע א'תריג ואילך. ועד\"ז הוא בלקו\"ת שה\"ש כד, א. וראה גם כתר שם טוב סימן קמו. רנה. שס.\nבהמשך מים רבים תרל\"ו פרק קפא הובאה תורת הבעש\"ט על הב\"ק דאבות (פ\"ו). וראה גם לקו\"ת במדבר ו, ג. המשך תרס\"ו ע' קכא. ספר המאמרים תרפ\"ח ע' קכ. תרצ\"ב ע' קטז ואילך. תש\"ב ע' 139. לקוטי שיחות ח\"ט ע' 25.\nוראה אגרות-קודש כ\"ק אדמו\"ר זי\"ע ח\"ה ע' קלד: ובמה שהעיר כת\"ר במש\"כ בדא\"ח בכ\"מ ומהם בלקו\"ת . . בשם הבעש\"ט . . הפי' בענין הבת קול שמכרזת דשומע המזל . . וצ\"ע שהלא הוא בשל\"ה (רמ\"ג, ב') בשם ס' חרדים.\nאבל כ\"כ בעצמו שוברו בצדו, כי הבעש\"ט מבאר יותר משא\"כ בהנ\"ל, ובהדרושים בלקו\"ת נוגע הוספת הבעש\"ט בעיקר, או עכ\"פ בטפל."]]],[300010624,"קב\n\n<b>וידוע</b> הקושיא למה לא נשמע קול הכרוזים הללו לשום אדם, אך הענין הוא כמאמר הבעש\"ט ז\"ל דהרהורי תשובה שנופלים לאדם פתאום בלתי שהכין א\"ע לזה הוא בא ונמשך עליו מבחי' הרוח העליון שעורר אותו לזה<sup data-n=\"1\">233</sup>.",[["1","233","מאמרי אדמו\"ר הזקן תקס\"ה ח\"ב ע' תתלג."]]],[300010625,"קג\n\nיבמות עט, א: <i>שלשה סימנים יש באומה זו כו'</i>.\n<b>הבעש\"ט</b> פי' מארז\"ל שלשה סימנים יש באומה זו הרחמנים והביישנים וגומלי חסדים. <i>רחמנים</i> – שמרחמים על הנשמה שירדה מרום מעלתה בעמדה לפני ה' בגן ה' וירדה בסתר המדרי' להתלבש בגוף אשר מעפר יסודו וסופו לעפר. <i>ביישנים</i> – שהם מתביישים מנר אלקים אשר על ראשם ומטיבים מעשיהם בקיום המצות. <i>גומלי חסדים</i> – דנשמת אדם העליון אשר על דמות הכסא תלמדם להעלות את גופם וכל צרכיו, נוסף על חלקם בעולם, כפי גזירת ההשגחה העליונה במקום וזמן, לזככם ולהאירם באור תורה ועבודה<sup data-n=\"1\">234</sup>.",[["1","234","ספר השיחות תש\"ג ע' 161 (הועתק ב\"היום יום\" חלק שני ע' כ)."]]],[300010626,"קד\n\nכתובות נ, א: <i>המבזבז אל יבזבז יותר מחומש</i>.\n<b>מען</b> דערציילט<sup data-n=\"1\">235</sup>, אַז דער בעש\"ט האָט געגעבן צדקה מער ווי אַ פינפטל, האָט מען אים געפרעגט, ס'שטייט דאָך אל יבזבז יותר מחומש? האָט ער געענטפערט, אַז המבזבז איז מלשון ביזה (וואָס איז ביי מלחמות וכיוצא בזה) ד. ה. דער וואָס וויל ניט געבן און ער דאַרף מיט זיך מלחמה האָבן, פּועל'ן בדרך כפי' ובדרך ביזה, אָפּרייסן דאָס ביי זיך, איז אל יבזבז יותר מחומש. דאַגעגען דער וואָס גיט דאָס בשמחה ובעונג (איז מיט וואָס איז אַנדערש צדקה פון אַנדערע תענוגים און באַדערפענישן אויף וועלכע ער גיט אויס געלט?)<sup data-n=\"2\">236</sup>.",[["1","235","הובא בספר אורח לחיים פרשת תרומה. ספר וציוה הכהן פרק טו."],["2","236","לקוטי שיחות ח\"א ע' 170. וראה תניא אגה\"ת פ\"ג (צג, א). אגה\"ק ס\"י (קטו, ב). לקוטי שיחות חכ\"ז ע' 217 ואילך."]]],[300010627,"קה\n\nנדרים לב, א: <i>בן ג' שנים הכיר אברהם את בוראו</i>.\n<b>ח\"י</b> אלול – תק\"ח – בעת דער סעודת החגיגה – דערציילט הגאון הצדיק ר' יעקב יוסף בעל התולדות – האָט מורנו הבעש\"ט געזאָגט אַ תורה אויף דעם מאמר (נדרים ל\"ב ע\"א) בן שלש שנים הכיר אברהם את בוראו, אברהם אבינו האָט געהאַט מסירות נפש אויף דעם דרך השם, געבן אַלעמען צו פאַרשטיין אחדות הבורא און השגחה פּרטית<sup data-n=\"1\">237</sup>.",[["1","237","לקוטי דיבורים ח\"ג שפט, ב ואילך. ספר השיחות תש\"א ע' 158. וממשיך שם: בתוך הסעודה האָט מורנו הבעש\"ט געזאָגט: דער בעל הנשמה אדמו\"ר הזקן אין פּוילן איז היינט געוואָרען דריי יאָהר בן שלש שנים הכיר את בוראו, ער וועט אויך דאַרפען דורך גיין אברהם אבינו'ס מסירות נפש, אויף צו מגלה זיין דעם דרך העבודה אין אחדות והשגחה פּרטית."]]],[300010628,"קו\n\nבבא מציעא ב, א: <i>שנים אוחזין בטלית כו'</i>.\n<b>פירוש</b> המשנה שנים אוחזין בטלית כמו שלומדים אותה במתיבתא דרקיע:\nבכל דבר שברא הקב\"ה בעולם הזה יש בו ניצוץ דקדושה וכשאדם עושה מצוה בדבר ההוא, מעלה את הניצוץ דקדושה לשרשו לאותו העולם שמשם הורידו הקב\"ה. ועל ידי זה שהאדם מעלה את הניצוץ – הוא זוכה לשכר טוב כפי פסק ההלכה שבתורה בזכות כל מצוה ומצוה. ואם מצוה אחת נעשית על ידי שני אנשים אז הנה שכר המצוה נחלק לשניהם.\nובפסק הלכה זו דמצוה שעשאוה שני אנשים ועל ידי שניהם נתעלה הניצוץ דקדושה שהי' בהדבר ההוא הנה בזה הוא הלימוד במתיבתא דרקיע: שנים, שני אנשים ואחד מהם, ראובן למשל, ידע כי שמעון נטה מדרך הישר וצריכים להחזירו למוטב, וסיפר ראובן ללוי על אודות שמעון והלך לוי והתעסק עם שמעון והחזירו למוטב, ונעשה בעל תשובה גמור ונתעלו ניצוצות הקדושה על ידי ראובן שסיפר ללוי ועל ידי לוי שהתעסק עם שמעון, והם שנים האוחזין בטלית, שהטלית הם ניצוצות הקדושה ושנים אוחזין בה זה אומר אני מצאתי', ראובן, על דרך משל, אומר אני הוא שספרתי על אודות שמעון שצריכים להחזירו למוטב וא\"כ כולה, כל השכר, שלי הוא. וזה – לוי על דרך משל – אומר אני הוא שעסקתי עם שמעון להחזירו למוטב וכולה שלי, כל השכר שלי, הנה פסק ההלכה הוא ששניהם זוכים בשכר<sup data-n=\"1\">238</sup>.",[["1","238","ספר הזכרונות ח\"ב ע' 426. ראה גם ד\"ה רבי אומר ה'ש\"ת (ספר המאמרים ה'ש\"ת ע' 75). קונטרס לימוד החסידות ע' 20 [אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' שנד]. אוה\"ת על מארז\"ל ע' לה. ספר המאמרים תרפ\"ט ע' 157. וש\"נ. קונטרס שנים אוחזין בטלית (קה\"ת, תשנ\"ו) ע' 9. וראה גם התוועדויות תשמ\"ה ח\"ב ע' 1298 ואילך."]]],[300010629,"קז\n\nבבא מציעא ל, ב: <i>לא חרבה ירושלים אלא על . . שהעמידו דיניהם על דין תורה</i>.\n<b>לא</b> חרבה ירושלים אלא על שהעמידו דיניהם על דין תורה. ירושלים הוא יראת שמים וההנהגה רק ע\"פ דין תורה מחרבת היראת שמים. ולפנים משורת הדין מחזקת היראת שמים<sup data-n=\"1\">239</sup>.",[["1","239","ספר הזכרונות ח\"א ע' 345."]]],[300010630,"קח\n\nסנהדרין מד, א: <i>אע\"פ שחטא ישראל הוא</i>.\n<b>אַ</b> איד האט זיך קיינמאָל ניט גע'שמד'ט און אַ גוי האָט זיך קיינמאָל ניט מגייר געווען, דער וואָס האָט זיך גע'שמד'ט איז לכתחילה געווען אַ גוי ער האָט ניט געהאַט קיין יחידה, דער וואָס האָט זיך מגייר געווען איז לכתחילה געווען אַ איד<sup data-n=\"1\">240</sup>, ער האָט געהאַט די יחידה שבנפש, השי\"ת בעדאַרף נאָר מסבב זיין עס זאָל אַראָפּגענומען ווערן די העלמות וואָס פאַרדעקן אויף דער נקודה און די התגלות פון דער נקודת היהדות מאַכט פון אַ רשע גמור אַ צדיק<sup data-n=\"2\">241</sup>.",[["1","240","ראה תשובות מהר\"ם מרוטונבורג (הובא בס' תשובות בעלי התוס' מכת\"י (נ.י. תשי\"ד סימן יט – ע' רפו): \"מלאך הממונה על ההריון . . ולפעמים משים נשמה שראוי' להיות גוי במעי יהודי' ואותו נעשה משומד, ולפעמים משים נשמה שראוי' להיות יהודי במעי גוי' ואותו נעשה גר\". ולהעיר מהדיוק בלשון חז\"ל (שבת קלה, א. פסחים צב, א. יבמות מז, א. ובכ\"מ) \"גר שנתגייר\" (ולא גוי שנתגייר) – מדבר קדמות להחיד\"א מערכת ג אות ג. הובא בלקוטי שיחות חי\"ח ע' 130. ועוד."],["2","241","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ח ע' רח. וראה גם רד\"ה ויהי בשלח תשכ\"א (ספר המאמרים תשכ\"א ס\"ע 256 ואילך)."]]],[300010631,"קט\n\nעבודה זרה יט, ב: <i>כל העוסק בתורה נכסיו מצליחין לו</i>.\n<b>דער</b> בעש\"ט – האָט געזאָגט ח\"י אלול, תקט\"ו: כל העוסק בתורה נכסיו מצליחין לו (ע\"ז די\"ט ע\"ב). יעדער איד האָט זיינע נכסים. קאָפּ און האַרץ, שכל און מדות – דאָס זיינען די נכסים פון אַ אידן. דער וואָס איז אַ עוסק בתורה, ניט נאָר אַ לומד תורה, זיינען זיינע נכסים מצליח. אברהם אבינו איז געווען אַ למדן און אַ ירא אלקים, קיים כל התורה עד שלא ניתנה<sup data-n=\"1\">242</sup>. אָבער דעם אייביגן כריתת ברית וואָס הקב\"ה האָט כורת ברית געווען מיט אברהם אבינו לדורותיו עד סוף כל הדורות איז פאַר דעם וואָס מצא את לבבו נאמן. די ערנסטקייט פון האַרצן<sup data-n=\"2\">243</sup>, די תמימות מיט דער פּשטות און די אמונה פּשוטה, דאָס זיינען די אידישע נכסים און ווען מען איז עוסק בתורה נכסיו מצליחין לו<sup data-n=\"3\">244</sup>.",[["1","242","יומא כח, ב. וש\"נ."],["2","243","ראה תו\"א קיד, ד. ד\"ה אתה הוא הוי' לבדך ה'ש\"ת (ספר המאמרים ה'ש\"ת ע' לה ואילך)."],["3","244","ספר השיחות התש\"ב ע' 131."]]],[300010632,"קי\n\nאבות פ\"ב מ\"ב: <i>כל תורה שאין עמה מלאכה סופה בטילה</i>.\n<b>מורנו</b> הבעש\"ט האָט געזאָגט אויף דעם מאמר \"כל תורה שאין עמה מלאכה סופה בטילה\", מלאכה מיינט התעסקות, כל תורה שאין עמה מלאכה, התעסקות אין אהבת ישראל, סופה בטילה, יעדע שטיקעל תורה וואָס מען לערנט און עס בריינגט ניט מלאכה ד. ה. אהבת ישראל, איז די תורה קיין תורה ניט<sup data-n=\"1\">245</sup>.",[["1","245","ספר השיחות קייץ ה'ש\"ת ע' 115. ושם, שזהו אחת מהג' תורות ששמע הגאון הצדיק ר' לוי יצחק בערדיטשעווער ומסיים: די תורות וואָס דער בערדיטשעווער רב האָט געהערט ממורנו הבעש\"ט האָבן מעורר געווען די התגלות עצם נשמתו הקדושה, אַז מיט זיין עבודתו הקדושה במסירת נפש צו ממליץ טוב זיין אויף יעדער בן ובת ישראל האָט ער זוכה געווען אויפצושטעלען אַ נייעם היכל הזכות.\nהובא ונתבאר בלקוטי שיחות ח\"א ע' 260, וז\"ל: . . . דאָס איז דאָך אַן ענין וואָס שטייט בפירוש אין גמרא, אַז דורך דעם וואָס עס פעלט די השפּעה אויף דעם צווייטען פעלט דער מאיר עיני שניהם הוי', דער עזר שלמעלה, און נאָך מער – ווי עס ווערט דאָרט אויסגעפירט – אַז פון דעם עשיר ווערט אַן עני, איז דאָך פאַרשטאַנדיק אַז תורה אָן אהבת ישראל סופה בטילה.\nדער בעל שם טוב האָט נאָך מבאר געווען, אַז בכדי די תורה זאָל האָבן אַ קיום, איז ווייניק אהבת ישראל סתם, נאָר עס דאַרף זיין אין דעם <i>מלאכה</i>, וכלשון הבעש\"ט, <i>התעסקות</i> אין אהבת ישראל.\nדעם טייטש פון התעסקות דערקלערט כ\"ק מו\"ח אדמו\"ר* אַז דאָס איז געגליכן צו אַ געשעפט, אַ בעל עסק מיינט ניט אַז ער זיצט ביי זיך אין הויז מיט זיין סחורה און וואַרט ביז עמעצער וועט זיך דערוויסן אַז ביי אים איז דאָ סחורה און וועט וויסן איר מעלה, און וועט קומען צו אים קויפן – ניט דאָס איז דער סדר פון אַ סוחר. דער סוחר עפנט אַ קראָם (סטאָר) וואו עס גייען פאַרביי אַ סך מענטשן און ער הענגט אויף אַ שילד, אַז אַלע פאַרבייגייער זאָלן וויסן אַז ביי אים געפינט זיך סחורה, דערמיט באַנוגענט ער זיך נאָך ניט, ער גייט אום און איז מפרסם און דערציילט די מעלה פון זיין סחורה, און רעדט איין מען זאָל ביי אים קויפן; ער טוט כל מיני השתדלות, מען זאָל זיין סחורה קויפן.\nדער רבי האט גערעדט דעמאָלט בענין עסק התורה והמצוות. דאָס זעלבע איז אויך בהנוגע התעסקות אין אהבת ישראל. מען דאַרף לייגן כל המיני השתדלות אויף טאָן אַ אידן אַ טובה, משפּיע זיין אים דאָס וואָס מען האָט, מסביר זיין אים די טייערקייט פון תורה ומצוות, פאַרשטייט זיך, תורת החסידות אַריינגערעכנט, און טאָן אַלע מיני השתדלות אַז אַ איד זאָל הערן אַ וואָרט חסידות. און דערמיט זיך ניט באַנוגענען, נאָר מען דאַרף נאָך יענעם מאַכן פאַר אַ טופח על מנת להטפיח, וואָרום ערשט דאַן ווען זיינע מקבלים וועלן אויך ווערן משפּיעים וועט מען וויסן אַז זיין השפּעה איז אין זיי נקלט געוואָרן.\nוראה אגרות-קודש כ\"ק אדמו\"ר זי\"ע חי\"ז ע' קסח: והנה לכאורה מרז\"ל מפורש הוא, כל האומר אין לי אלא תורה אפילו תורה אין לו (עיין לקו\"ת ראה כג, ג), שצ\"ל עם גמ\"ח. אבל מודגשת בתורת הבעש\"ט, שתי נקודות: א) שצ\"ל הדבר אין יעדער שטיקל תורה, ב) שצריכה להיות התעסקות, וכמבואר במ\"א בענין עסק, שאין זה שיושב בהיכלו ומחכה עד שיבוא מי אליו וישאלנו האם יש לו סחורה למכור אלא אדרבה יוצא ממקומו מתעסק ומשתדל ומחפש איפוא למכור סחורתו ומשדל את הקונה בכל מיני אופנים וכו' והנמשל מובן.\n-----שולי הגליון-----\n*) <i>ד\"ה הסכת ושמע תרצ\"ג (ספר המאמרים קונטרסים ח\"א רנז</i>,<i> ב ואילך. ספר המאמרים תרצ\"ג ע' תצו ואילך)</i>."]]],[300010633,"קיא\n\nאבות פ\"ג מ\"י: <i>כל שרוח הבריות נוחה הימנו רוח המקום נוחה הימנו</i>.\n<b>דער</b> בעש\"ט איז אַמאָל אַרויסגעגאַנגען צו די חבריא און האָט געזאָגט: אַז עס איז רוח הבריות נוחה הימנו איז אַ סימן אַז רוח המקום נוחה הימנו<sup data-n=\"1\">246</sup>.",[["1","246","ספר השיחות תש\"ה ע' 63. ושם: האָט דאָס אויפגעטרייסלט די גאַנצע חבריא קדישא. וראה ספר המאמרים אידיש ע' 173."]]],[300010634,"קיב\n\nאבות פ\"ג מט\"ז: <i>ונפרעין מן האדם מדעתו ושלא מדעתו</i>.\n<b>דער</b> בעש\"ט נ\"ע האָט מפרש געווען די משנה: ונפרעין מן האדם מדעתו ושלא מדעתו. מען באַצאָלט דעם מענטשן פאַר זיינע ניט גוטע זאַכן וועלכע ער האָט געטאָן מיט זיין וויסן און אויך אפילו אָן זיין וויסן, און פון זיין וויסן הייסט ווען דער מענטש רעדט זיך אויס אויף זיך אַליין אַ שלעכט וואָרט, ווי מיר זעען ווען ח\"ו איינער האָט יסורים אין קינדער אָדער אין געזונט אָדער אין פּרנסה ווען אים איז ח\"ו זייער ניט גוט רעדט ער זיך אויס אַ שווער וואָרט אַז ח\"ו וח\"ו איז אים ניט ניחא דער לעבן, אָדער ער זאָגט אַז ווידער אַזאַ ביטערער לעבן וויל ער בעסער דעם פאַרקערט ח\"ו וח\"ו וכדומה אַזעלכע אויסשפּראַכן. דער שלא מדעתו איז ווען איינער רעדט וועגן דעם צווייטן און זאָגט אַז יענער וועלכער האָט געזאָגט אָדער געטאָן דאָס און דאָס איז ווערט אַזאַ און אַזאַ עונש, איז מיט דעם וואָס ער זאָגט אַזוי פּסק'נט ער דאָס ניט אויף יענעם נאָר אויף זיך אַליין, און דאָס איז ונפרעין מן האדם שלא מדעתו, אַז דער מענטש ווייס ניט אַז ער פּסק'נט דעם עונש אויף זיך אַליין, דאָס הייסט מיט דעם וואָס ער זאָגט אַז יענעם קומט אַזוי און אַזוי פּסק'נט ער דאָס אויף זיך אַליין<sup data-n=\"1\">247</sup>.",[["1","247","ספר המאמרים אידיש ע' 76."]]],[300010635,"קיג\n\n<b>ביאור</b> פון בעש\"ט<sup data-n=\"1\">248</sup>, אויף דער משנה: \"ונפרעין מן האדם מדעתו ושלא מדעתו\", אז מלמעלה איז מען מעניש נאָר \"מדעתו\", דוקא ווען ער אַליין פּסק'נט אָפּ דעם עונש אויף זיך; דער מענטש אָבער גיט ארויס זיין פּסק אין אַן אופן פון \"שלא מדעתו\": מען איז אים מזמין אַ צווייטן וואָס האָט געטאָן אַזאַ חטא ווי זיינער און אַרויסזאָגנדיק זיין מיינונג וואָס פאַר אַן עונש עס קומט דעם צווייטן פאַר אָט דער עבירה, גיט ער דערמיט אַרויס אַ פּסק אויף זיך אַליין, און מען איז דעמאָלט נפרע פון אים מיט דעם עונש. און דאָס מיינט \"מדעתו ושלא מדעתו\"<sup data-n=\"2\">249</sup>: \"מדעתו\" – זיין אייגענער פּסק, נאָר דאָס קומט אין אַן אופן פון \"שלא מדעתו\", ער האָט ניט געוואוסט אַז ער פּסק'נט דערמיט אויף זיך<sup data-n=\"3\">250</sup>.",[["1","248","הובא בליקוטי מהר\"ן סי' קי\"ג. שוב מצאתי ענין זה בבינה לעתים דרוש סג. וכענין שמצינו בדוד (שמואל-ב יב, ז) \"אתה האיש\". – בד\"ה אני לדודי פ\"ב (ס' המאמרים אידיש ע' 76 – הועתק בקטע שלפנ\"ז) נמצא פי' הבעש\"ט באופן אחר קצת. ואולי הם ב' פירושים שלו. ושבעים פנים לתורה."],["2","249","ראה ג\"כ לקמן סימן קמו."],["3","250","לקוטי שיחות ח\"ד ע' 1207. וממשיך שם: לויט דעם וועט מען אויך פאַרשטיין דעם לשון \"דין וחשבון\" (אבות רפ\"ג), פריער דין און דערנאָך \"חשבון\": צום ערשט קומט דער \"דין\" וואָס ער אַליין פּסק'נט אָפּ פאַר אַזאַ פּעולה, און דערנאָך מאַכט מען דעם חשבון, אַז ער האָט געטאָן אַזאַ פּעולה, במילא קומט אים אויך דער זעלבער פּסק דין.\nלכאורה איז ניט פאַרשטאַנדיק, פאַרוואָס דאַרף בית-דין שלמעלה אָנקומען צום פּסק דין פון דעם מענטשן, און זיי פּסק'נען ניט אָפּ אַליין דעם דין?\nאיז דער טעם אויף דעם: יעדער איד איז אַ \"חלק אלקה ממעל ממש\"<sup data-n=\"4\">1</sup>, און אין יעדן \"חלק\" פון אַן עצם איז דאָך פאַראַן דער עצם, כמאמר הבעש\"ט<sup data-n=\"5\">2</sup>: \"כשאתה תופס במקצת מן העצם אתה תופס בכולו\", ד. ה. אַז אַן \"עצם\", איז אין יעדער טייל פון אים, געפינט ער זיך מיט זיין גאַנצע עצמיות. ובמילא קען קיינער אַפילו מלאכים הכי עליונים, ניט האָבן קיין שליטה איבער אַ אידן. כל-זמן ער אַליין פּסק'נט ניט אָפּ דעם דין אויף זיך אַליין קען עס קיינער ניט פּסק'נען, ווייל קיינער האָט ניט קיין שליטה איבער אים.\nאדרבה, אַ איד מצד זיין עצם איז ער מושל ושליט אויף אַלע ענינים עליונים ותחתונים, וואָס דערפאַר הייסט יעדער איד מיטן נאָמען \"ישראל\" – \"כי <i>שרית</i> עם אלקים ועם אנשים ותוכל\"<sup data-n=\"6\">3</sup>, אַז אַ איד איז אַ בעל-הבית און געוועלטיקט איבער מלאכים (\"אלקים\") און \"אנשים\". ושם בס\"י: פון דעם אויבענדערמאָנטן כלל \"כשאתה תופס במקצת מן העצם אתה תופס בכולו\" איז פאַרשטאַנדיק, אַז אין דער תורה פון בעש\"ט וועגן \"נפרעין כו'\", דריקט זיך אויך אויס עצם ענינו פון דעם בעש\"ט:\nעצם ענינו של הבעש\"ט איז געווען צו מעורר זיין די נשמה פון יעדער אידן, און דאָס איז אויך מרומז אין דעם בעש\"ט'ס נאָמען \"ישראל\", וועלכער איז דער שם פון <i>יעדן</i> איינציקן אידן<sup data-n=\"7\">4</sup>.\nדאָס דריקט זיך אויס אין כללות תורת הבעש\"ט (תורת החסידות), וואָס זי איז מבאר די גרויסקייט און הויכקייט פון נשמות ישראל, אַז זיי זיינען אַ \"חלק אלקה ממעל ממש\"<sup data-n=\"8\">5</sup>, און אויך אין דער אויבנדערמאָנטער תורה אויף דער משנה \"ונפרעין כו' מדעתו ושלא מדעתו\". וראה גם לקוטי שיחות ח\"ו ע' 283 ואילך.\n-----שולי הגליון-----"],["4","1","<i>איוב לא</i>,<i> ב</i>.<i> ובתניא [ריש פרק ב] מוסיף \"ממש\". וראה שפע טל בהקדמה</i>."],["5","2","<i>המשך תרס\"ו בסופו</i>."],["6","3","<i>בראשית לב</i>,<i> כט</i>."],["7","4","<i>ראה בארוכה לקוטי שיחות ח\"ב ע' 472</i>."],["8","5","<i>ראה הערות הצמח צדק לתניא רפ\"ב</i>."]]],[300010636,"קיד\n\nאבות פ\"ד מ\"א: <i>איזהו חכם הלומד מכל אדם שנאמר</i><sup data-n=\"1\">251</sup><i> מכל מלמדי השכלתי</i>.\n<b>וקשה</b> האם כל אדם מלמד הוא. ומצינו שמלמד צריך שיהיו לו סגולות ומעלות שונות. ואיך אמר הלומד מכל אדם, וכי כל אדם יש לו אותן הסגולות ללמד. ומה ראי' מהכתוב מכל מלמדי השכלתי. דלכאורה זהו רק כאשר האדם משכיל במה שהמלמד מלמדו. וכמו מבין דבר מתוך דבר. ואיך הלומד מכל אדם הוא חכם. אך הענין הוא דכתיב<sup data-n=\"2\">252</sup> נר הוי' נשמת אדם. ובנר יש ב' דברים אור הנר וצלו. אור הנר הוא מהנר עצמו, וצל האור בא ע\"י כלי הנר. כן הוא בנשמה שיש בה אור וצל. האור בא מן הנשמה, והצל שעל אור הנשמה בא מן הגוף שהוא הכלי. כשעומדים בתוך ד' אמות של צדיק נופלות מחשבות טובות. והן גילוי אור נר הנשמה. וכשעומדים בתוך ד' אמות של רשע נופלות מחשבות רעות. מהצדיק לומדים ועשה טוב, ובזה נעשים ממזכי הרבים. ומהרשע לומדים סור מרע. ובזה נעשים כלי להרהור תשובה. וזהו הלומד מכל אדם, דמכל אדם בין צדיק ובין רשע ח\"ו אפשר וצריכים ללמוד. והראי' מכל מלמדי השכלתי, דכל מה שברא הקב\"ה בעולם הוא בשביל ללמד האדם וכתיב<sup data-n=\"3\">253</sup> מלפנו מבהמות ארץ א\"ר יוחנן אלמלא ניתנה תורה לישראל למדנו צניעות מחתול וגזל מנמלה<sup data-n=\"4\">254</sup>. וההשגחה העליונה מזמנת להאדם ממה ללמוד<sup data-n=\"5\">255</sup>. וזהו החכם הלומד מכל אדם בסור מרע ועשה טוב<sup data-n=\"6\">256</sup>.",[["1","251","תהלים קיט, צט."],["2","252","משלי כ, כז."],["3","253","איוב לה, יא."],["4","254","עירובין ק, ב."],["5","255","ראה גם לקמן סימן רכג ואילך."],["6","256","ספר הזכרונות ח\"א ע' 344."]]],[300010637,"קטו\n\n<b>בשם</b> הבעש\"ט וואָס ער האָט געזאָגט אויפן מארז\"ל איזהו חכם הלומד מכל אדם שנאמר מכל מלמדי השכלתי, האָט דאָך געדאַרפט שטיין הלומד מכל מלמד. האָט דער בעש\"ט געזאָגט, אַז מען דאַרף לערנען פון יעדן איינעם, אפילו פון אַן אדם רשע דאַרף מען לערנען אַ מדה טובה<sup data-n=\"1\">257</sup>.",[["1","257","ספר השיחות קייץ ה'ש\"ת ע' 104. ושם לפנ\"ז: החסיד ר' בצלאל האט געלערנט פון יעדן איינעם א מדה טובה. ער פלעגט דערציילן [ההמשך בפנים. וממשיך שם]: ווי ר' זושע האָט געזאָגט אַז מ'דאַרף לערנען אַפילו פון אַ גנב (ראה \"היום יום\" ג אייר) ווייל יעדער איד האָט אַ אות אין תורה און אַ מדה פון י\"ג מדות שנדרשת בהם. וראה גם לקמן סימן קפה."]]],[300010638,"קטז\n\nאבות פ\"ד מ\"א: <i>איזהו גבור הכובש את יצרו</i>.\n<b>הבעש\"ט</b> אמר: איזהו גבור הכובש את יצרו, כובש את יצרו אמרו ולא שוברו, כי שבירת היצר אין זה גבורה כלל, כי בשביל לשבור את היצר די ומספיק שכל הישר, דהשכל הישר מחייב שצריכים לשבור את היצה\"ר, אבל ענין הכבוש הוא להשתמש בכחותיו ובמעלותיו, דרב תבואות בכח שור<sup data-n=\"1\">258</sup>, ומתנהג בתוקף, וזהו איזהו גבור הכובש את הכחות של יצרו ומשתמש בו בקדושה<sup data-n=\"2\">259</sup>.",[["1","258","משלי יד, ד."],["2","259","ספר המאמרים תש\"ט ע' 92, ומועתק בזה הסיפּור הקשור בזה (שם): פתאום אמר לי כ\"ק אאמו\"ר – אאזמו\"ר מוהר\"ש – מיר האָבן זיך פאַררעדט, זאָג מיר וואָס האָט זיך דיר גע'חלומ'ט באַ דער נאַכט וואָס האָסטו געזעהן, און וואָס האָסטו געהערט אין חלום.\nכרגע – מספר כ\"ק אאמו\"ר – רעד עבר בכל גוי, וארכבותי דא לדא נקשן*, וכנראה אשר גם מראה פני השתנה, כי כ\"ק אאמו\"ר אמר לי: וואָס ביסטו אַזוי איבערגעשראָקן און פאַרשעמט, דערצייל דבר דבר על אופנו כסדרו.\nוועמען פון די וואָס דו האָסט געזעהן אין חלום קאָנסטו זיי.\nואני עודני רועד כולי, ופשוט לא יכולתי לדבר, כי אין מלה בלשוני. כעבור איזה זמן התגברתי על עצמי, ואמרתי:\nאלו שהכרתים היו כ\"ק אאזמו\"ר – צמח צדק – הי' לבוש בבגדי שבת, משי לבן, כ\"ק דודי הרב\"ש והמהרי\"ל, והשאר לא אדע.\nכ\"ק אאמו\"ר – אאזמו\"ר – שאלני איך הי' מושבם, ואמרתי לו: שנים ישבו בראש השלחן, ואחוריהם ישבו שבעה אנשים מימינו של היושב בימין ישבו שני אנשים ואחריהם דודי כ\"ק מהרי\"ל, ומשמאלו של היושב בשמאל ישב כ\"ק אאזמו\"ר ואצלו כ\"ק דודי הרב\"ש.\nכ\"ק אאמו\"ר אמר לי, כי שנים היושבים בראש השולחן הם הבעש\"ט – מימין והרב המגיד ממעזריטש – משמאל, והאנשים היושבים אחוריהם, הנה שלשה הם מתלמידי הבעש\"ט, וארבעה מתלמידי הרב המגיד, כ\"ק אאזמו\"ר הזקן ישב מימין הבעש\"ט ואצלו כ\"'ק אאזמו\"ר – האמצעי – ואצלו אחי, דודך מהרי\"ל, כ\"ק אאמו\"ר ישב אצל הרב המגיד מול כ\"ק אאזמו\"ר הזקן ואצלו אחי, דודך הרב\"ש.\nמה שמעת – שאלני כ\"ק אאמו\"ר – והאם אתה זוכר מה ששמעת [ההמשך בפנים].\n-----שולי הגליון-----\n*) <i>ע\"פ דניאל ה, ו</i>."]]],[300010639,"קיז\n\nאבות פ\"ו, ו: <i>כל האומר דבר בשם אומרו מביא גאולה לעולם</i>.\n<b>כל</b> האומר דבר בשם אומרו מביא גאולה לעולם. דער וואָס דערציילט אַ זאַך און דערביי דערמאָנט ער דעם וואָס האָט דעם דבר געזאָגט, ווי מיר טרעפן אָפט באַ די חז\"ל אַז ר' פלוני האָט געזאָגט בשם ר' פלוני, און אָפט טרעפט נאָך אַז באַ דער מסירת המימרא איז נאָך אָפּגעהיט געוואָרן אַ איכא דאמרי, איז מיט דעם וואָס מען דערמאָנט דעם נאָמען פון דעם וואָס האָט עס געזאָגט איז דורכדעם בריינגט מען אַ גאולה לעולם. אין פלוג וואָס איז די רבותא. פאַרוואָס איז אַזוי גרויס וואָס מען זאָגט בשם אומרו אַז דער שכר דערפאַר איז וואָס מען בריינגט אַ גאולה לעולם, און וואָס איז דער ענין וואָס דער עולם באַדאַרף האָבן אַ גאולה, ווי דען זאָל מען זאָגען ניט בשם אומרו איז דאָך דאָס אַ שקר. אַ גראָבער ליגנער איז מורגל צו זאָגן איך זאָג. דער וואָס איז ניט אַזוי גראָב זאָגט-ניט אַז ער זאָגט-דאָס נאָר זאָגט סתם, נאָר לבסוף לאָזט ער אויס אַזוי אַז די צוהערער זאָלן מיינען און פאַרשטיין פון זיין אויסשפּראַך אַז ער האָט דאָס געזאָגט מעצמו. און אַזוי זיינען פאַראַן כמה אופני אויסשפּראַכן. היינט וואָס איז די רבותא אַז מען זאָגט בשם אומרו און דאָס איז נאָך אַזוי גרויס אַז דער שכר פאַר דעם איז אַז מען איז מביא גאולה לעולם. וואָס פון דעם איז צו פאַרשטיין אַז עולם מוז האָבן אַ גאולה און ער בריינגט די גאולה, ווי עס שטייט<sup data-n=\"1\">260</sup> גאולה תתנו לארץ, ארץ וואָס דאָס איז עולם מוז האָבן גאולה. האָט דער רבי געזאָגט בשם מורו הבעש\"ט גאולה בגימטריא מ\"ה און דאָס איז וואָס מביא גאולה לעולם, וואָס בחכמה אתברירו<sup data-n=\"2\">261</sup>. עולם איז העלם. מביא גאולה לעולם דעם גילוי ההעלם. היינו דעם גילוי העלם העצמי<sup data-n=\"3\">262</sup>.",[["1","260","בהר כה, כד."],["2","261","תניא אגה\"ק סכ\"ח (קמח, א) בשם הזוהר. – ראה זח\"ב (היכלות) רנד, סע\"ב."],["3","262","ספר השיחות תש\"ח ע' 245. ושם לפנ\"ז: איצטער גיב איך אייך איבער די צוויי תורות פון מורנו הבעש\"ט . . . די צווייטע איז הוד כ\"ק רבינו הזקן'ס אַ תורה, וואָס ער האָט געזאָגט פאַר זיינע תלמידים יונגע לייט קומענדיק דעם ערשטן מאָל פון מעזריטש [ההמשך בפנים]."]]],[300010640,"קיח\n\nחולין מח, ב: <i>אתמר מחט שנמצאת בריאה, רבי יוחנן ורבי אלעזר ורבי חנינא מכשרי, רבי שמעון בן לקיש ורבי מני בר פטיש ורבי שמעון בן אליקים טרפי</i>.\n<b>אתמר</b> מחט שנמצאה בריאה, אַ ברזל וואָס מען געפינט אין דער לונג, ברזל עם הכולל בגימט' עמלק, און עמלק איז בגימט' ספק, און ספק איז בגימט' ר\"מ און ר\"מ איז מ\"ר, איז אַז מען געפינט אַ ברזל אין די ריאה, דאָס הייסט עמלק וואָס וואַרפט אַריין ספיקות אין אמונת ה' אין דער הייליקייט פון תורה אַז מי נעמט אָן די תורה הקדושה מער ניט ווי כפּשוטה, און דעם רמז דרוש סוד פון תורה וויל מען ניט וויסן, און מען איז זיך מתגאה מיט דער ידיעה פון פּשטות וואָס דאָס איז דער ר\"מ פון עמלק'ן, איז יעמולט טאַקע באמת מר, די סיבה אויף דעם איז, מחט שנמצאה בריאה, דער חטא וואָס איז אין ראי' – דער בעש\"ט האָט געטייטשט מחט לשון חטא, ריאה לשון ראי' – אַז מען קוקט מיט אַ שלעכט אייג אויף אַ אידן, אַז מען האָט אַ קושיא אויף אַ אידן וואָס זיין הנהגה איז ניט געפעלן בעדאַרפמען אים מוכיח זיין, ניט ח\"ו קוקן בעין רעה, און זיין אופגעבראַכט אויף אים, און פון דעם חטא הראי' ווערט דער פעלער פון דעם עמלק וואָס ער איז מטיל ספיקות אין אמונת ד'.\nר' יוחנן ור' אלעזר ורבי חנינא מכשרי, רבי שמעון בן לקיש ר' מני בר פטיש ורבי שמעון בן אליקים טרפי – דער בעש\"ט האָט מבאר געווען אַז די דריי וואָס זיינען מכשיר זיינען מצד מדת החסד, און די דריי וואָס זיינען מטריף איז שרש נשמתם פון מדת הגבורה און האָט געזאָגט אַז דאָס – די שרשי הנשמות – איז מרומז אין די נעמען, דערפאַר איז אין די אַלע דריי נעמען וואָס זיינען מכשיר איז פאַראַן אין יעדער נאָמען אַ רמז אויף חסד, אין נאָמען ר' יוחנן איז י' חנן, אין נאָמען ר' אלעזר אל עזר, ר' חנינא ל' חנינה, און אין די דריי נעמען וואָס זיינען<sup data-n=\"1\">263</sup>. . .<sup data-n=\"2\">264</sup>.",[["1","263","חסר הסיום."],["2","264","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' רעט."]]]]});
